  ('7468b046-a5c6-44b1-8f90-5ddfb9627f8b', 2872358, 'chal-2872358', 'ספר תורה לבן עם חריטת שם הילד על שחור', '<p>האירוע המרגש של בר המצווה או הברית זוכה למתנה מיוחדת שתלווה את הילד לכל החיים. ספר תורה לבן, עם כריכה איכותית ועיצוב נקי, מעוטר בחריטת שם הילד באותיות שחורות אלגנטיות. זוהי דרך נפלאה לחבר את הדור הצעיר למסורת, ליצור קשר אישי עם ספר הלימוד העתיק, ולהעניק מתנה בעלת משמעות רוחנית עמוקה ויופי נצחי.</p>', 'ספר תורה לבן ייחודי עם חריטת שם אישית - מתנה מושלמת לבר מצווה או לברית.', 329.0, NULL, NULL, 'instock', NULL, 'https://deyidkzuvwniioxjisdr.supabase.co/storage/v1/object/public/product-images/opt/593c552e7bf1b080209c03c2.webp', true, '2026-05-31T11:30:03.111272+00:00', '2026-07-12T17:37:19.989636+00:00'),
  ('74fa5089-fe1b-4cb6-92c7-5d1d322006b8', NULL, 'מזמור-לתודה-בלוק-אקריליק-מסגרת-כסף-21-סמ-80199', 'מזמור לתודה בלוק אקריליק מסגרת כסף 21 ס"מ', NULL, 'מזמור לתודה בלוק אקריליק מסגרת כסף 21 ס"מ', 270.0, NULL, 'UK80199', 'instock', NULL, 'https://deyidkzuvwniioxjisdr.supabase.co/storage/v1/object/public/product-images/opt/39df306aef016c40a4a80cf2.webp', true, '2026-06-04T09:45:17.183788+00:00', '2026-07-12T17:37:17.04806+00:00'),
  ('75786292-05d1-43c6-93eb-73629bb98a13', NULL, 'product-16', 'סידור כותל לגבר ג''ינס כחול כהה הטבעה בכסף', '<p>סידור כותל זה, המיועד לגבר המודרני, משלב אלגנטיות וסגנון. הכריכה המיוחדת מבד ג''ינס כחול כהה מעניקה לו מראה ייחודי ויוקרתי, תואמת לכל סגנון. במרכז הכריכה, הטבעת כסף אותנטית מוסיפה נופך קדושה ויופי נצחי, ומזמינה להתחבר למקום הקדוש ביותר. זהו לא רק סידור תפילה, אלא פריט אישי בעל משמעות עמוקה, המשלב מסורת עם עיצוב עכשווי, והופך כל תפילה לחוויה מיוחדת.</p>', 'סידור כותל מהודר לגבר, בשילוב מראה יוקרתי של ג''ינס כחול כהה והטבעת כסף מרהיבה. מתנה שתלווה אותו בכל תפילה.', 186.0, NULL, NULL, 'instock', NULL, 'https://deyidkzuvwniioxjisdr.supabase.co/storage/v1/object/public/product-images/opt/588e6d689296ee87bd899b30.webp', true, '2026-05-31T11:04:26.373999+00:00', '2026-07-12T17:37:14.19728+00:00'),
  ('757ed179-16be-4828-bcbf-c029e06a0b0c', 2871971, 'talit-2871971', 'טלית פלטניום תשבץ 100% צמר רחלים דגם כהנים עטרה פינות וגב בצבע קרם', '<p>טלית פלטניום זו, הנטווית מ-100% צמר רחלים איכותי, מציגה עיצוב תשבץ אלגנטי המוסיף נופך של יוקרה לכל תפילה. דגם "כהנים" המיוחד, עם עטרה, פינות וגב בגוון קרם עדין, משלב מסורת עתיקת יומין עם אסתטיקה מודרנית. התחושה הרכה והטבעית של הצמר מבטיחה נוחות מרבית, בעוד העיצוב המוקפד מחבר אותך לשורשים ולמורשת היהודית. מתנה מושלמת לאירוע משמעותי או תוספת יקרת ערך לארון הבגדים של כל מתפלל.</p>', 'טלית פלטניום בעיצוב תשבץ יוקרתי, 100% צמר רחלים טבעי. דגם כהנים עם עטרה, פינות וגב בגוון קרם עשיר.', 1572.0, NULL, NULL, 'instock', NULL, 'https://deyidkzuvwniioxjisdr.supabase.co/storage/v1/object/public/product-images/opt/ce71c4634d022a193d5a61f7.webp', true, '2026-05-31T11:10:09.145533+00:00', '2026-07-12T17:37:16.726415+00:00'),
  ('75b30a35-ad8f-416b-970d-3c3ea34ef0d9', 2872390, 'chal-2872390', 'כיסוי לטלית חלאקה לבן רקמה תכלת', '<p>הכיסוי לטלית חלאקה מעוצב בקפידה, בשילוב רקמת תכלת עדינה על גבי בד לבן ואיכותי. הוא נועד להכיל את הטלית של הגוזז, לשמור עליה במצבה הטוב ולהוסיף נופך של קדושה ויופי לרגע המיוחד של החלאקה. בד איכותי ומגע רך מבטיחים שהטלית תישמר מכל משמר, ועיצובו האלגנטי הופך אותו למזכרת יקרת ערך.</p>', 'כיסוי לטלית חלאקה מרהיב, רקום בעדינות בגווני תכלת, מושלם לשמירה על טלית הגוזז ולציון הרגע המיוחד.', 129.0, NULL, NULL, 'instock', NULL, 'https://deyidkzuvwniioxjisdr.supabase.co/storage/v1/object/public/product-images/opt/91abf560e06ad77ac7c4d6db.webp', true, '2026-05-31T11:30:03.111272+00:00', '2026-07-12T17:37:21.910827+00:00'),
