  ('76894ff2-f1b0-4c08-bebd-1aae308496d0', 2871356, 'talit-2871356', 'טלית דגם האש שלי', '<p>טלית "האש שלי" הינה יצירת אמנות רוחנית, המשלבת עיצוב עכשווי עם מסורת עתיקה. עשויה מחומרים משובחים במחזור ממוחשב, היא מונחת בנוחות על הכתפיים ומקרינה קדושה ויופי. דגם "האש שלי" נועד להדגיש את הלהט הפנימי והחיבור לרוחניות, והוא מהדורה מוגבלת שתעשיר כל תפילה.</p>', 'טלית "האש שלי": קדושה, עיצוב וחיבור רוחני. עשויה במחזור ממוחשב, מהדורה מוגבלת.', 571.43, 350.0, NULL, 'instock', NULL, 'https://deyidkzuvwniioxjisdr.supabase.co/storage/v1/object/public/product-images/opt/b708a7e24f8586df00a02d8d.webp', true, '2026-05-31T11:10:09.145533+00:00', '2026-07-12T17:37:13.710709+00:00'),
  ('7783a6bb-d598-4ece-9755-76f27e66ab34', 2433, 'מזוזה-פולימר-דמוית-בטון-שוק-זהב-12-סמ', 'מזוזה פולימר דמוית בטון, שוק זהב, 12 ס"מ', '<p>העניקו נופך של יוקרה וקדושה לביתכם עם מזוזה זו, המשלבת עיצוב תעשייתי מודרני עם שיק זהוב. עשויה פולימר איכותי בגימור דמוי בטון, היא מציעה עמידות לאורך שנים ומראה ייחודי. השוק המוזהב מוסיף נגיעה מלכותית, והגודל האידיאלי (12 ס"מ) הופך אותה למתאימה לכל פתח. מזוזה זו אינה רק אובייקט פונקציונלי, אלא גם פריט עיצובי שיעשיר את האסתטיקה של הבית ויזכיר לכם את קדושת המקום.</p>', 'מזוזה פולימר אלגנטית בגימור דמוי בטון עם טאץ'' יוקרתי של שוק זהב. מידה 12 ס"מ, מושלמת לכל דלת.', 152.0, 89.98, 'UK21353', 'instock', NULL, 'https://deyidkzuvwniioxjisdr.supabase.co/storage/v1/object/public/product-images/opt/4ca67ab93234ae5657b35d5b.webp', true, '2026-05-10T16:10:19.018791+00:00', '2026-07-12T17:37:17.089254+00:00'),
  ('77f5108f-542d-46a9-8e9f-3bf4648abc74', NULL, 'product-5', 'סידור מעוצב ברכת הכהנים לגבר צבע שחור מט', '<p>העניקו קדושה וסטייל לכל יום עם סידור ברכת הכהנים המעוצב לגבר. הכריכה היוקרתית בצבע שחור מט, עם הטקסט המוזהב, מוסיפה נופך של אלגנטיות מודרנית. הסידור מכיל את ברכת הכהנים בנוסח מדויק, ומגיע בכריכה עמידה ונעימה למגע. מתנה אידיאלית לגבר שמעריך איכות, קדושה ועיצוב. חוויה רוחנית מעוצבת.</p>', 'ברכת הכהנים בעיצוב יוקרתי לגבר. סידור תפילה אלגנטי בגוון שחור מט, משלים כל מראה.', 186.0, NULL, NULL, 'instock', NULL, 'https://deyidkzuvwniioxjisdr.supabase.co/storage/v1/object/public/product-images/opt/b81d30dd26e3e9e0098ba14b.webp', true, '2026-05-31T11:04:26.373999+00:00', '2026-07-12T17:37:13.729379+00:00'),
