  ('791cf4e9-dc95-475e-a956-6f0024d1d1f9', NULL, 'artj-uk67856', 'תיק מפואר לטלית דמוי עור שחור אותיות בולטות "יברכך" 36x29 ס"מ', '<p>העניקו לטלית שלכם את הכבוד הראוי לה עם תיק מהודר זה, עשוי דמוי עור שחור איכותי. עיטור האותיות הבולטות "יברכך" מעניק לו מראה יוקרתי ומרשים, ומבטיח הגנה מיטבית וסטייל לטלית שלכם. מידותיו הנדיבות (36x29 ס"מ) מתאימות לרוב הטליתות, והוא מהווה מתנה אידיאלית וברכה לכל אדם.</p>', 'תיק טלית מהודר מבד דמוי עור שחור, מקושט באותיות "יברכך" בולטות. מתנה מושלמת לשמירה על הטלית.', 357.14, NULL, 'UK67856', 'instock', NULL, 'https://deyidkzuvwniioxjisdr.supabase.co/storage/v1/object/public/product-images/opt/bdd2dff38433ad859d5f79ca.webp', true, '2026-05-31T11:25:25.72855+00:00', '2026-07-12T17:37:06.511741+00:00'),
  ('7a915830-29b4-489b-9eaa-fce31fe62675', NULL, 'ברכת-מזמור-לתודה-פולימר-19x26-סמ-80899', 'ברכת מזמור לתודה פולימר 19x26 ס"מ', NULL, 'ברכת מזמור לתודה פולימר 19x26 ס"מ', 202.0, NULL, 'UK80899', 'instock', NULL, 'https://deyidkzuvwniioxjisdr.supabase.co/storage/v1/object/public/product-images/opt/8a980d1a8e5894f0de30c4e9.webp', true, '2026-06-04T09:45:15.282361+00:00', '2026-07-12T17:37:17.304477+00:00'),
  ('7b5baf11-e48a-4701-ae3c-38d3dc78e82c', NULL, 'product-32', 'סידור מעוצב כתר מובלט לגבר ג''ינס כחול כהה', '<p>הכירו את סידור התפילה ''כתר'', פריט יודאיקה מיוחד שמשלב עיצוב עכשווי עם קדושה. הכריכה בגוון ג''ינס כחול כהה מעניקה מראה יוקרתי ויומיומי כאחד, בעוד כתר מוזהב מובלט מדגיש את עוצמת הקשר עם יראת שמיים. הסידור מכיל את כל התפילות החשובות, כתובות באותיות ברורות וקריאות, ומגיע באריזה מהודרת המתאימה למתנה.**</p>', 'סידור תפילה מהודר ''כתר'' לגבר, בעיצוב ג''ינס כחול כהה. שילוב של קלאסיקה מודרנית ורוחניות.', 186.0, NULL, NULL, 'instock', NULL, 'https://deyidkzuvwniioxjisdr.supabase.co/storage/v1/object/public/product-images/opt/45a7b0c013a6229eeaf6fbc4.webp', true, '2026-05-31T11:04:26.373999+00:00', '2026-07-12T17:37:15.031589+00:00'),
  ('7b667131-0760-4074-9bf6-44c36e0d1c46', 2174, 'נרתיק-למגילה-מעץ-ספרדי-עם-לוחית-גודל-31-ס', 'נרתיק למגילה מעץ ספרדי עם לוחית גודל 31 ס"מ / 12.2 אינץ''', '<p>הגנו על המגילה שלכם בנועם ואלגנטיות עם נרתיק זה, העשוי מעץ ספרדי איכותי. הלוחית המעוצבת מוסיפה נופך של תחכום, בעוד שהעץ עצמו מבטיח עמידות והגנה לאורך שנים. נרתיק זה אינו רק אביזר פרקטי, אלא גם תוספת אמנותית שתעשיר את ביתכם ותשמור על קדושת המגילה.</p>', 'נרתיק מעץ ספרדי מהודר למגילה, משלב עיצוב עשיר עם הגנה אופטימלית. נועד לשמור על יקר ערך.', 480.0, 399.98, 'UK82203', 'instock', NULL, 'https://deyidkzuvwniioxjisdr.supabase.co/storage/v1/object/public/product-images/opt/c9cfc2f0b476c8ea14671336.webp', true, '2026-05-10T16:10:19.018791+00:00', '2026-07-12T17:37:18.555549+00:00'),
  ('7bbcbf14-297c-4c65-9f89-4b428704761b', NULL, 'product-53', 'סידור לבת ישראל – אבן קורדרוי', '<p>סידור לבת ישראל - אבן קורדרוי. סידור תפילה מהודר זה, המיוצר מעור סוס איכותי ועמיד, מציע חוויה רוחנית מיוחדת. עיצובו האלגנטי והיוקרתי, בשילוב עם טקסטורת הקורדרוי המרשימה, הופכים אותו למתנה אידיאלית לכל בת ובחורה. הסידור מכיל את כל התפילות הדרושות, בנוסח עדות אשכנז, ומהווה ליווי קדוש בכל רגע.</p>', 'סידור ייחודי לבת ישראל, העשוי עור סוס איכותי ומרשים. מתנה מושלמת לכל אירוע, שמדגישה את יופייה וקדושתה.', 186.0, NULL, NULL, 'instock', NULL, 'https://deyidkzuvwniioxjisdr.supabase.co/storage/v1/object/public/product-images/opt/c63c3261dc42bc3e2b00ac1c.webp', true, '2026-05-31T11:04:26.373999+00:00', '2026-07-12T17:37:15.847263+00:00'),
  ('7c503a1c-6234-475f-8a5b-f0542bff16c0', 2872364, 'chal-2872364', 'ספר תורה לבן עם חריטת שם הילד על כסוף', '<p>הכירו את ספר התורה הלבן המרהיב, מתנה ייחודית שתלווה את יקיריכם לכל החיים. הספר מעוטר בחריטת שם אישית מכסף טהור, המוסיפה נופך של יוקרה ואישיות. עשוי מחומרים משובחים, הוא מבטיח עמידות ויופי לאורך שנים. זוהי לא רק מתנה, אלא זיכרון יקר ומקור גאווה, המושלם לבר מצווה, לידה או כל אירוע משמעותי אחר.</p>', 'ספר תורה לבן מהודר, עם שם הילד חרוט בכסף - מתנה אישית ומרגשת שמלווה לכל החיים.', 329.0, NULL, NULL, 'instock', NULL, 'https://deyidkzuvwniioxjisdr.supabase.co/storage/v1/object/public/product-images/opt/46375fae1e6deb210bde037b.webp', true, '2026-05-31T11:30:03.111272+00:00', '2026-07-12T17:37:06.825062+00:00'),
  ('7cb8b9b7-f0a0-414b-a4f0-26a11ca385c5', 2167, 'סט-תפילין-מעור-דמוי-עור-3629-סמ-עם-רקמה-2', 'סט תפילין מעור דמוי עור 36*29 ס"מ עם רקמה', '<p>העניקו לעצמכם או ליקירכם סט תפילין מיוחד ומרשים, העשוי מעור דמוי עור איכותי ועמיד. הסט כולל תפילין מהודרות בגודל 36*29 ס"מ, מעוטרות ברקמה עשירה ויוקרתית המוסיפה נופך של פאר וחן. תפילין אלו נועדו ללוות אתכם בכל יום, להזכיר לכם את הקשר העמוק לרוחניות ולהוסיף קדושה להדרתכם.</p>', 'סט תפילין מהודרים מעור דמוי עור איכותי, עם רקמה עשירה. גודל 36*29 ס"מ.', 357.14, NULL, 'UK65047', 'instock', NULL, 'https://deyidkzuvwniioxjisdr.supabase.co/storage/v1/object/public/product-images/opt/a205906404173e6906315754.webp', true, '2026-05-10T16:10:19.018791+00:00', '2026-07-12T17:37:16.198434+00:00'),
  ('7d6937ad-6d2a-4fee-a59b-38f6e24cc78a', NULL, 'artj-uk44509', 'תיק מפואר לטלית תפילין דמוי עור גוון שחור עם ידיות', '<p>העניקו כבוד מרבי לספרי התורה שלכם עם תיק מפואר זה, המעוצב במיוחד עבור טלית ותפילין. עשוי דמוי עור איכותי בגוון שחור עמוק, התיק משלב אלגנטיות עם עמידות. ידיות נוחות מאפשרות נשיאה קלה ובטוחה, בעוד העיצוב המוקפד מבטיח שהכל יישאר מוגן ומסודר. זוהי מתנה אידיאלית או דרך להעצים את החוויה האישית שלכם.</p>', 'תיק מהודר לדברי קדושה: טלית ותפילין. עשוי דמוי עור איכותי בגוון שחור אלגנטי, עם ידיות נוחות לנשיאה.', 357.14, NULL, 'UK44509', 'instock', NULL, 'https://deyidkzuvwniioxjisdr.supabase.co/storage/v1/object/public/product-images/opt/c7ef283fff8faeaf88f29bae.webp', true, '2026-05-31T11:25:25.72855+00:00', '2026-07-12T17:37:21.345897+00:00'),
  ('7db6607f-fc4f-442a-9c9a-6872879a4432', 2871368, 'talit-2871368', 'טלית דגם פאר זהב', '<p>טלית דגם פאר זהב היא יצירת אמנות לבושה. עשויה מכסף טהור 925, היא נוצרת בחיתוך לייזר מדויק המעניק לה מראה נקי ומודרני. עיטורי רקמה עשירים, המשולבים בחומרים איכותיים ובחוטי זהב אמיתי, מוסיפים עומק ויוקרה. זוהי טלית שתעניק הוד והדר לתפילה, תהיה מתנה מרגשת לחגיגות משמעותיות, ותלווה אתכם בשלבים החשובים של החיים.</p>', 'טלית דגם פאר זהב – עשויה כולה מכסף טהור 925, עם רקמה עשירה המשלבת חוט זהב אמיתי. מפוארת, אלגנטית ומרשימה.', 500.0, NULL, NULL, 'instock', NULL, 'https://deyidkzuvwniioxjisdr.supabase.co/storage/v1/object/public/product-images/opt/c90a37326c5ccd975c2e676e.webp', true, '2026-05-31T11:10:09.145533+00:00', '2026-07-12T17:37:12.349953+00:00'),
  ('7e8f2814-e97e-469c-a5a9-a4684c6060cd', 2871432, 'talit-2871432', 'טלית תשבץ  צמר פסים בצבע שחור', '<p>טלית תשבץ מרשימה זו, עשויה 100% צמר כבשים משובח, מציעה שילוב של מסורת ואיכות ללא פשרות. פסי הצמר השחורים האלגנטיים על רקע הצמר הלבן יוצרים מראה קלאסי ונצחי, המתאים לכל גבר. תחושת הצמר הטבעי על הגוף מעניקה תחושת חום, עוטפת ומרוממת, ומחברת את המתפלל אל קדושת התפילה. טלית זו היא מתנה מושלמת או תוספת יוקרתית לארון הבגדים של כל שומר מצוות.</p>', 'טלית צמר תשבץ בפסים שחורים קלאסיים. עשויה 100% צמר כבשים איכותי, לחוויית תפילה מרוממת.', 540.0, 450.0, NULL, 'instock', NULL, 'https://deyidkzuvwniioxjisdr.supabase.co/storage/v1/object/public/product-images/opt/293d03920ce8a423be3171de.webp', true, '2026-05-31T11:10:09.145533+00:00', '2026-07-12T17:37:12.40264+00:00'),
  ('7f4b89a9-53a3-4e7f-85e2-04af0261b247', 2871970, 'talit-2871970', 'טלית פלטניום תשבץ 100% צמר רחלים דגם האש שלי תוקד עטרה פינות וגב בצבע קרם', '<p>הטלית פלטניום "האש שלי תוקד" היא יצירת אמנות רוחנית, עשויה 100% צמר רחלים טהור, המבטיח תחושה נעימה ומכבדת. עיצובה הייחודי, עם הכתובת "האש שלי תוקד", מעניק לה משמעות עמוקה וחיבור אישי לתפילה. הפינות והגב, בצבע קרם רגוע, משלימים את המראה האלגנטי והנצחי. טלית זו אינה רק בגד, אלא שותפה לדרך בתפילותיכם, המחברת אתכם למסורת ולרוחניות.</p>', 'טלית פלטניום יוקרתית מצמר רחלים משובח, בעיצוב "האש שלי תוקד" הייחודי. עטרת פינות וגב בצבע קרם מושלמת לחוויה רוחנית.', 1572.0, NULL, NULL, 'instock', NULL, 'https://deyidkzuvwniioxjisdr.supabase.co/storage/v1/object/public/product-images/opt/f57cb144e59e12797c62f07c.webp', true, '2026-05-31T11:10:09.145533+00:00', '2026-07-12T17:37:16.758883+00:00'),
  ('7ff57178-5a99-42d9-b264-94dba75da3a2', 1020, 'כוס-קידוש-מניקל-15-סמ-עם-צלחת-מכילה-120-מל-4-06', 'כוס קידוש מניקל 15 ס"מ עם צלחת, מכילה 120 מ"ל / 4.06 אונקיות', '<p>העניקו קדושה מיוחדת לזמנים היקרים עם כוס קידוש מניקל מרהיבה זו, בגובה 15 ס"מ. עיצובה האלגנטי לצד הברק העדין של המניקל יוצרים ניגוד מושלם, והיא מלווה בצלחת תואמת המעצימה את יופייה. קיבולת של 120 מ"ל (4.06 אונקיות) הופכת אותה לאידיאלית לקידוש של שבתות וחגים, ומוסיפה חן ושמחה לכל מפגש משפחתי.</p>', 'כוס קידוש מניקל מהודרת, 15 ס"מ, מגיעה עם צלחת תואמת. מושלמת לקידוש בכל אירוע.', 253.0, 149.98, 'UK45394', 'instock', NULL, 'https://deyidkzuvwniioxjisdr.supabase.co/storage/v1/object/public/product-images/opt/85979de3009a3825a1906340.webp', true, '2026-05-10T16:10:19.018791+00:00', '2026-07-12T17:37:13.300328+00:00'),
  ('80423930-65b7-4f44-8382-01eaac54266c', NULL, 'cover-dark-navy-star-laser', 'כיסוי לטלית ותפילין - נייבי כהה מגן דוד לייזר', 'כיסוי איכותי לטלית ותפילין בגוון נייבי כהה עם הדפס לייזר של מגן דוד וכיתוב "שיוויתי ה'' לנגדי תמיד". הרקמה ניתנת ללייזר בשם בלבד.', 'נייבי כהה עם מגן דוד - לייזר', 429.0, 300.0, NULL, 'instock', NULL, 'https://deyidkzuvwniioxjisdr.supabase.co/storage/v1/object/public/product-images/opt/cae9ffbd7a9ab4c56ec6d7c7.webp', true, '2026-06-09T10:46:32.34945+00:00', '2026-07-12T17:37:08.790447+00:00'),
  ('8163216e-96e3-4030-a630-8ecd97d77414', 2147, 'סט-תפילין-דמוי-עור-3629-סמ', 'סט תפילין דמוי עור 36*29 ס"מ', '<p>העניקו לעצמכם או ליקיריכם סט תפילין מהודר, שעוצב בקפידה ובאסתטיקה מרשימה. דמוי העור האיכותי, בגודל 36x29 ס"מ, מעניק מראה יוקרתי ומונע בלאי מואץ. כל פרט בסט, מרצועות העור הסינתטי ועד לתאים המגנים על הקלף, תוכנן להבטיח נוחות מרבית ושימוש לאורך שנים. השקיעו במתנה בעלת משמעות רוחנית עמוקה, שתלווה אתכם בדרככם.</p>', 'סט תפילין יוקרתיות בדמוי עור, גודל 36x29 ס"מ. מתנה מושלמת לבר מצווה או לאירוע משמעותי.', 357.14, NULL, 'UK67632', 'instock', NULL, 'https://deyidkzuvwniioxjisdr.supabase.co/storage/v1/object/public/product-images/opt/a93af100953e7b98936adf5a.webp', true, '2026-05-10T16:10:19.018791+00:00', '2026-07-12T17:37:20.437007+00:00'),
  ('8206bd90-bf78-4df3-a01c-c664a736811b', 2871722, 'chal-2871722', 'סט חלאקה קלאסי דגם האש שלי רקמה כסופה וחריטה על המספריים', '<p>הפכו את טקס החלאקה לחוויה עוצרת נשימה עם סט ''האש שלי''. הסט המרהיב, הכולל מספריים עם חריטה אישית עדינה וכיסוי רקום בכסף נוצץ, משלב מסורת עתיקת יומין עם עיצוב בלתי נשכח. כל פריט עשוי בקפידה, נועד להפוך את האירוע הקדוש הזה למזכרת משפחתית יקרת ערך לדורי דורות. העיצוב הייחודי ישזור קסם של קדושה וגאווה ביום שבו ילדכם עובר את המצווה הראשונה.</p>', 'סט חלאקה ''האש שלי'': מסורת, יופי ואיכות ליום המיוחד. רקמה כסופה יוקרתית וחריטה אישית על המספריים.', 400.0, NULL, NULL, 'instock', NULL, 'https://deyidkzuvwniioxjisdr.supabase.co/storage/v1/object/public/product-images/opt/dc73b1294718422a10a22b60.webp', true, '2026-05-31T11:30:03.111272+00:00', '2026-07-12T17:37:21.64741+00:00'),
  ('84dac17a-e5b5-4526-b937-9093002eb989', NULL, 'groom-set-yaron-ben-dror', 'מארז לחתן - אפור מלאנז''', 'מארז חתן יוקרתי הכולל תיק טלית, תיק תפילין, כיפה וסידור עם רקמה אישית טלית צמר רכלים תשב"צ כולל עטרה ופינות ותיק תואם וכיפה תואמת עם אפשרות לרשום את השם בלייזר.', 'מארז חתן יוקרתי בגוון אפור מלאנז'' הכולל תיק טלית, תיק תפילין, כיפה וסידור עם רקמה אישית', 2000.0, 1400.0, NULL, 'instock', NULL, 'https://deyidkzuvwniioxjisdr.supabase.co/storage/v1/object/public/product-images/opt/8a190d342333e4548a7fd44e.webp', true, '2026-06-09T10:38:39.906587+00:00', '2026-07-12T17:37:06.962667+00:00'),
