  ('875ea734-ed7d-4efc-9c08-26eca77ef2bf', NULL, 'נטלה-מהודרת-מפולימר-14-סמ-דגם-7-40070', 'נטלה מהודרת מפולימר 14 ס"מ (דגם 7)', NULL, 'נטלה מהודרת מפולימר 14 ס"מ (דגם 7)', 185.0, NULL, 'UK40070', 'instock', NULL, 'https://deyidkzuvwniioxjisdr.supabase.co/storage/v1/object/public/product-images/opt/efc9bd88b0b7e4cbd20857f6.webp', true, '2026-06-04T09:45:21.452729+00:00', '2026-07-12T17:37:10.675884+00:00'),
  ('879d3bc4-35d5-450d-817f-2fa7d78de0b2', NULL, 'מזוזה-פולימר-בטון-שיש-גס-לבן-ש-ציפוי-כסף-15-סמ-21818', 'מזוזה "פולימר בטון" שיש גס לבן ש ציפוי כסף 15 ס"מ', NULL, 'מזוזה "פולימר בטון" שיש גס לבן ש ציפוי כסף 15 ס"מ', 135.0, NULL, 'UK21818', 'instock', NULL, 'https://deyidkzuvwniioxjisdr.supabase.co/storage/v1/object/public/product-images/opt/41c7d837f4a4534ce3a2cc83.webp', true, '2026-06-04T09:45:24.700991+00:00', '2026-07-12T17:37:10.024912+00:00'),
  ('882e608c-01a6-4751-9af0-90fe0cf17b17', NULL, 'product-50', 'סידור ויברך דוד – מוקה קורדרוי', '<p>הסידור ''ויברך דוד'' בגוון מוקה מציע חווית תפילה ייחודית ונעימה. העטיפה החיצונית מקטיפת קורדרוי רכה ויוקרתית, בגוון מוקה עמוק, מעניקה תחושה של חום ונוחות. הסידור כולל את כל התפילות החיוניות, כתובות באותיות ברורות וקריאות, ומעוצב כדי להפוך כל רגע של התבודדות לחוויה מעצימה. זהו פריט יודאיקה אלגנטי שמוסיף נופך של קדושה ויופי לסדר היום הרוחני.</p>', 'סידור ''ויברך דוד'' בגוון מוקה מפנק, עטוף בקטיפת קורדרוי רכה. מתנה מושלמת למתפלל או למתקדש.', 186.0, NULL, NULL, 'instock', NULL, 'https://deyidkzuvwniioxjisdr.supabase.co/storage/v1/object/public/product-images/opt/7402fa9e74850a3334e2e60f.webp', true, '2026-05-31T11:04:26.373999+00:00', '2026-07-12T17:37:15.607148+00:00'),
  ('88542f8e-abfd-4148-9bf9-c7150bff40e8', NULL, 'product-58', 'סידור מבד טוויד – צבע טורקיז מנטה', '<p>הכירו את סידור התפילה המרהיב שלנו, עטוף בבד טוויד איכותי בגוון טורקיז מנטה ייחודי. הטקסטורה העשירה של הבד מעניקה תחושה יוקרתית ונעימה לידיים, ומכניסה שלווה ללב. הסידור מכיל תפילות לימות חול, שבתות וחגים, כתוב באותיות ברורות וקריאות. זהו פריט עיצובי מרשים שישתלב נפלא בכל בית, וגם מתנה שתשאיר רושם לכל השנים.</p>', 'סידור תפילה מהודר בטקסטורת טוויד עשירה, בגוון טורקיז מנטה מרגיע. מתנה אידיאלית לכל בית יהודי.', 186.0, NULL, NULL, 'instock', NULL, 'https://deyidkzuvwniioxjisdr.supabase.co/storage/v1/object/public/product-images/opt/d4d32e109c9fa1a81ae5f06f.webp', true, '2026-05-31T11:04:26.373999+00:00', '2026-07-12T17:37:15.988908+00:00'),
  ('899e5078-4f95-4a29-a8ec-4bc90e20363b', 2872456, 'chal-2872456', 'סט חלאקה קלאסי דגם כתר רקמה כסופה חריטה על המספריים ונרתיק לתלתל', '<p>חוגגים בר מצווה? העניקו לחתן הבר מצווה שלכם מתנה לכל החיים עם סט החלאקה הקלאסי שלנו, דגם ''כתר''. הסט כולל מספריים איכותיות בעלות חריטה אישית, נרתיק מהודר לשמירה על המספריים, ותליון כתר יוקרתי המעוטר ברקמה כסופה. זהו לא רק סט לזכרונות מרגשים, אלא גם פריט עדין ומעוצב שישאר איתו לשנים רבות. הסט מגיע באריזה חגיגית, מוכן להעניק ולהתרגש.</p>', 'סט חלאקה יוקרתי לתינוק: מספריים עם חריטה אישית, נרתיק מעוצב ותליון כתר מזהב. מתנה מושלמת לבר מצווה.', 471.0, NULL, NULL, 'instock', NULL, 'https://deyidkzuvwniioxjisdr.supabase.co/storage/v1/object/public/product-images/opt/3c75bd6b7413891a01f05ae3.webp', true, '2026-05-31T11:30:03.111272+00:00', '2026-07-12T17:37:07.367451+00:00'),
  ('89aea257-9bc4-48a6-94bb-73d795cf57d7', 2870879, 'chal-2870879', 'סט חלאקה קלאסי דגם כתר רקמה כסופה', '<p>חגוג את רגע החלאקה המרגש עם סט "כתר רקמה כסופה", עיצוב קלאסי ומרהיב שהופך כל טקס לחוויה בלתי נשכחת. הסט, מעוטר ברקמה כסופה עשירה, מהווה מתנה אידיאלית לבר מצווה, המושלמת לבני משפחה וחברים המבקשים להעניק שי קלאסי ומהודר. עשוי מחומרים איכותיים, הוא ישמש זיכרון יפה לשנים רבות.</p>', 'סט חלאקה קלאסי "כתר רקמה כסופה" – מתנה יוקרתית ומכובדת לבר מצווה.', 357.0, NULL, NULL, 'instock', NULL, 'https://deyidkzuvwniioxjisdr.supabase.co/storage/v1/object/public/product-images/opt/2846824747440f17a792edf9.webp', true, '2026-05-31T11:30:03.111272+00:00', '2026-07-12T17:37:19.998273+00:00'),
  ('8a0947bf-dd44-4641-b37d-4cbe418bfd09', 2132, 'כוס-קידוש-קריסטל-באבא-סאלי-16-סמ-עם-אבני', 'כוס קידוש קריסטל "באבא סאלי" 16 ס"מ עם אבנים מכילה 130 מ"ל / 4.3 אונקיות', '<p>כוס קידוש יוקרתית עשויה קריסטל איכותי, מעוטרת בעבודת יד באבני חן נוצצות המעניקות לה מראה עשיר וייחודי. הכוס, בגובה 16 ס"מ, נושאת בחובה את הקשר הרוחני לבאבא סאלי זצ"ל, ומביאה ברכה ושפע לכל שולחן שבת וחג. היא מכילה כ-130 מ"ל, ונהדרת לשימוש בטקסי קידוש או כפריט אספנות בעל ערך סנטימנטלי ודתי.</p>', 'כוס קידוש קריסטל מרשימה עם עיטורי אבנים, המקשרת אותנו למורשתו של הבאבא סאלי זצ"ל.', 152.0, 129.98, 'UK42437', 'instock', NULL, 'https://deyidkzuvwniioxjisdr.supabase.co/storage/v1/object/public/product-images/opt/e769d2d65b059ed8be66a9cd.webp', true, '2026-05-10T16:10:19.018791+00:00', '2026-07-12T17:37:13.002095+00:00'),
  ('8a0a06b7-2a4a-4fd9-b706-bd8f52f670d9', 2871444, 'talit-2871444', 'טלית תשבץ  צמר פסים בצבע לבן עם עטרה לבנה יוקרתית יברכך ה'' וישמרך בצבע כסוף', '<p>טלית תשבץ מרשימה העשויה צמר איכותי, בצבע לבן טהור עם פסים עדינים המעניקים לה מראה אלגנטי. עטרת הטלית מפוארת, מעוטרת ברקמה כסופה נוצצת של הברכה "יברכך ה'' וישמרך", ומוסיפה נופך של קדושה. הטלית מגיעה במידות שונות ומתאימה לתפילה מכובדת ומרגשת.</p>', 'טלית תפילה לבנה יוקרתית, בשילוב פסי צמר עדינים.', 1286.0, NULL, NULL, 'instock', NULL, 'https://deyidkzuvwniioxjisdr.supabase.co/storage/v1/object/public/product-images/opt/944391c1eb65f73181b8eacf.webp', true, '2026-05-31T11:10:09.145533+00:00', '2026-07-12T17:37:17.251388+00:00'),
  ('8a3f382b-2252-4329-9f9f-67062c6985a6', 1089, 'כוס-קידוש-קריסטל-16-סמ-מכילה-100-מל-3-4-אונקיו-4', 'כוס קידוש קריסטל 16 ס"מ מכילה 100 מ"ל / 3.4 אונקיו', '<p>העניקו לטקס הקידוש שלכם נופך של אלגנטיות עם כוס קידוש קריסטל מרהיבה זו. גובהה 16 ס"מ והיא מכילה 100 מ"ל (3.4 אונקיות) של יין קדוש, בדיוק בכמות הנדרשת. הקריסטל הצלול והאיכותי משדר אור יפה ומדגיש את ברכת הקידוש. מתנה אידיאלית לכל בית יהודי, לחגים, לחתונות או לבר מצווה, המוסיפה יופי וקדושה לכל שולחן.</p>', 'כוס קידוש קריסטל מעוצבת, 16 ס"מ גובה, 100 מ"ל קיבולת. מתנה מושלמת לכל אירוע.', 156.0, 129.98, 'UK80044', 'instock', NULL, 'https://deyidkzuvwniioxjisdr.supabase.co/storage/v1/object/public/product-images/opt/e5b7cad1714d8c4d8caf0327.webp', true, '2026-05-10T16:10:19.018791+00:00', '2026-07-12T17:37:08.905546+00:00'),
  ('8b3a9656-27fe-490a-8aa3-e5d921eb80c1', NULL, 'artj-uk66529', 'תיק מפואר לטלית דמוי עור אפור אותיות בולטות', '<p>העניקו לטלית שלכם את הבית הראוי לה עם תיק מהודר זה. בעבודת יד מדמוי עור אפור איכותי, הוא מעוצב לשמירה אופטימלית על כיסוי התפילה שלכם. האותיות הבולטות מוסיפות נופך של פאר וייחודיות, והופכות אותו למתנה מושלמת או לפריט אישי יוקרתי. שמרו על הטלית שלכם במראה חדש ומכובד, לאורך שנים.</p>', 'תיק מהודר במיוחד לטלית, עשוי דמוי עור אפור אלגנטי עם אותיות בולטות. אידיאלי לשמירה על כיסוי התפילה שלך בכבוד.', 357.14, NULL, 'UK66529', 'instock', NULL, 'https://deyidkzuvwniioxjisdr.supabase.co/storage/v1/object/public/product-images/opt/54bb456e18ad4bf764f650dd.webp', true, '2026-05-31T11:25:25.72855+00:00', '2026-07-12T17:37:21.34446+00:00'),
  ('8b50c539-5a16-4a5b-bb6f-c2392b0f0da0', NULL, 'כיפה-קטיפה-ארט-מן-אותיות-בולטות-זהב-בבא-סאלי-פנינה-גודל-4-10522', 'כיפה קטיפה "ארט-מן" אותיות בולטות זהב "בבא סאלי" - פנינה (גודל 4)', NULL, 'כיפה קטיפה "ארט-מן" אותיות בולטות זהב "בבא סאלי" - פנינה (גודל 4)', 67.0, 40.0, 'UK10522', 'instock', NULL, 'https://deyidkzuvwniioxjisdr.supabase.co/storage/v1/object/public/product-images/opt/71989a898949c6ca3f2b045f.webp', true, '2026-06-04T09:45:17.788043+00:00', '2026-07-12T17:37:10.3279+00:00'),
  ('8bdcd8e1-4ffe-4018-9096-3f7e12119f2c', 2871920, 'talit-2871920', 'טלית פרימיום בחריטת לייזר בד תשבץ  100% צמר רחלים דגם שויתי במגוון צבעים', '<p>טלית מרהיבה זו, ארוגה בשיטת תשבץ מ-100% צמר רחלים טבעי ואיכותי, מציעה חוויה ייחודית של קדושה והדרה. דגם ''שויתי'' בחריטת לייזר מדויקת מוסיף נופך מודרני ומעודן, ומבטיח שכל פריט הוא יצירת אמנות. הזמינה במגוון צבעים עשירים, תלווה אתכם בתפילה ותעצים את החיבור הרוחני.</p>', 'טלית פרימיום אריגת תשבץ מ-100% צמר רחלים, עם דגם שויתי בחריטת לייזר. התגשמות ההוד והקדושה.', 1286.0, NULL, NULL, 'instock', NULL, 'https://deyidkzuvwniioxjisdr.supabase.co/storage/v1/object/public/product-images/opt/b982efc53f70b038a2904322.webp', true, '2026-05-31T11:10:09.145533+00:00', '2026-07-12T17:37:05.896514+00:00'),
  ('8c3d361f-7468-4e19-9583-2306fea6f4c0', NULL, 'קופת-צדקה-מאקריליק-נצנצים-זהב-13x13-סמ-42800', 'קופת צדקה מאקריליק נצנצים זהב 13x13 ס"מ', NULL, 'קופת צדקה מאקריליק נצנצים זהב 13x13 ס"מ', 143.0, NULL, 'UK42800', 'instock', NULL, 'https://deyidkzuvwniioxjisdr.supabase.co/storage/v1/object/public/product-images/opt/c8290aea67b7e9d2ee6d363a.webp', true, '2026-06-04T09:45:12.684915+00:00', '2026-07-12T17:37:19.386908+00:00'),
  ('8cc667b2-3462-428f-a356-8f40384dad7f', 2037, 'פמוטי-קריסטל-16-5-סמ-עם-לוחית-מתכת-קישוטי', 'פמוטי קריסטל 16.5 ס"מ עם לוחית מתכת - קישוטים', '<p>האירו ביתכם באור חגיגי עם פמוטי קריסטל מהודרים אלו. בגובה 16.5 ס"מ, הם משלבים בעדינות את הברק השקוף של הקריסטל עם לוחית מתכת מעוטרת, המוסיפה נופך מלכותי. מושלמים להדלקת נרות שבת ויום טוב, הם ייצרו אווירה חמה ומכובדת בכל חדר. עיצובם הקלאסי והחומרים האיכותיים מבטיחים שהם יהפכו לפריט נצחי בביתכם, המעורר קדושה ויופי.</p>', 'פמוטי קריסטל אלגנטיים בגודל 16.5 ס"מ, משולבים עם לוחית מתכת מעוטרת. תוספת מושלמת לכל בית יהודי.', 216.0, 179.98, 'UK40449', 'instock', NULL, 'https://deyidkzuvwniioxjisdr.supabase.co/storage/v1/object/public/product-images/opt/763bd0ba0d1c3fa2cdac0bb8.webp', true, '2026-05-10T16:10:19.018791+00:00', '2026-07-12T17:37:19.51067+00:00'),
