  ('8d640972-f316-4a41-91e7-414823128949', 2073, 'תצוגת-ספסלי-לוסיט-18x13-סמ-עם-6-ברכות-אשכנז', 'תצוגת ספסלי לוסיט 18X13 ס"מ עם 6 ברכות - אשכנז', '<p>הוסיפו נגיעה של יוקרה וקדושה לביתכם עם ספסל הלוסיט המרהיב שלנו, בגודל 18X13 ס"מ. הספסל מעוטר ב-6 ברכות בנוסח אשכנזי, חרוטות בדיוק ובטוב טעם על חומר לוסיט איכותי ושקוף. הוא משמש כאלמנט עיצובי מרשים ואלגנטי, וגם כמקור השראה והתבוננות יומיומית. מתנה מושלמת לכל אירוע משמעותי, המשלבת יופי, מסורת ואיכות.</p>', 'ספסל לוסיט מעוצב עם 6 ברכות, תוספת אלגנטית לכל בית יהודי. מתנה מרשימה ומלאת משמעות.', 216.0, 179.98, 'UK42563', 'instock', NULL, 'https://deyidkzuvwniioxjisdr.supabase.co/storage/v1/object/public/product-images/opt/971e679589f9d6cb4cd8c3ee.webp', true, '2026-05-10T16:10:19.018791+00:00', '2026-07-12T17:37:20.387365+00:00'),
  ('8f095bd8-1ab3-4fb0-8275-df1b1f8e0cfb', 1150, 'כוס-קידוש-קריסטל-16-סמ-מכילה-100-מל-3-4-אונקיו-3', 'כוס קידוש קריסטל 16 ס"מ מכילה 100 מ"ל / 3.4 אונקיות', '<p>הגבירו את קדושת השבת והחג עם כוס קידוש קריסטל מפוארת זו. בגובה 16 ס"מ ובנפח 100 מ"ל, היא מעוצבת בקפידה להכיל את יין הקידוש שלכם במדויק. הקריסטל הצלול מנצנץ באור, מעניק לברכה נוכחות חגיגית ומרשימה. מתנה מושלמת לכל בית יהודי, שמשדרגת כל סעודה.</p>', 'כוס קידוש קריסטל מהודרת, 16 ס"מ גובה, 100 מ"ל נפח. מושלמת לקידוש בליל שבת וביום טוב.', 168.0, 139.98, 'UK80055', 'instock', NULL, 'https://deyidkzuvwniioxjisdr.supabase.co/storage/v1/object/public/product-images/opt/e5b7cad1714d8c4d8caf0327.webp', true, '2026-05-10T16:10:19.018791+00:00', '2026-07-12T17:37:08.905546+00:00'),
  ('8f3eb2b8-e1c8-4c2f-b606-6827edaf64d1', 2136, 'סט-הבדלה-קריסטל-20-סמ', 'סט הבדלה קריסטל 20 ס"מ', '<p>האירו את סיום השבת עם סט ההבדלה המרהיב שלנו, עשוי מקריסטל איכותי וצלול, בגובה 20 ס"מ. כל פריט בסט – הכוס המפוארת, הפמוט המיוחד, ומספר הבשמים – תוכנן בקפידה ליצירת אווירה של קדושה והוד. ברגע ההבדלה, האור יעבור דרך הקריסטל ויצור משחקי אור קסומים, תוספת של יופי וזוהר לטקס השבועי. סט זה הוא מתנה מושלמת לכל בית יהודי, המוסיף שיק ומשמעות לכל קבלת שבת.</p>', 'סט הבדלה קריסטל 20 ס"מ – חוויה מסנוורת לסיום השבת. פריט שידור משמעותי ומנצנץ.', 408.0, 339.98, 'UK80063', 'instock', NULL, 'https://deyidkzuvwniioxjisdr.supabase.co/storage/v1/object/public/product-images/opt/6fa7b3f7074cf31e09883409.webp', true, '2026-05-10T16:10:19.018791+00:00', '2026-07-12T17:37:20.290253+00:00'),
  ('8f7ad6e1-1f72-4473-8f09-d6baa29e88e6', 1984, 'פמוטים-פולימריים-18-סמ', 'פמוטים פולימריים 18 ס"מ', '<p>הוסיפו נגיעה של חום ואור לביתכם עם פמוטי השבת האלה, בגובה 18 ס"מ, העשויים פולימר איכותי. עיצובם האלגנטי משתלב בכל סגנון, והחומר העמיד מבטיח הנאה לשנים רבות. נהדרים להדלקת נרות שבת, ימי הולדת או כפריט דקורטיבי מושך. העניקו או קבלו מתנה מיוחדת שתיצור אווירה קדושה ושמחה.</p>', 'פמוטי שבת קסומים מפו לימר, 18 ס"מ גובה. מוסיפים אור וחן לכל שולחן. מתנה מושלמת לבית חדש או לכל אירוע.', 192.0, 159.98, 'UK47379', 'instock', NULL, 'https://deyidkzuvwniioxjisdr.supabase.co/storage/v1/object/public/product-images/opt/2ce6dedd0bd1ef4353def2d5.webp', true, '2026-05-10T16:10:19.018791+00:00', '2026-07-12T17:37:11.803614+00:00'),
