  ('935d7a79-7740-474e-9402-0ab4b538c29b', 2216, 'ברכון-לוסייט-בגודל-16x21-ס״מ-תפילה-לכלה', 'ברכון לוסייט בגודל 16×21 ס״מ – תפילה לכלה', '<p>ברכון יפהפה זה, בגודל 16x21 ס"מ, נועד לשאת את התפילה המרגשת לכלה ביום חופתה. הוא עשוי מנייר איכותי ומעוצב בקפידה, עם עיטורים עדינים המוסיפים לו הדר ויוקרה. ברכון זה הוא יותר מסתם פריט יודאיקה, הוא זיכרון מתוק ומרגש ליום המיוחד, מתנה אישית ומשמעותית לכלה, שתלווה אותה שנים רבות.</p>', 'ברכון מהודר ללוויה, מעוצב במיוחד לתפילה לכלה. גודל 16x21 ס"מ, מתנה מרגשת לכלות ולמשפחות.', 84.0, 49.98, 'UK48864', 'instock', NULL, 'https://deyidkzuvwniioxjisdr.supabase.co/storage/v1/object/public/product-images/opt/e078b582e98467f1a9fde09f.webp', true, '2026-05-10T16:10:19.018791+00:00', '2026-07-12T17:37:13.118743+00:00'),
