  ('94cd0c4d-d5d7-496a-8d22-23cbe4ac5083', NULL, 'מזוזה-פולימר-בטון-ברכת-הבית-גוון-טבעי-24443', 'מזוזה "פולימר בטון" ברכת הבית גוון טבעי', NULL, 'מזוזה "פולימר בטון" ברכת הבית גוון טבעי', 114.0, NULL, 'UK24443', 'instock', NULL, 'https://deyidkzuvwniioxjisdr.supabase.co/storage/v1/object/public/product-images/opt/c685228f1fab4394a0a909f9.webp', true, '2026-06-04T09:45:25.714918+00:00', '2026-07-12T17:37:09.739364+00:00'),
  ('94eaf5be-322d-429e-a42a-38ce506bb7a8', 2872391, 'chal-2872391', 'כיסוי לטלית חלאקה לבן רקמה שחורה', '<p>הכיסוי לטלית חלאקה לבן יוצר אווירה של קדושה וריגוש עבור אירוע החלאקה. עשוי מבד איכותי, הוא מעוטר ברקמה שחורה עדינה, המוסיפה נופך של יוקרה וכבוד. כיסוי זה הוא הרבה יותר מפריט לבוש; הוא מזכרת יקרת ערך שתלווה את הילד בצעדיו הראשונים למצוות, ותזכיר לו את היום המיוחד והברכה שהתלוותה אליו. מתנה אידיאלית למשפחות החוגגות את המצווה הראשונה של בנם.</p>', 'כיסוי טלית מהודר לזכר החלאקה, מעוטר ברקמה שחורה. מתנה מושלמת ליום המיוחד.', 129.0, NULL, NULL, 'instock', NULL, 'https://deyidkzuvwniioxjisdr.supabase.co/storage/v1/object/public/product-images/opt/4112d09afc4fc6998197d86c.webp', true, '2026-05-31T11:30:03.111272+00:00', '2026-07-12T17:37:07.766467+00:00'),
  ('967f2707-9bdd-4fdb-a868-cfd54da03210', NULL, 'product-62', 'סידור מבד טוויד – צבע קאמל', '<p>הכירו את הסידור החדש שלנו, עטוף בבד טוויד משובח בצבע קאמל מהודר. הוא משלב פשטות אלגנטית עם עמידות לאורך זמן, והופך כל רגע של תפילה לחוויה של סטייל ומקוריות. הבד הרך והנעים למגע, יחד עם העיצוב המוקפד, הופכים אותו למתנה מושלמת לעצמכם ולאהובים. סידור זה הוא בן לוויה אידיאלי לזמני התפילה בבית, בעבודה או בדרכים.</p>', 'סידור תפילה יומיומי במראה יוקרתי. עשוי בד טוויד איכותי בגוון קאמל, מושלם לבית ולדרך.', 186.0, NULL, NULL, 'instock', NULL, 'https://deyidkzuvwniioxjisdr.supabase.co/storage/v1/object/public/product-images/opt/3a35e907524516d8e965d1f8.webp', true, '2026-05-31T11:04:26.373999+00:00', '2026-07-12T17:37:16.440758+00:00'),
  ('96a82f67-9f7b-40ab-927f-10223eab11ad', 2872439, 'chal-2872439', 'סט חלאקה קלאסי דגם פרי רקמה בצבע שמנת', '<p>חגגו את יום החלאקה של ילדכם עם סט ''פרי'' המעוצב בקפידה. רקמת פרי עדינה ובצבע קרם טבעי מעניקה לסט מראה קלאסי ויוקרתי, המתאים באופן מושלם לטקס המרגש. הסט עשוי מחומרים איכותיים, כולל טלית רכה ומגבת מכותנה נעימה, ומגיע בקופסת מתנה מהודרת. עיצוב שלא רק שומר על המסורת, אלא גם משדרג אותה ברכות ובסטייל.</p>', 'סט חלאקה קלאסי ''פרי'' - רקמה עדינה בלבן שמנת, מתנה מושלמת ליום המיוחד. שמרו על המסורת באלגנטיות.', 357.0, NULL, NULL, 'instock', NULL, 'https://deyidkzuvwniioxjisdr.supabase.co/storage/v1/object/public/product-images/opt/eb8ca204e9cbd602c0a21da5.webp', true, '2026-05-31T11:30:03.111272+00:00', '2026-07-12T17:37:21.733899+00:00'),
  ('96d7c4ab-b011-4fc8-9274-0685352da1c8', 2399, 'מזוזה-אלומיניום-לבנה-12-סמ-שוק-מודפס-שחו', 'מזוזה אלומיניום לבנה 12 ס"מ, שוק מודפס שחור', '<p>הוסיפו נגיעה של יופי וקדושה למפתן הבית עם מזוזה זו, העשויה אלומיניום איכותי בגוון לבן נקי. השוק המודפס בשחור מוסיף ניגוד עדין ומודרני, והגודל האידיאלי של 12 ס"מ מתאים לרוב המשקופים. זוהי מתנה נפלאה לבית חדש, או דרך להעשיר את האווירה הרוחנית בכל חדר.</p>', 'מזוזה אלומיניום לבנה, 12 ס"מ, עם שוק מודפס בשחור - תוספת עיצובית ומרשימה לבית', 24.0, 19.98, 'UK28686', 'instock', NULL, 'https://deyidkzuvwniioxjisdr.supabase.co/storage/v1/object/public/product-images/opt/7ba24f5a50578838a32633bf.webp', true, '2026-05-10T16:10:19.018791+00:00', '2026-07-12T17:37:19.12904+00:00'),
  ('9707504a-b93f-4b36-b81c-dd921f985734', NULL, 'מזוזה-סמנט-בטון-האש-שלי-רחבה-24849', 'מזוזה "סמנט בטון" "האש שלי" רחבה', NULL, 'מזוזה "סמנט בטון" "האש שלי" רחבה', 135.0, NULL, 'UK24849', 'instock', NULL, 'https://deyidkzuvwniioxjisdr.supabase.co/storage/v1/object/public/product-images/opt/22f99708f338260a8bcb20c9.webp', true, '2026-06-04T09:45:26.108869+00:00', '2026-07-12T17:37:11.231942+00:00'),
  ('9753e0ba-fe98-473d-88b8-13463028f8b5', 2377, 'מזוזה-מפלסטיק-לבנה-עם-פקק-גומי-12-סמ-הכו', 'מזוזה מפלסטיק לבנה עם פקק גומי 12 ס"מ - "הכותל" עם שוק כסף', '<p>מזוזה זו, עשויה פלסטיק איכותי בגימור לבן נקי, מציגה עיטור מרשים של ''הכותל המערבי'', המוסיף נופך של קדושה והיסטוריה לכל פתח. הפקק העליון עשוי גומי עמיד, המבטיח הגנה מיטבית למגילה בפנים, בעוד שוק הכסף מוסיף אלגנטיות ועומק לעיצוב. בגודל 12 ס"מ, היא מתאימה למגוון רחב של משקופים. מזוזה זו היא לא רק חפץ יודאיקה, אלא סמל לחיבור עמוק למסורת, המביא ברכה, שלום והגנה לכל בית יהודי.</p>', 'מזוזה לבנה מפלסטיק בעיצוב ''הכותל'' עם שוק כסף, 12 ס"מ. הוסיפו ברכה והגנה לביתכם.', 26.0, 21.98, 'UK23104', 'instock', NULL, 'https://deyidkzuvwniioxjisdr.supabase.co/storage/v1/object/public/product-images/opt/9672de4c592cd6e442dbab80.webp', true, '2026-05-10T16:10:19.018791+00:00', '2026-07-12T17:37:20.817443+00:00'),
  ('98f39765-45a7-4c33-9905-de9bc16b51be', 2871400, 'talit-2871400', 'טלית דגם האש שלי זהב עם עטרה לבנה יוקרתית רקמת האש שלי בזהב', '<p>טלית "האש שלי" היא יצירת אמנות המשדרגת כל תפילה. עשויה מבד משובח, היא מתהדרת בעיטור רקמת "האש שלי" בחוטי זהב נוצצים, המוסיפה מימד של הדר והוד. העטרה הלבנה, עשירה בפרטים, משלימה את המראה היוקרתי. טלית זו אינה רק פריט לבוש, אלא סמל לתשוקה רוחנית ואסתטיקה מרהיבה, ליצירת חיבור עמוק יותר בין האדם לקדושה.</p>', 'טלית "האש שלי" - עיצוב יוקרתי בזהב עם עטרה לבנה רקמה. להוסיף טאץ'' של קדושה לארון הבגדים', 714.0, NULL, NULL, 'instock', NULL, 'https://deyidkzuvwniioxjisdr.supabase.co/storage/v1/object/public/product-images/opt/e56175d4fbcde088bc5c8e2a.webp', true, '2026-05-31T11:10:09.145533+00:00', '2026-07-12T17:37:12.135406+00:00'),
  ('99b7216f-c6fb-4e6c-9467-221c3744a5fb', NULL, 'artj-uk60304', 'סט תיק טלית תפילין פיו שחור יברכך אותיות בולטות זהב', '<p>הסט המרהיב הזה לתיק טלית ותפילין, בשילוב פיו שחור אלגנטי ואותיות ''יברכך'' מוזהבות ובולטות, מעניק הגנה וסטייל לעטרות הקודש. עשוי מחומרים איכותיים ועמידים, התיק מעוצב לנוחות נשיאה ולאורך חיים. האותיות המוזהבות משרות קדושה ויוקרה, והעיצוב הייחודי שלו הופך אותו למתנה בלתי נשכחת לכל אירוע חשוב.</p>', 'סט מהודר לתיק טלית ותפילין, מעוצב בפיו שחור עם אותיות ''יברכך'' בזהב בולטות. מתנה מושלמת להתרגשות יומיומית.', 357.14, NULL, 'UK60304', 'instock', NULL, 'https://deyidkzuvwniioxjisdr.supabase.co/storage/v1/object/public/product-images/opt/21bc68a70b273f0440c2492b.webp', true, '2026-05-31T11:25:25.72855+00:00', '2026-07-12T17:37:06.569535+00:00'),
  ('99c84dfc-ba7a-4c6f-9fb4-a83d54d2f836', NULL, 'גביע-קידוש-גימור-ניקל-פיליגרין-עם-ברכה-ויכלו-עם-תחתית-15-סמ-47925', 'גביע קידוש גימור ניקל פיליגרין עם ברכה "ויכלו" עם תחתית 15 ס"מ', NULL, 'גביע קידוש גימור ניקל פיליגרין עם ברכה "ויכלו" עם תחתית 15 ס"מ', 236.0, NULL, 'UK47925', 'instock', NULL, 'https://deyidkzuvwniioxjisdr.supabase.co/storage/v1/object/public/product-images/opt/fab0c2a0f6acc2b7211d7fee.webp', true, '2026-06-04T09:45:22.89473+00:00', '2026-07-12T17:37:09.925789+00:00'),
  ('99f56425-25e8-49b8-8289-3e84ad95614b', NULL, 'cover-blue-star-laser', 'כיסוי לטלית ותפילין - כחול מגן דוד לייזר', 'כיסוי איכותי לטלית ותפילין בגוון כחול עם הדפס לייזר של מגן דוד וכיתוב "שיוויתי ה'' לנגדי תמיד". הרקמה ניתנת ללייזר בשם בלבד.', 'כחול עם מגן דוד - לייזר', 429.0, 300.0, NULL, 'instock', NULL, 'https://deyidkzuvwniioxjisdr.supabase.co/storage/v1/object/public/product-images/opt/a413e40d65c71ccc0f664870.webp', true, '2026-06-09T10:46:32.34945+00:00', '2026-07-12T17:37:08.179242+00:00'),
  ('9a21800c-5736-4ca6-897b-b84a415eebac', 2224, 'מזוזה-מפלסטיק-עם-פקק-גומי-15-סמ-מתכת-צבוע', 'מזוזה מפלסטיק עם פקק גומי 15 ס"מ מתכת צבועה תלת מימדית', '<p>הוסיפו נגיעה של קודש ויופי לביתכם עם מזוזה איכותית זו, באורך 15 ס"מ. עשויה פלסטיק עמיד ומעוטרת בעיצוב תלת-ממדי מרשים של מתכת צבועה, המוסיף עומק ונוכחות. הפקק המגנטי מבטיח אטימה מושלמת לשמירה על הקלף. מתנה אידיאלית לכל בית, לחיזוק הקשר למסורת וליופי היהודי.</p>', 'מזוזה מפלסטיק 15 ס"מ בעיצוב תלת ממדי מהודר. מתנה מושלמת לכל בית יהודי.', 18.0, 14.98, 'UK23862', 'instock', NULL, 'https://deyidkzuvwniioxjisdr.supabase.co/storage/v1/object/public/product-images/opt/72f6a6c5b0390bb63f98ca20.webp', true, '2026-05-10T16:10:19.018791+00:00', '2026-07-12T17:37:20.575398+00:00'),
  ('9b30409a-c2d4-4eb9-94b3-d825d2c28f43', NULL, 'product-10', 'סידור מעוצב האש שלי לגבר ג''ינס שחור', '<p>הכירו את סידור התפילה "האש שלי", דגם ג''ינס שחור לגברים, שילוב מנצח של קדושה וסטייל. הסידור מעוצב בהשראת בד הג''ינס האייקוני, בגוון שחור עמוק, ומעניק מראה מודרני ואורבני. הוא עשוי מחומרים איכותיים ועמידים, נוח לנשיאה ולשימוש יומיומי. סידור זה הוא יותר מסתם ספר תפילה, הוא הצהרה אישית של אמונה וזהות, מתנה מושלמת לאיש הערך בחייכם, שיעטר כל בית כנסת או חדר.</p>', 'סידור תפילה "האש שלי" לגבר - עיצוב ג''ינס שחור ייחודי, מתנה מרשימה לכל גבר.', 186.0, NULL, NULL, 'instock', NULL, 'https://deyidkzuvwniioxjisdr.supabase.co/storage/v1/object/public/product-images/opt/f0969d1b5175b3321019f1a2.webp', true, '2026-05-31T11:04:26.373999+00:00', '2026-07-12T17:37:14.069767+00:00'),
  ('9c2650e8-00ec-41c5-98aa-2d879aaa55b0', 2871980, 'talit-2871980', 'טלית פלטניום תשבץ 100% צמר רחלים דגם שויתי עטרה פינות וגב בצבע תכלת', '<p>טלית פלטניום זו, עשויה 100% צמר רחלים איכותי, מציעה חוויה של קדושה ויופי בתפילה. עיצוב התשבץ המיוחד, בתוספת עטרת ''שויתי'' עשירה, פינות מעוצבות וגב מגובס, כולם בצבע תכלת עדין, הופכים אותה לפריט ייחודי. הטלית משלבת מסורת עם עיצוב מודרני, ומאפשרת להתעטף בחן ובהוד בכל תפילה.</p>', 'טלית פלטניום בעיצוב תשבץ, 100% צמר רחלים משובח. עטרת שויתי, פינות וגב בצבע תכלת מוסיפים קדושה ויופי.', 1572.0, NULL, NULL, 'instock', NULL, 'https://deyidkzuvwniioxjisdr.supabase.co/storage/v1/object/public/product-images/opt/581d63f21b5cc845ff2a933e.webp', true, '2026-05-31T11:10:09.145533+00:00', '2026-07-12T17:37:16.840442+00:00'),
  ('9c9f9557-d32b-474f-9342-906682d1b8d3', NULL, 'product-61', 'סידור מבד טוויד – צבע כחול נייבי', '<p>הסידור במראה יוקרתי, עטוף בבד טוויד משובח בגוון כחול נייבי עמוק. הבד המיוחד, בעל הטקסטורה המורגשת, מעניק תחושה חמה ומזמינה, ומשדרג כל תפילה לחוויה אישית ונעימה. הוא אידיאלי לנשיאה יומיומית, ומהווה מתנה מרגשת לכל אדם שאוהבים.</p>', 'סידור תפילה מהודר בבד טוויד כחול נייבי – מגע של אלגנטיות ליום יום.', 186.0, NULL, NULL, 'instock', NULL, 'https://deyidkzuvwniioxjisdr.supabase.co/storage/v1/object/public/product-images/opt/ea331ef017249b1687812ae0.webp', true, '2026-05-31T11:04:26.373999+00:00', '2026-07-12T17:37:16.417796+00:00'),
  ('9ccc25b4-8537-4ad7-b66c-f2f639af2ebb', 2871380, 'talit-2871380', 'טלית דגם פאר שחור', '<p>טלית דגם פאר שחור היא ביטוי מרהיב של מסורת ועידון. עשויה מצמר רחלים 100% איכותי, היא נשפכת ברכות ובעדינות, ומעניקה תחושת קדושה והגנה. עיצובה הקלאסי, עם פסי הזהב העדינים המשולבים באריגה, מקנה לה מראה יוקרתי ומרשים. טלית זו אינה רק בגד אלא הצהרה של אמונה, והיא תלווה את בעליה ברגעי התפילה החשובים ביותר, והופכה לחלק בלתי נפרד מחייהם הרוחניים.</p>', 'טלית דגם פאר שחור - עשויה צמר רחלים משובח, בעיצוב קלאסי ומכובד. מושלמת לבר מצווה, חתונות או כמתנה יוקרתית.', 500.0, NULL, NULL, 'instock', NULL, 'https://deyidkzuvwniioxjisdr.supabase.co/storage/v1/object/public/product-images/opt/f33c30b6237b43b5672258bd.webp', true, '2026-05-31T11:10:09.145533+00:00', '2026-07-12T17:37:05.630469+00:00'),
  ('9d31c5cf-7faa-4eb4-9e68-e17c6288275c', 1169, 'מזרקת-יין-קריסטל-3325-סמ-עם-8-כוסות-קטנות', 'מזרקת יין קריסטל 33*25 ס"מ עם 8 כוסות קטנות', '<p>הוסיפו נגיעה של אלגנטיות וקסם לכל אירוע עם מזרקת היין הקריסטלית המרהיבה שלנו. בגודל מרשים של 33*25 ס"מ, היא מגיעה עם 8 כוסות קטנות תואמות, המאפשרות חלוקה נוחה ומסוגננת של משקה. עשויה מקריסטל איכותי, מזרקה זו לא רק מושכת את העין אלא גם מבטיחה עמידות לאורך שנים. מתאימה לאירוח בארוחות חג, שמחות משפחתיות, או כמתנה בלתי נשכחת ומיוחדת.</p>', 'מזרקת יין קריסטל מהודרת, 33*25 ס"מ, עם 8 כוסות קטנות. העיצוב המושלם לאירוח חגיגי או מתנה יוקרתית.', 576.0, 479.98, 'UK42356', 'instock', NULL, 'https://deyidkzuvwniioxjisdr.supabase.co/storage/v1/object/public/product-images/opt/a2c34e09f99e34b2036b9376.webp', true, '2026-05-10T16:10:19.018791+00:00', '2026-07-12T17:37:19.713173+00:00'),
  ('9d32bd38-e49d-4ebd-a541-8baf9f92bfb9', NULL, 'product-43', 'סידור מעוצב מזמור לתודה לגבר צבע ג''ינס כהה', '<p>סידור תפילה אלגנטי ומרשים, המעוצב במיוחד לגברים, עם כריכת דמוי עור איכותית ונעימה למגע בצבע ג''ינס כהה. הסידור מכיל את כל תפילות השבת והחגים, ומעוצב בכתב ברור וקריא. מתנה מושלמת לבר מצווה, חתונה, יום הולדת או כל אירוע חשוב אחר, המבטאת הערכה וכבוד.</p>', 'סידור יוקרתי "מזמור לתודה" לגבר, בעיצוב מהודר ובצבע ג''ינס כהה.', 186.0, NULL, NULL, 'instock', NULL, 'https://deyidkzuvwniioxjisdr.supabase.co/storage/v1/object/public/product-images/opt/3808d6a82bbe4510398ced44.webp', true, '2026-05-31T11:04:26.373999+00:00', '2026-07-12T17:37:15.537366+00:00'),
  ('9dbf9d40-7973-40b3-a888-3377e47bd742', NULL, 'esh-sheli-silver-ring-diamonds', 'טבעת כסף "האש שלי" משובצת יהלומים', 'טבעת "האש שלי" מכסף 925 משובצת אבני זרקון מבריקות בעיצוב להבה. ניתן להזמין במידות שונות.<br><br><strong>המחיר משתנה לפי שער הכסף.</strong><br>לתיאום הזמנה ובחירת מידה - צרו קשר בטלפון או בוואטסאפ.', 'טבעת "האש שלי" מכסף 925 משובצת אבני זרקון בעיצוב להבה. ✦ המחיר משתנה לפי שער הכסף.', 0.0, NULL, NULL, 'instock', NULL, 'https://deyidkzuvwniioxjisdr.supabase.co/storage/v1/object/public/product-images/opt/0766d9a66befb08f15b81d64.webp', true, '2026-06-24T12:36:25.537318+00:00', '2026-07-12T17:37:19.088518+00:00'),
  ('9de36442-deee-4e40-809d-206748a98c43', 2148, 'מחזיק-בסמים-מזכוכית-עם-לוחית-מתכת-עיצו', 'מחזיק בסמים מזכוכית עם לוחית מתכת, עיצובים שונים 6 ס"מ', '<p>העניקו לביתכם נופך של אלגנטיות עם מחזיק בשמים זכוכית מעוצב. הלחונית השקופה מדגישה את יופיו של הנוזל, בעוד הלוחית המתכתית המוסיפה טאץ'' יוקרתי. מושלם להוספת ניחוח עדין של שמנים אתריים או בושם לכל חדר. פריט דקורטיבי ושימושי כאחד, שמשתלב נפלא בכל סגנון עיצוב.</p>', 'קישוט מסוגנן ושימושי לבית: מחזיק בשמים מזכוכית שקופה עם לוחית מתכת מעוצבת. מושלם להוספת ניחוח נעים וטאץ'' אישי לחלל.', 26.0, 21.98, 'UK44756', 'instock', NULL, 'https://deyidkzuvwniioxjisdr.supabase.co/storage/v1/object/public/product-images/opt/6b5fcbfb70626da4fd960b21.webp', true, '2026-05-10T16:10:19.018791+00:00', '2026-07-12T17:37:20.53432+00:00'),
  ('9dfea5ce-f0d3-4331-bd0c-9c574d4e0d7b', 2198, 'טלית-דמוי-עור-סט-תפילין-3629-סמ-עם-רקמה-לבן', 'טלית דמוי עור - סט תפילין 36*29 ס"מ עם רקמה - לבן', '<p>הכירו את סט התפילין המרהיב שלנו, מעוצב בקפידה מחומר דמוי עור איכותי בלבן נקי ומזמין. גודלו הנדיב (36*29 ס"מ) מבטיח נוחות וכיסוי מיטבי בזמן התפילה. העיטורים ברקמה עדינה מוסיפים נופך של קדושה והוד, והופכים אותו למתנה מושלמת או לפריט אישי שיעטר את בית הכנסת. חוו טקסטיל תפילה שמחבר בין מסורת ליוקרה.</p>', 'סט תפילין יוקרתי דמוי עור, בגודל 36*29 ס"מ, עם רקמה מרשימה. מושלם לכל תפילה.', 357.14, NULL, 'UK65778', 'instock', NULL, 'https://deyidkzuvwniioxjisdr.supabase.co/storage/v1/object/public/product-images/opt/b150e19be04098a1abbaef1d.webp', true, '2026-05-10T16:10:19.018791+00:00', '2026-07-12T17:37:05.849852+00:00'),
  ('9f7eac52-0088-42d0-9933-ca523691c0d0', 2871932, 'talit-2871932', 'טלית פרימיום בחריטת לייזר בד תשבץ  100% צמר רחלים דגם האש שלי תוקד במגוון צבעים', '<p>טלית צמר רחלים יוקרתית, ארוגה בדוגמת תשבץ עשירה ומעוטרת בחריטת לייזר עדינה של הפסוק "האש שלי תוקד", המעניק לה נוכחות ומסתורין. ארוגה מ-100% צמר רחלים טהור, היא מבטיחה אווריריות, רכות ונוחות מרבית בעת התפילה. כל טלית מגיעה במגוון צבעים המתאימים לטעמכם האישי, והיא מתנה מושלמת ומרגשת לכל גבר.</p>', 'טלית פרימיום בתשבץ, 100% צמר רחלים, בחריטת לייזר "האש שלי תוקד". חוויה רוחנית ייחודית.', 1286.0, NULL, NULL, 'instock', NULL, 'https://deyidkzuvwniioxjisdr.supabase.co/storage/v1/object/public/product-images/opt/1166b63dcf865b098dd3b773.webp', true, '2026-05-31T11:10:09.145533+00:00', '2026-07-12T17:37:17.140023+00:00'),
  ('9faeddba-6a6b-48d6-a1dd-ec46afd9a7d9', NULL, 'product-30', 'סידור כתר לגבר שחור הטבעה בזהב', '<p>סידור תפילה ''כתר'' לגבר, עשוי עור שחור איכותי ונעים למגע. על הכריכה חרוטה הטבעת זהב יוקרתית, המוסיפה נופך של פאר וקדושה. סידור זה ישמש את בן הזוג, האב או החבר בתפילותיו היומיומיות, ויהווה משנה תפילה ייחודי ומרשים. הפנים עשיר בתפילות בנוסח אחיד, בתוספת פיוטים ופסקאות מיוחדות, הכתובים באותיות ברורות וקריאות.</p>', 'סידור כתר להגבר - עור שחור יוקרתי עם הטבעת זהב מרהיבה. מתנה מושלמת לגבר המודרני.', 186.0, NULL, NULL, 'instock', NULL, 'https://deyidkzuvwniioxjisdr.supabase.co/storage/v1/object/public/product-images/opt/33df1a6f143ed91dcc939c8d.webp', true, '2026-05-31T11:04:26.373999+00:00', '2026-07-12T17:37:14.883098+00:00'),
