  ('a1a9ffaf-b1bb-451f-93d2-62185a71bddb', 900, 'כוס-קידוש-ניקל-נהרות-התנך-מכילה-120-מל-4-06-א-2', 'כוס קידוש ניקל "נהרות התנ"ך" מכילה 120 מ"ל / 4.06 אונקיות', '<p>כוס קידוש זו, עשויה ניקל איכותי, מעוצבת בהשראת נהרות התנ"ך, סמל לחיים, טוהר והתחדשות.  בנפח של 120 מ"ל, היא אידיאלית לקידוש של שבת וחג, ומשלבת עיצוב מודרני עם עומק רוחני.  הברק של הניקל מוסיף יוקרה לכל שולחן, מה שהופך אותה למתנה מושלמת או תוספת יפה לאוסף שלכם.</p>', 'כוס קידוש ניקל "נהרות התנ"ך" - 120 מ"ל. חיבור מודרני למקורות קדושים.', 202.0, 119.98, 'UK41533', 'instock', NULL, 'https://deyidkzuvwniioxjisdr.supabase.co/storage/v1/object/public/product-images/opt/93512bf14b0996e6908aa6b4.webp', true, '2026-05-10T16:10:19.018791+00:00', '2026-07-12T17:37:13.338919+00:00'),
  ('a1ddcf39-6a62-4fa7-ba20-d4f4f76324f4', 2063, 'פמוטי-קריסטל-8-ברנצים-25-סמ-עם-לוחית-מתכת', 'פמוטי קריסטל 8 ברנצ''ים 25 ס"מ עם לוחית מתכת', '<p>האירו את ביתכם באור יקרות עם פמוטי קריסטל מהודרים אלו, עוצרי נשימה בגובה 25 ס"מ ועיצובם בעל 8 ברנצ''ים. כל פמוט מעוטר בלוחית מתכת עדינה, המשווה לו מראה מלכותי ומעודן. עשויים מחומרים איכותיים, הם מבטיחים שימוש לאורך שנים והופכים כל הדלקת נרות למעמד מיוחד ומרשים. מתנה אידיאלית לכל אירוע משמעותי, או פינוק אישי שיוסיף חן ויוקרה לכל חלל.</p>', 'פמוטי קריסטל מפוארים עם 8 ברנצ''ים ועיטורי מתכת, בגובה 25 ס"מ. תוספת אלגנטית לכל בית יהודי.', 360.0, 299.98, 'UK47192', 'instock', NULL, 'https://deyidkzuvwniioxjisdr.supabase.co/storage/v1/object/public/product-images/opt/a9fb9cad2216f6047b1c6962.webp', true, '2026-05-10T16:10:19.018791+00:00', '2026-07-12T17:37:09.346337+00:00'),
  ('a3edd859-9827-4353-8347-0d013b12e6ee', NULL, 'product-51', 'סידור ויברך דוד – שחור', '<p>הכירו את סידור "ויברך דוד" בעיצוב שחור, היוצר אווירה של קדושה ועומק. הסידור מכיל את כל התפילות בנוסח עשיר ומדויק, כתוב באותיות ברורות ובפריסה נוחה לקריאה. הכריכה השחורה, בעלת מגע יוקרתי, משלימה את המראה המכובד. סידור זה הוא בן לוויה מושלם לתפילות היומיום, לשבתות ולחגים, ומעניק חוויה רוחנית מעמיקה.</p>', 'סידור "ויברך דוד" בשחור: נוסח עשיר, עיצוב אלגנטי. לכל תפילה, בכל יום.', 186.0, NULL, NULL, 'instock', NULL, 'https://deyidkzuvwniioxjisdr.supabase.co/storage/v1/object/public/product-images/opt/eddaa127b8eb1899060cb68a.webp', true, '2026-05-31T11:04:26.373999+00:00', '2026-07-12T17:37:15.876532+00:00'),
  ('a4922852-d2e3-47a7-9fca-ad4c46512e37', 2191, 'סט-תפילין-מעור-דמוי-עור-3629-סמ-עם-רקמה', 'סט תפילין מעור דמוי עור 36*29 ס"מ עם רקמה', '<p>סט תפילין זה, עשוי בעבודת יד מעור דמוי עור משובח, משלב יופי מסורתי עם עיצוב מודרני. הרקמה המיוחדת על הדפנות מוסיפה נופך יוקרתי ומותאם אישית. בגודל 36*29 ס"מ, התפילין נוחים לנשיאה ולתפילה יומיומית. זוהי מתנה משמעותית ומרגשת שתלווה את בעליה בנאמנות בכל צעדיו.</p>', 'תפילין מעור איכותי, מעוצבות עם רקמה מהודרת. גודל 36*29 ס"מ. מתנה מושלמת לכל גיל.', 357.14, NULL, 'UK67506', 'instock', NULL, 'https://deyidkzuvwniioxjisdr.supabase.co/storage/v1/object/public/product-images/opt/056334cb6bac07f6558b809d.webp', true, '2026-05-10T16:10:19.018791+00:00', '2026-07-12T17:37:09.49592+00:00'),
  ('a49a9c54-cf36-42f6-a3e5-a91a3afaf7d0', NULL, 'נטלה-מהודרת-מפולימר-14-סמ-דגם-4-48990', 'נטלה מהודרת מפולימר 14 ס"מ (דגם 4)', NULL, 'נטלה מהודרת מפולימר 14 ס"מ (דגם 4)', 185.0, NULL, 'UK48990', 'instock', NULL, 'https://deyidkzuvwniioxjisdr.supabase.co/storage/v1/object/public/product-images/opt/79d6a1314e7bbdd8a1ad9476.webp', true, '2026-06-04T09:45:20.440038+00:00', '2026-07-12T17:37:08.566442+00:00'),
  ('a542a9cc-f29a-4939-9823-7fd1f9e00798', 2872409, 'chal-2872409', 'סט חלאקה פרימיום דגם כתר מגן דוד רקמה שחורה', '<p>חגגו את רגע החלאקה המשמעותי עם סט "כתר מגן דוד" היוקרתי. הסט המפואר, הכולל חלוק, כיסוי ראש ושאר אביזרי חלאקה נדרשים, מעוצב בקפידה עם רקמה שחורה אלגנטית המשלבת את סמל מגן דוד. עשוי מבדים איכותיים ונעימים למגע, הסט מבטיח נוחות מירבית לילדכם ברגעיו הראשונים הייחודיים. העיצוב הייחודי והאיכות הבלתי מתפשרת הופכים אותו למזכרת יקרה לשנים הבאות, ומתנה מושלמת להורים.</p>', 'סט חלאקה פרימיום "כתר מגן דוד" - תפארת ליום המיוחד, מעוצב עם רקמה שחורה בלתי נשכחת. מתנה יוקרתית לילדכם.', 900.0, NULL, NULL, 'instock', NULL, 'https://deyidkzuvwniioxjisdr.supabase.co/storage/v1/object/public/product-images/opt/4998feab0c8866231aa714b8.webp', true, '2026-05-31T11:30:03.111272+00:00', '2026-07-12T17:37:07.418337+00:00'),
  ('a6a90a49-b295-4f1e-a930-101dc839ef79', NULL, 'product-46', 'סידור מעוצב מזמור לתודה לגבר צבע שחור', '<p>הוסיפו קדושה ויוקרה לשגרת התפילה עם סידור "מזמור לתודה" המעוצב לגבר. כרוך בעור שחור איכותי, הוא משלב חומרי גלם משובחים עם עיצוב מינימליסטי ואלגנטי. זוהי מתנה מושלמת ואישית שתלווה אותו בכל תפילה, ותפיץ ניחוח של מסורת וסטייל. סידור זה נועד להעצים את חווית התפילה ולהוסיף טאץ'' של הוד לכל רגע.</p>', 'סידור תפילה "מזמור לתודה" לגבר - עיצוב יוקרתי בשחור.', 186.0, NULL, NULL, 'instock', NULL, 'https://deyidkzuvwniioxjisdr.supabase.co/storage/v1/object/public/product-images/opt/aa8d5376239408fa913feaf7.webp', true, '2026-05-31T11:04:26.373999+00:00', '2026-07-12T17:37:15.601631+00:00'),
  ('a71e07e3-2f26-4891-b138-296bbb291028', 1221, 'סט-הבדלה-מתומן-מניקל-4-יחידות', 'סט הבדלה מתומן מניקל 4 יחידות', '<p>הוסיפו קסם ונוכחות לטקס ההבדלה עם סט ההבדלה המתומן המרהיב הזה. עשוי מניקל איכותי, הסט כולל ארבעה חלקים מעוצבים ומגש תואם, המשלבים יופי מסורתי עם עיצוב מודרני. הוא מושלם להשלמת יופייה של שבת בביתכם או כמתנה יוקרתית ומכובדת לאהוביכם. הרגישו את החיבור למסורת בכל נגיעה.</p>', 'סט הבדלה מתומן מניקל 4 חלקים - מסורת אלגנטית לכל שבת.', 360.0, 299.98, 'UK40005', 'instock', NULL, 'https://deyidkzuvwniioxjisdr.supabase.co/storage/v1/object/public/product-images/opt/ebd6db4984fd00085fb3c926.webp', true, '2026-05-10T16:10:19.018791+00:00', '2026-07-12T17:37:11.690347+00:00'),
