  ('a8d60bb3-fe2a-4c3a-8896-482047d36774', NULL, 'artj-uk67701', 'תיק מפואר לטלית דמוי פשתן "יברכך" 31X38 ס"מ', '<p>שדרגו את חווית הנשיאה של טליתכם עם תיק יוקרתי זה, המעוצב בקפידה מדמוי פשתן איכותי. התיק, בגודל 31X38 ס"מ, מעוטר בהדפס "יברכך" המשרה קדושה, ומסמל ברכה והגנה. הוא נועד לשמור על הטלית שלכם מכובדת ומגוננת, בכל עת ובכל מקום. הבחירה האידיאלית לאלו המחפשים שילוב של פונקציונליות, אסתטיקה ומשמעות.</p>', 'תיק מהודר לדוגמה לפרוכת, מעוצב דמוי פשתן עם הדפס "יברכך" - יוקרה והגנה לתפילין.', 357.14, NULL, 'UK67701', 'instock', NULL, 'https://deyidkzuvwniioxjisdr.supabase.co/storage/v1/object/public/product-images/opt/481acc09327b14284d5baf64.webp', true, '2026-05-31T11:25:25.72855+00:00', '2026-07-12T17:37:06.762943+00:00'),
  ('a98ce224-37e2-4ca1-abf2-afe8e7052270', NULL, 'cover-black-circle', 'כיסוי טלית ותפילין שחור עם הטבעת מעגל - לייזר בלבד', NULL, 'כיסוי טלית ותפילין שחור עם עיטור מעגלי. הטבעת שם אישי בלייזר בלבד.', 429.0, 300.0, NULL, 'instock', NULL, 'https://deyidkzuvwniioxjisdr.supabase.co/storage/v1/object/public/product-images/opt/766302d29eb3876cdf884063.webp', true, '2026-06-09T10:43:24.061178+00:00', '2026-07-12T17:37:08.327508+00:00'),
  ('a9a90f47-0a5b-42fa-ac67-00c33ef757e4', NULL, 'כרית-מהודרת-לברית-דמוי-עור-בבא-סאלי-עם-אותיות-בולטות-74x50-סמ-45791', 'כרית מהודרת לברית דמוי עור "בבא סאלי" עם אותיות בולטות 74x50 ס"מ', NULL, 'כרית מהודרת לברית דמוי עור "בבא סאלי" עם אותיות בולטות 74x50 ס"מ', 428.57, NULL, 'UK45791', 'instock', NULL, 'https://deyidkzuvwniioxjisdr.supabase.co/storage/v1/object/public/product-images/opt/3f4e8f558bd597a334fc404e.webp', true, '2026-06-04T09:45:19.378157+00:00', '2026-07-12T17:37:12.921526+00:00'),
  ('aa4ef747-b5bc-4dab-a70e-0eab9c54aaaa', NULL, 'cover-cream-star-laser', 'כיסוי לטלית ותפילין - קרם מגן דוד לייזר', 'כיסוי איכותי לטלית ותפילין בגוון קרם בהיר עם הדפס לייזר של מגן דוד וכיתוב "שיוויתי ה'' לנגדי תמיד". הרקמה ניתנת ללייזר בשם בלבד.', 'קרם עם מגן דוד - לייזר', 429.0, 300.0, NULL, 'instock', NULL, 'https://deyidkzuvwniioxjisdr.supabase.co/storage/v1/object/public/product-images/opt/3e378a2e840b631d29674aa8.webp', true, '2026-06-09T10:46:32.34945+00:00', '2026-07-12T17:37:07.371076+00:00'),
  ('aaa88776-04e6-43ad-bf39-bdd4980e08b3', NULL, 'product-0', 'סידור מעוצב ברכת הכהנים לגבר ג''ינס כחול כהה', '<p>סידור תפילה ייחודי ומרשים, המשלב את ברכת הכהנים הקדושה עם עיצוב מודרני ואורבני. כריכת ג''ינס כחול כהה איכותית מעניקה לו מראה יומיומי ואלגנטי, מתאים לבית ולנסיעות. דפי הסידור עשירים בתוכן, עם פירוש קצר וברור, ומותאמים לנוחות תפילה מירבית. מתנה מושלמת לגבר המחפש חיבור רוחני בעל נוכחות, מבלי לוותר על סטייל.</p>', 'סידור ברכת הכהנים לגבר בעיצוב ג''ינס כחול כהה, מתנה יוקרתית ומקורית לכל גבר.', 186.0, NULL, NULL, 'instock', NULL, 'https://deyidkzuvwniioxjisdr.supabase.co/storage/v1/object/public/product-images/opt/8636052c25a2c9e04941d982.webp', true, '2026-05-31T11:04:26.373999+00:00', '2026-07-12T17:37:11.506529+00:00'),
  ('ac2f46a1-d7ba-41fe-a99e-ff6b9b759ff0', NULL, 'product-20', 'סידור כותל לגבר לבן הטבעה בזהב', '<p>סידור כותל יוקרתי לגבר, מעוצב בלבן קלאסי עם הטבעת זהב עדינה המעניקה לו מראה מלכותי. סידור זה נאסף בקפידה כדי להכיל את כל התפילות החשובות, מן הבוקר ועד הערב, ומעניק חווית תפילה אישית ומיוחדת אצלכם בבית או כמזכרת מרגשת מביקורכם בכותל המערבי. עשוי מחומרים איכותיים, זהו מתנה שתלווה אתכם לאורך שנים.</p>', 'סידור כותל לגבר – מהודר עם הטבעת זהב, המתנה המושלמת לתפילה ייחודית.', 186.0, NULL, NULL, 'instock', NULL, 'https://deyidkzuvwniioxjisdr.supabase.co/storage/v1/object/public/product-images/opt/40d0e16538cf96187cb1afec.webp', true, '2026-05-31T11:04:26.373999+00:00', '2026-07-12T17:37:14.520041+00:00'),
  ('ac5e2a7e-a495-4dc5-94ba-e78929bb705a', 2873740, 'talit-2873740', 'טלית פלטניום תשבץ 100% צמר רחלים דגם מגן דוד שויתי ה''  במגוון צבעים', '<p>עטפו את עצמכם בקדושה ויוקרה עם טלית הפלטניום שלנו, דגם מגן דוד. הטלית, עשויה 100% צמר רחלים משובח, מעוצבת בתשבץ מרהיב של ''שויתי ה'''', היוצר שילוב מושלם של אמירה אישית והגנה רוחנית. כל אריגה מספרת סיפור של מסורת עשירה, והעיצוב הייחודי הופך אותה מבטאת כבוד והדרה לתפילה. זמינה במגוון צבעים עשירים, לבחירתכם.</p>', 'טלית פלטניום מגן דוד: יוקרה, מסורת והגנה רוחנית. עשויה 100% צמר רחלים משובח, עם עיצוב תשבץ ייחודי ''שויתי ה'''' במגוון צבעים.', 1572.0, NULL, NULL, 'instock', NULL, 'https://deyidkzuvwniioxjisdr.supabase.co/storage/v1/object/public/product-images/opt/c982837809406611d96cb24a.webp', true, '2026-05-31T11:10:09.145533+00:00', '2026-07-12T17:37:21.277501+00:00'),
  ('ac9606a6-c167-49b0-b547-249e1b232076', NULL, 'נטלה-מהודרת-מפולימר-14-סמ-דגם-6-81420', 'נטלה מהודרת מפולימר 14 ס"מ (דגם 6)', NULL, 'נטלה מהודרת מפולימר 14 ס"מ (דגם 6)', 185.0, NULL, 'UK81420', 'instock', NULL, 'https://deyidkzuvwniioxjisdr.supabase.co/storage/v1/object/public/product-images/opt/b352a812e352a232ecb2469e.webp', true, '2026-06-04T09:45:20.824216+00:00', '2026-07-12T17:37:10.399585+00:00'),
  ('ac98cf78-74cc-4ff3-a282-7790d6d9dd9c', 1236, 'סט-הבדלה-קריסטל-20-סמ-3', 'סט הבדלה קריסטל 20 ס"מ', '<p>העניקו לטקס ההבדלה שלכם נופך של אלגנטיות נצחית עם סט קריסטל מרהיב זה. גובה 20 ס"מ, כל פריט נוצר בקפידה מחומרים איכותיים, המשדרים אור וטוהר. הברק העדין של הקריסטל משתלב באופן מושלם עם חום הנר והדרת היין, ומוסיף קסם מיוחד לרגע המפריד בין קודש לחול. מתנה אידיאלית לכל בית יהודי, המסמלת את קדושת השבת וההתחדשות לקראת השבוע החדש.</p>', 'סט הבדלה קריסטל 20 ס"מ – חותם יופי וקדושה על סיום השבת.', 456.0, 379.98, 'UK81770', 'instock', NULL, 'https://deyidkzuvwniioxjisdr.supabase.co/storage/v1/object/public/product-images/opt/429162b78c55ed8d95d29c84.webp', true, '2026-05-10T16:10:19.018791+00:00', '2026-07-12T17:37:11.758439+00:00'),
  ('ae4d5692-1dcd-450f-b620-accde0869887', NULL, 'artj-uk66469', 'תיק מפואר לטלית דמוי עור לבן אותיות בולטות "וי"', '<p>שדרגו את חווית הנשיאה של הטלית שלכם עם תיק מהודר זה, המעוצב בדמוי עור לבן איכותי. האות "וי" המוזהבת הבולטת מוסיפה נגיעה של יוקרה וקדושה. התיק מרווח ויגן על הטלית שלכם לאורך זמן, והוא הפריט המושלם להגעה לבית הכנסת או לשמירה עליה בבית. זהו לא רק תיק, אלא הצהרה של אמונה וכבוד.</p>', 'תיק טלית מהודר מעור לבן, מעוטר באות "וי" בולטת. מתנה מושלמת לכל אירוע.', 357.14, NULL, 'UK66469', 'instock', NULL, 'https://deyidkzuvwniioxjisdr.supabase.co/storage/v1/object/public/product-images/opt/e64e90bec277abb19656fd88.webp', true, '2026-05-31T11:25:25.72855+00:00', '2026-07-12T17:37:06.227303+00:00'),
  ('aebe4b82-cd52-4db6-af51-377d4ae5370b', NULL, 'artj-uk60458', 'תיק מפואר לטלית תפילין דמוי עור לבן "יברכך" 38X33 ס"מ', '<p>שדרגו את חווית הנשיאה של הטלית והתפילין עם תיק מהודר זה. עשוי דמוי עור איכותי בגוון לבן נקי, הוא ישמור על קדושת פרטי הטקס ויעניק להם מראה יוקרתי. הברכה "יברכך" רקום במרכז התיק, מוסיף נופך של קדושה והגנה. עם מידות נדיבות של 38X33 ס"מ, התיק מציע מקום נוח לטלית ותפילין, והופך למתנה מושלמת ואלגנטית לכל אירוע משמעותי.</p>', 'תיק מפואר לדברי קדושה – טלית ותפילין. עיצוב לבן יוקרתי עם ברכת "יברכך". מתנה מרגשת לכל גבר.', 357.14, NULL, 'UK60458', 'instock', NULL, 'https://deyidkzuvwniioxjisdr.supabase.co/storage/v1/object/public/product-images/opt/fcbc342335bdfdeefd2cd6aa.webp', true, '2026-05-31T11:25:25.72855+00:00', '2026-07-12T17:37:05.941799+00:00'),
