  ('af7ac312-0f49-40b2-a1c6-73058fca2aba', 2872407, 'chal-2872407', 'סט חלאקה פרימיום דגם כתר רקמה בכסף', '<p>חגגו את רגע החלאקה הראשונה של ילדכם בסט פרימיום אלגנטי, המשלב מסורת עשירה עם עיצוב מודרני. הסט ''כתר רקמה'' עשוי מכסף טהור, מעוטר בעבודת רקמה עדינה ויוקרתית, היוצרת מראה מלכותי ומיוחד. כל פריט בסט תוכנן בקפידה כדי להעניק חוויה חלקה ונעימה, ולהפוך את הרגע המרגש הזה למזכרת יקרת ערך שתלווה אתכם לשנים רבות.</p>', 'סט חלאקה יוקרתי ''כתר רקמה'' בכסף – לחוויה קסומה ובלתי נשכחת.', 586.0, NULL, NULL, 'instock', NULL, 'https://deyidkzuvwniioxjisdr.supabase.co/storage/v1/object/public/product-images/opt/e7d51cc3a03aa899796b7db2.webp', true, '2026-05-31T11:30:03.111272+00:00', '2026-07-12T17:37:08.527176+00:00'),
  ('afaae595-c120-40f1-b560-6f402f4b2d92', 2415, 'מזוזה-דמוית-אבן-פולימר-15-סמ-2', 'מזוזה דמוית אבן פולימר 15 ס"מ', '<p>העניקו לביתכם קדושה ויופי עם המזוזה המיוחדת שלנו, המעוצבת בדמות אבן טבעית. עשויה מחומר פולימר עמיד ואיכותי, בגובה 15 ס"מ, היא משלבת את המראה המרשים של אבן עם פרקטיות ותחזוקה קלה. כל פרט במזוזה עוצב בקפידה להעניק מראה אותנטי ומכובד, והיא תהווה תוספת נפלאה לכל פתח בבית, המזכירה את נצחיות המסורת ואת הברכה השורה בו.</p>', 'מזוזה מרשימה דמוית אבן, 15 ס"מ, תוסיף קדושה ויופי לביתך. מתנה מושלמת לכל בית יהודי.', 72.0, 59.98, 'UK24440', 'instock', NULL, 'https://deyidkzuvwniioxjisdr.supabase.co/storage/v1/object/public/product-images/opt/804bd6407913cd2446b3e4ad.webp', true, '2026-05-10T16:10:19.018791+00:00', '2026-07-12T17:37:19.218859+00:00'),
  ('afec9238-4d87-4894-b040-2a1c64cdd424', 2019, 'פמוטי-קריסטל-8-סמ-עם-לוחית-מתכת', 'פמוטי קריסטל 8 ס"מ עם לוחית מתכת', '<p>הוסיפו נגיעה של קסם ויוקרה לביתכם עם פמוטי קריסטל מרהיבים אלו, בגובה 8 ס"מ. כל פמוט מעוצב בקפידה משלב ברק קריסטלי צלול עם לוחית מתכת מעודנת, המוסיפה חותם של אלגנטיות מודרנית. הפמוטים הללו אינם רק כלי להדלקת נרות, אלא פריט עיצובי שיוסיף חום, אור ויופי לכל פינה בבית, משולחן השבת ועד למדף תצוגה. מתנה מושלמת לכל אירוע, המבטיחה להאיר ולשדרג כל חלל.</p>', 'פמוטי קריסטל מהודרים 8 ס"מ, משלבים ברק קריסטל עם נגיעת מתכת אלגנטית. מושלמים להוספת אור ויופי לכל חלל.', 169.0, 99.98, 'UK81087', 'instock', NULL, 'https://deyidkzuvwniioxjisdr.supabase.co/storage/v1/object/public/product-images/opt/9c94db5e62395304c96b7542.webp', true, '2026-05-10T16:10:19.018791+00:00', '2026-07-12T17:37:18.03285+00:00'),
  ('b0629a5c-248a-49e8-9482-1bdaf6ba4a9f', 2873174, 'talit-2873174', 'טלית פרימיום בחריטת לייזר בד תשבץ  100% צמר רחלים דגם מזמור לתודה במגוון צבעים', '<p>התעטפו בקדושה עם טלית פרימיום זו, עשויה 100% צמר רחלים משובח. בד התשבץ הייחודי בשילוב חריטת הלייזר העדינה של דגם ''מזמור לתודה'' מוסיף נופך של הוד והדר לתפילה. זמינה במגוון צבעים לבחירתכם, טלית זו היא לא רק פריט לבוש, אלא חוויה רוחנית עשירה ומזמינה.</p>', 'טלית פרימיום בתשבץ ובחריטת לייזר, 100% צמר רחלים. דגם ''מזמור לתודה'' - תוספת אלגנטית לתפילה.', 1286.0, NULL, NULL, 'instock', NULL, 'https://deyidkzuvwniioxjisdr.supabase.co/storage/v1/object/public/product-images/opt/b4d51bf7f05c8a1f9d629770.webp', true, '2026-05-31T11:10:09.145533+00:00', '2026-07-12T17:37:19.970611+00:00'),
