  ('b0f6cbb1-9a41-4220-ab92-f86539697f3a', 2873146, 'talit-2873146', 'טלית פרימיום בחריטת לייזר בד תשבץ  100% צמר רחלים דגם תיקון הכללי במגוון צבעים', '<p>קחו את התפילה שלכם לרמה חדשה עם טלית הפרימיום שלנו, עשויה 100% צמר רחלים טהור בבד תשבץ יוקרתי. חריטת לייזר מדויקת של ''תיקון הכללי'' מעטרת את הטלית, מוסיפה לה נופך של קדושה והוד. המגע הרך והאיכות הבלתי מתפשרת של הצמר הופכים כל תפילה לחוויה עשירה ומרגשת. זמין במגוון צבעים קלאסיים ומודרניים, זוהי מתנה מושלמת לעצמכם או ליקירכם.</p>', 'טלית פרימיום בתשבץ צמר רחלים טהור, עם חריטת לייזר מדויקת של ''תיקון הכללי''. בחרו מהמגוון הייחודי של צבעים – התחדשו או פנקו במתנה שלא תישכח.', 1286.0, NULL, NULL, 'instock', NULL, 'https://deyidkzuvwniioxjisdr.supabase.co/storage/v1/object/public/product-images/opt/27eb7eec67fac48324c9e76d.webp', true, '2026-05-31T11:10:09.145533+00:00', '2026-07-12T17:37:06.074652+00:00'),
  ('b110f4d1-c1ae-4d3d-900b-8455b55462f3', NULL, 'laser-misgan-haesek', 'משגן העסק - חיתוך לייזר', NULL, 'לוח אקרילי שקוף לברכת העסק בחיתוך לייזר', 357.0, NULL, NULL, 'instock', NULL, 'https://deyidkzuvwniioxjisdr.supabase.co/storage/v1/object/public/product-images/opt/8ecbc447496742d7d1f128c4.webp', true, '2026-06-21T12:45:15.77172+00:00', '2026-07-12T17:37:14.416349+00:00'),
  ('b112851a-b54e-42dc-8c17-e86668ee463b', NULL, 'product-7', 'סידור מעוצב ברכת הכהנים לגבר קורדרוי אפור כהה', '<p>הביאו קדושה וסטייל לכל בית עם סידור ברכת הכהנים היוקרתי שלנו. מעוצב במיוחד עבור הגבר הישראלי, הוא עשוי קורדרוי אפור כהה ועשיר, המעניק לו מראה מודרני ואלגנטי. הסידור כולל את ברכת הכהנים הנוגעת ללב, המעוטרת במילים עדינות ובמבנה מסורתי. זוהי מתנה מושלמת לבר מצווה, חתונה, או כל אירוע חשוב, שתלווה את יקירכם ברכה והגנה.</p>', 'סידור ברכת הכהנים מעוצב לגבר, בקורדרוי אפור. מתנה יוקרתית ומרגשת לכל אירוע.', 186.0, NULL, NULL, 'instock', NULL, 'https://deyidkzuvwniioxjisdr.supabase.co/storage/v1/object/public/product-images/opt/388effb103b0cc24f31fdef8.webp', true, '2026-05-31T11:04:26.373999+00:00', '2026-07-12T17:37:13.784958+00:00'),
