  ('b658fff2-b6bf-4754-a8ca-8a298d90f8fb', NULL, 'artj-uk60305', 'סט תיק טלית תפילין פיו לבן יברכך אותיות בולטות זהב', '<p>העניקו קדושה והדר לציוד התפילה שלכם עם סט תיק טלית ותפילין מרהיב זה. התיק, מעוצב בגוון לבן טהור, מתחדש באותיות "יברכך" מוזהבות ובולטות, המעניקות לו נופך של עושר ורוחניות. פיו לבן תואם משלים את העיצוב המלוטש. תפירה איכותית וחומרים עמידים מבטיחים שהסט ישמש אתכם לשנים רבות, וישמור על קדושת טלית ותפילין באופן מכובד.</p>', 'סט מהודר לתיק טלית ותפילין, מעוצב באותיות זהב בולטות "יברכך" על רקע לבן אלגנטי. הפיו הלבן משלים את המראה המיוחד.', 357.14, NULL, 'UK60305', 'instock', NULL, 'https://deyidkzuvwniioxjisdr.supabase.co/storage/v1/object/public/product-images/opt/0926fde1dde01daa4afa1c2f.webp', true, '2026-05-31T11:25:25.72855+00:00', '2026-07-12T17:37:06.670886+00:00'),
  ('b6654317-e7db-4642-946f-8517adc8f34c', 2871969, 'talit-2871969', 'טלית פלטניום תשבץ 100% צמר רחלים דגם בבא סאלי עטרה פינות וגב בצבע קרם', '<p>טלית פלטניום "בבא סאלי" – יצירת אומנות של קדושה וענווה. עשויה 100% צמר רחלים איכותי, היא נושאת את ברכת העיטורים "בבא סאלי" המיוחדים, עם פינות ועטרה בצבע קרם עדין. כל השתפכות בתפילה בטלית זו מחברת בין מסורת עתיקה לאיכות בלתי מתפשרת, ומעניקה תחושת טוהר והגנה.</p>', 'טלית פלטניום מרשימה, 100% צמר רחלים, דגם ייחודי "בבא סאלי" עם עטרה ופינות בצבע קרם.', 1572.0, NULL, NULL, 'instock', NULL, 'https://deyidkzuvwniioxjisdr.supabase.co/storage/v1/object/public/product-images/opt/0981b8c61e7b3ac01ca81129.webp', true, '2026-05-31T11:10:09.145533+00:00', '2026-07-12T17:37:16.796305+00:00'),
  ('b6b147d5-0783-4fe8-9924-04174f46d694', 2176, 'סט-טלית-ותפילין-מעור-מלאכותי-3831-סמ-שחור', 'סט טלית ותפילין מעור מלאכותי 38*31 ס"מ - שחור עם אותיות מוטבעות', '<p>הסט המרהיב הזה, הכולל טלית ותפילין מעור מלאכותי איכותי, מציע שילוב מושלם בין מסורת לסטייל מודרני. הגודל המחושב (38*31 ס"מ) מבטיח נוחות ושימוש נגיש, בעוד הצבע השחור העמוק והאותיות המוטבעות מעניקים לו מראה יוקרתי ומכובד. מושלם להענקת מתנה משמעותית או לשימוש אישי, הסט הזה מחבר בין קדושת התפילה ליופי של עיצוב מוקפד.</p>', 'סט טלית ותפילין יוקרתי מעור מלאכותי. עיצוב אלגנטי בשחור עם אותיות מוטבעות, לאיכות ולמסורת.', 357.14, NULL, 'UK66922', 'instock', NULL, 'https://deyidkzuvwniioxjisdr.supabase.co/storage/v1/object/public/product-images/opt/76613b7aae001e2e95602af7.webp', true, '2026-05-10T16:10:19.018791+00:00', '2026-07-12T17:37:08.780032+00:00'),
  ('b6fd9cca-d80c-4203-91c3-907f12e81a2a', NULL, 'קופת-צדקה-אקריליק-האש-שלי-נצנצים-כסף-14-סמ-42770', 'קופת צדקה אקריליק "האש שלי" - נצנצים כסף 14 ס"מ', NULL, 'קופת צדקה אקריליק "האש שלי" - נצנצים כסף 14 ס"מ', 143.0, NULL, 'UK42770', 'instock', NULL, 'https://deyidkzuvwniioxjisdr.supabase.co/storage/v1/object/public/product-images/opt/2f447f363d2d55928171c6c1.webp', true, '2026-06-04T09:45:13.44789+00:00', '2026-07-12T17:37:19.421856+00:00'),
  ('b744edd4-1dc1-4a3c-8e34-2495522fe262', NULL, 'מסגרת-זכוכית-מהודרת-אשת-חיל-20x25-סמ-81986', 'מסגרת זכוכית מהודרת אשת חיל 20x25 ס"מ', NULL, 'מסגרת זכוכית מהודרת אשת חיל 20x25 ס"מ', 140.0, 110.0, 'UK81986', 'instock', NULL, 'https://deyidkzuvwniioxjisdr.supabase.co/storage/v1/object/public/product-images/opt/076529bd6a207a16fb50ec7a.webp', true, '2026-06-04T09:45:15.706104+00:00', '2026-07-12T17:37:10.111514+00:00'),
  ('b78024ba-7fbd-4a65-80ba-901c411b0b94', 2382, 'מזוזה-מפלסטיק-עם-פקק-גומי-15-סמ-הכותל-לב', 'מזוזה מפלסטיק עם פקק גומי 15 ס"מ - "הכותל" לבנה עם שוק כסף', '<p>הכניסו נגיעה ירושלמית לביתכם עם המזוזה הלבנה והיפהפייה הזו, המעוצבת בהשראת הכותל המערבי. גודלה 15 ס"מ, היא עשויה מפלסטיק איכותי ועמיד, ומגיעה עם פקק גומי נוח לסגירה. שוק הכסף המוזהב מוסיף לה ברק אלגנטי. זוהי מתנה מושלמת לכל בית, המסמלת שמירה, קדושה וחיבור עמוק לירושלים.</p>', 'מזוזה לבנה ומרשימה של הכותל, 15 ס"מ, מפלסטיק עם פקק גומי. מתנה נפלאה לבית חדש או לכל מי שרוצה להרגיש קרוב לירושלים.', 29.0, 23.98, 'UK23105', 'instock', NULL, 'https://deyidkzuvwniioxjisdr.supabase.co/storage/v1/object/public/product-images/opt/d8d75447715e012fb87bd224.webp', true, '2026-05-10T16:10:19.018791+00:00', '2026-07-12T17:37:19.112811+00:00'),
  ('b7a37d62-c550-4d3f-bfec-591fd060ee6b', 2209, 'בד-דמוי-עור-pu-טלית-2336-סמ-עם-ידית-שחור-עם-או', 'בד דמוי עור PU טלית 23*36 ס"מ עם ידית - שחור עם אותיות מובלטות', '<p>שדרגו את חווית נשיאת הטלית שלכם עם כיסוי מהודר זה, העשוי מבד דמוי עור PU איכותי ועמיד. בגודל נדיב של 23*36 ס"מ, הוא מתאים לרוב סוגי הטליתות, ומגיע עם ידית מחוזקת לנשיאה נוחה ובטוחה. הצבע השחור הקלאסי בשילוב עם אותיות מובלטות מוסיפים נופך של יוקרה וייחודיות, והופכים את הכיסוי הזה למתנה מושלמת לכל אירוע.</p>', 'כיסוי טלית מהודר מבד דמוי עור PU, בגודל 23*36 ס"מ, עם ידית נוחה לנשיאה. עיצוב שחור קלאסי עם אותיות מובלטות לחוויה יוקרתית.', 300.0, NULL, 'UK66589', 'instock', NULL, 'https://deyidkzuvwniioxjisdr.supabase.co/storage/v1/object/public/product-images/opt/ac3a8b1b590f0a7d766c0933.webp', true, '2026-05-10T16:10:19.018791+00:00', '2026-07-12T17:37:16.857403+00:00'),
  ('b7be1e85-9c46-4cbc-bae8-f72f44ceb2a5', 2872393, 'chal-2872393', 'סט חלאקה קלאסי דגם מגן דוד רקמה שחורה וחריטה על המספרים', '<p>חגגו את רגע הבר מצווה עם סט חלאקה קלאסי ומרגש, מעוצב בדגם מגן דוד מרהיב. הסט כולל תגלחת מיוחדת על המספרים, עם אפשרות לחריטה אישית שתנציח את התאריך המיוחד. הרקמה השחורה העשירה מעניקה נופך של יוקרה ומסורתיות, בעוד החומרים האיכותיים מבטיחים שימוש לאורך שנים. זוהי מתנה מושלמת ובלתי נשכחת לילד שגדל.</p>', 'סט חלאקה מגן דוד - חגיגה לבר המצווה בעיצוב מרשים עם רקמה שחורה וחריטה אישית על המספרים.', 400.0, NULL, NULL, 'instock', NULL, 'https://deyidkzuvwniioxjisdr.supabase.co/storage/v1/object/public/product-images/opt/fde44228870e1922331cc9da.webp', true, '2026-05-31T11:30:03.111272+00:00', '2026-07-12T17:37:21.674975+00:00'),
  ('b7d2a9a2-c062-496d-b48a-0204cd53f26d', 2871393, 'talit-2871393', 'טלית דגם האש שלי זהב עם עטרה שחורה יוקרתית רקמת האש שלי בזהב', '<p>הטלית ''האש שלי'' היא יצירת אמנות ייחודית, שבה רקמת אש מוזהבת מתעוררת לחיים על גבי בד איכותי. העטרה השחורה, רקמה בזהב, מוסיפה נופך של יוקרה וייחוד, כשכל כיפה היא הצהרה אישית של עוצמה רוחנית. הבד הנעים למגע והעיצוב המרשים מבטיחים שתחושו בטחון והשראה בכל תפילה. זוהי מתנה מושלמת לאדם הקרוב אליכם, או פינוק לעצמכם, שמביאה עמה ברכה וחום.</p>', 'טלית ''האש שלי'' - עיצוב זהב עוצר נשימה עם עטרה שחורה יוקרתית. סמל אישי של עוצמה והשראה.', 714.0, NULL, NULL, 'instock', NULL, 'https://deyidkzuvwniioxjisdr.supabase.co/storage/v1/object/public/product-images/opt/39c4f6fee6752314db7db5f9.webp', true, '2026-05-31T11:10:09.145533+00:00', '2026-07-12T17:37:05.630354+00:00'),
  ('b8bc6d2d-c586-4652-b219-3d66a7eb2064', NULL, 'laser-eshet-chayil', 'אשת חיל - חיתוך לייזר', 'גודל: 36×18 ס״מ, לתליה.', 'לוח אקרילי שקוף עם פרק אשת חיל בחיתוך לייזר', 357.0, NULL, NULL, 'instock', NULL, 'https://deyidkzuvwniioxjisdr.supabase.co/storage/v1/object/public/product-images/opt/31703f465e91d86eb1e9e7db.webp', true, '2026-06-21T12:45:15.77172+00:00', '2026-07-12T17:37:13.908023+00:00'),
  ('b8f1897c-5214-4a2e-97f3-e2fad14ae086', 2872373, 'chal-2872373', 'כיסוי לתלתל שלי לבן כסף', '<p>העניקו יוקרה והגנה לתפילין שלכם עם כיסוי מהודר זה, עשוי בד איכותי בגוון כסף-לבן. העיצוב המוקפד והמרקם העשיר משווים לכיסוי מראה מלכותי, המצדיע לקדושת מצוות התפילין. הדגמים העדינים והקווים הנקיים הופכים אותו לפריט שימושי ואסתטי כאחד, המגלם כבוד והדר. מתנה אידיאלית לבר מצווה, חתונה או כהוקרה מיוחדת, שתלווה את בעליה לשנים רבות.</p>', 'כיסוי לתפילין אלגנטי, בעיצוב יוקרתי של פני כסף. מתנה מושלמת לבר מצווה או לכל אירוע משמעותי.', 86.0, NULL, NULL, 'instock', NULL, 'https://deyidkzuvwniioxjisdr.supabase.co/storage/v1/object/public/product-images/opt/c7b2297394422434e2669f50.webp', true, '2026-05-31T11:30:03.111272+00:00', '2026-07-12T17:37:07.077343+00:00'),
  ('b92e93e4-2a63-46b3-bcc8-dbe9c5d8d989', 2872437, 'chal-2872437', 'סט חלאקה קלאסי דגם פרי רקמה בצבע תכלת', '<p>הגיע הזמן לחגוג את המצווה הראשונה! סט החלאקה ''פרי'' בעיצוב קלאסי וגוון תכלת מרגיע, עשוי מבדים איכותיים ונעימים למגע, מקושט ברקמה עדינה ומרשימה. הסט כולל את כל הפריטים הדרושים לטקס החלאקה, והופך את הרגע המיוחד הזה לקסום ונוח. תנו לו את המתנה שתלווה אותו לאורך הדרך.</p>', 'סט חלאקה קלאסי דגם פרי, רקמה עדינה בגוון תכלת. המתנה המושלמת לחוויה בלתי נשכחת.', 357.0, NULL, NULL, 'instock', NULL, 'https://deyidkzuvwniioxjisdr.supabase.co/storage/v1/object/public/product-images/opt/2d994ee2d6a7f57af0409491.webp', true, '2026-05-31T11:30:03.111272+00:00', '2026-07-12T17:37:08.50947+00:00'),
  ('b9d23cc1-f4c6-435c-943c-0b55f9e8667a', 2872434, 'chal-2872434', 'כיסוי לטלית חלאקה לבן רקמה  בצבע שמנת', '<p>הכיסויי המדהים הזה הוא הדרך המושלמת להפוך את סעודת החלאקה לחוויה בלתי נשכחת. עשוי מבד משובח, הוא מעוטר ברקמה עדינה בצבע לבן על גבי רקע בגוון שמנת חם, המשדרים יוקרה וקדושה. כיסוי זה ישמש מזכרת ייחודית ומרגשת לאורך שנים, וישמור על הטלית בצורה מכובדת ומרשימה. השקיעו במתנה שתלווה את ילדכם ברגעים משמעותיים.</p>', 'כיסוי טלית חלאקה מהודר, רקום בלבן על רקע שמנת, למתנה יוקרתית ומרגשת.', 129.0, NULL, NULL, 'instock', NULL, 'https://deyidkzuvwniioxjisdr.supabase.co/storage/v1/object/public/product-images/opt/3aa064a645d065cd29fa9972.webp', true, '2026-05-31T11:30:03.111272+00:00', '2026-07-12T17:37:06.807856+00:00'),
  ('bab5f72c-2198-4a51-9bd7-0c95508b5e0d', NULL, 'esh-sheli-gold-pendant', 'שרשרת זהב "האש שלי" - תליון קלאסי', 'תליון "האש שלי" בעיצוב להבה מזהב 14K, עבודת יד מדוייקת. השרשרת מגיעה באריזת מתנה יוקרתית.<br><br><strong>המחיר משתנה לפי שער הזהב היומי.</strong><br>לתיאום הזמנה וקבלת הצעת מחיר עדכנית - צרו קשר בטלפון או בוואטסאפ.', 'תליון "האש שלי" בעיצוב להבה מזהב טהור, על שרשרת עדינה. ✦ המחיר משתנה לפי שער הזהב היומי - להזמנה צרו קשר.', 0.0, NULL, NULL, 'instock', NULL, 'https://deyidkzuvwniioxjisdr.supabase.co/storage/v1/object/public/product-images/opt/a9e99a6a17ef3a2078b563d7.webp', true, '2026-06-24T12:36:25.537318+00:00', '2026-07-12T17:37:18.272086+00:00'),
  ('bc971c9b-dec3-4f9c-8be3-c0637b695e8e', NULL, 'כיפה-קטיפה-ארט-מן-אותיות-בולטות-זהב-האש-שלי-פנינה-גודל-4-10514', 'כיפה קטיפה "ארט-מן" אותיות בולטות זהב "האש שלי" - פנינה (גודל 4)', NULL, 'כיפה קטיפה "ארט-מן" אותיות בולטות זהב "האש שלי" - פנינה (גודל 4)', 67.0, 40.0, 'UK10514', 'instock', NULL, 'https://deyidkzuvwniioxjisdr.supabase.co/storage/v1/object/public/product-images/opt/e3960af8ada28e44c0c0fb50.webp', true, '2026-06-04T09:45:18.892061+00:00', '2026-07-12T17:37:10.314047+00:00'),
  ('bd0d354b-1dde-43e5-b3ea-00b336235984', NULL, 'גביע-קידוש-ניקל-פיליגרן-מלא-משובץ-8-5-סמ-120-מל-49683', 'גביע קידוש ניקל פיליגרן מלא משובץ 8.5 ס"מ - 120 מ"ל', NULL, 'גביע קידוש ניקל פיליגרן מלא משובץ 8.5 ס"מ - 120 מ"ל', 236.0, NULL, 'UK49683', 'instock', NULL, 'https://deyidkzuvwniioxjisdr.supabase.co/storage/v1/object/public/product-images/opt/fd3b1a3ae3e8eb81b080fad4.webp', true, '2026-06-04T09:45:23.086085+00:00', '2026-07-12T17:37:12.624427+00:00'),
  ('be0dd0e6-ee48-40d0-8b57-a630d2f0b397', NULL, 'product-13', 'סידור מעוצב האש שלי לגבר צבע לבן', '<p>סידור התפילה "האש שלי" בגוון לבן טהור, תוכנן במיוחד עבור הגבר המודרני, המשלב אמונה ועיצוב. הסידור משלב מבנה תפילה מסורתי עם חומרי גלם איכותיים ותווים עיצוביים חדשניים, היוצרים חוויה רוחנית ייחודית. כל סידור עשוי בקפידה, ומבטיח הנאה לטווח ארוך. תנו הצצה לעולם של קדושה מעוצבת.</p>', 'סידור תפילה "האש שלי" לגבר, בעיצוב מודרני לבן, משלב קדושה וסטייל. מתנה אידיאלית לכל גבר.**', 186.0, NULL, NULL, 'instock', NULL, 'https://deyidkzuvwniioxjisdr.supabase.co/storage/v1/object/public/product-images/opt/bfac24aa4ceb7c23f213f1b0.webp', true, '2026-05-31T11:04:26.373999+00:00', '2026-07-12T17:37:14.324994+00:00'),
  ('bf50288c-cb74-4655-ac44-23759ba6f58d', NULL, 'cover-cream-mizmor-laser', 'כיסוי לטלית ותפילין - קרם מזמור לתודה לייזר', 'כיסוי איכותי לטלית ותפילין בגוון קרם עם הדפס לייזר של "מזמור לתודה" בעיגול. הרקמה ניתנת ללייזר בשם בלבד.', 'קרם עם מזמור לתודה - לייזר', 429.0, 300.0, NULL, 'instock', NULL, 'https://deyidkzuvwniioxjisdr.supabase.co/storage/v1/object/public/product-images/opt/9e841e40df015959218b646c.webp', true, '2026-06-09T10:46:32.34945+00:00', '2026-07-12T17:37:08.240658+00:00'),
  ('c1419494-b11a-46fc-a747-cf8909c14d84', 2873117, 'talit-2873117', 'טלית פרימיום בחריטת לייזר בד תשבץ  100% צמר רחלים דגם בבא סאלי במגוון צבעים', '<p>גלו את טלית ''בבא סאלי'' היוקרתית, ארוגה מ-100% צמר רחלים טבעי ואיכותי, המעניקה תחושת רכות ויוקרה. חריטת לייזר מרהיבה בדוגמת תשבץ מעטרת את הטלית, מוסיפה לה נופך מיסטי ומיוחד. דגם זה, המושפע מדמותו המכובדת של הבבא סאלי, מגיע במגוון צבעים עשירים, ומאפשר לכל אחד למצוא את הטלית המושלמת עבורו. חוו תפילה מעמיקה ומלאת השראה עם טלית שתלווה אתכם שנים רבות.</p>', 'טלית פרימיום ''בבא סאלי'' מצמר רחלים טבעי 100%, מעוטרת בחריטת לייזר עדינה בדגם תשבץ. יוקרה וקדושה בכל תפילה.', 1286.0, NULL, NULL, 'instock', NULL, 'https://deyidkzuvwniioxjisdr.supabase.co/storage/v1/object/public/product-images/opt/19b782f7bc97779cbfec5881.webp', true, '2026-05-31T11:10:09.145533+00:00', '2026-07-12T17:37:05.933404+00:00'),
  ('c16b202c-ce8f-4e59-bce3-d6d26a5362b4', 2872372, 'chal-2872372', 'כיסוי לתלתל שלי לבן זהב', '<p>העניקו קדושה והדר לתפילין שלכם עם כיסוי מהודר זה. עשוי פשתן לבן איכותי, הוא משלב רקמה עשירה בפסי זהב, המוסיפה נגיעה של יוקרה וייחודיות. הכיסוי מגן על התפילין שלכם ומשמש כתזכורת יומיומית לקדושת המצווה. מתנה מרגשת ובעלת משמעות לכל בר מצווה, חתונה או כל אירוע משמעותי.</p>', 'כיסוי יוקרתי לתפילין, עשוי פשתן לבן בשילוב רקמת פסי זהב עדינה. מתנה מושלמת לשמירה על קודש הקודשים.', 86.0, NULL, NULL, 'instock', NULL, 'https://deyidkzuvwniioxjisdr.supabase.co/storage/v1/object/public/product-images/opt/e4d6347785f3739a898d1d38.webp', true, '2026-05-31T11:30:03.111272+00:00', '2026-07-12T17:37:16.14744+00:00'),
