  ('d6195393-9b2b-42e2-aaa9-40f85af833c8', 2871473, 'talit-2871473', 'טלית דגם פאר עטרה שחורה  רקמת יברכך צבע זהב', '<p>הטלית "פאר" היא פסגת ההוד והקדושה, מעוצבת בקפידה להעניק חוויית תפילה בלתי נשכחת. עטרת "יברכך" רקמת זהב בוהקת מעטרת את הגלים, ומביאה עמה סגולת ברכה והצלחה. הטלית עשויה מבד איכותי ונעים למגע, אשר נשפך בעדינות ומעניקה תחושת קדושה עמוקה. מתנה מושלמת לעצמכם או ליקיריכם, שתלווה אתכם ברגעים הרוחניים החשובים ביותר.</p>', 'טלית מהודרת ''פאר'' עם עטרת ''יברכך'' רקמת זהב, למראה מלכותי בתפילה. בד איכותי ותחושת קדושה.', 500.0, NULL, NULL, 'instock', NULL, 'https://deyidkzuvwniioxjisdr.supabase.co/storage/v1/object/public/product-images/opt/d48a2e6fd74f9525af48cda7.webp', true, '2026-05-31T11:10:09.145533+00:00', '2026-07-12T17:37:05.63694+00:00'),
  ('d6273119-aa7e-417f-ab76-5cc588d85534', NULL, 'נטלה-פולימר-מהודרת-גוון-שחור-עם-כיתוב-על-נטילת-ידים-14-סמ-49155', 'נטלה פולימר מהודרת גוון שחור עם כיתוב "על נטילת ידים" 14 ס"מ', NULL, 'נטלה פולימר מהודרת גוון שחור עם כיתוב "על נטילת ידים" 14 ס"מ', 185.0, NULL, 'UK49155', 'instock', NULL, 'https://deyidkzuvwniioxjisdr.supabase.co/storage/v1/object/public/product-images/opt/9c81336450c9855c5031fa8b.webp', true, '2026-06-04T09:45:20.945408+00:00', '2026-07-12T17:37:10.393425+00:00'),
  ('d6b37cea-3724-45b4-84d9-cf41fc7a00cc', NULL, 'product-2', 'סידור מעוצב ברכת הכהנים לגבר ג''ינס תכלת בהיר', '<p>סידור תפילה מהודר, שעוצב במיוחד עבור הגבר המודרני. הכריכה בגוון ג''ינס תכלת בהיר מעניקה מראה ייחודי ועדכני, בעוד שהטקסט והאותיות מודפסים באיכות גבוהה לנוחות קריאה והתייחדות. סידור זה מברך את הקורא בברכת הכהנים המקורית, ומציע חיבור עמוק למסורת בצורה שמתאימה לסגנון החיים העכשווי. מושלם כמתנה מרגשת ואישית.</p>', 'סידור ברכת הכהנים לגבר בעיצוב ג''ינס תכלת בהיר – מתנה אישית ומיוחדת.', 186.0, NULL, NULL, 'instock', NULL, 'https://deyidkzuvwniioxjisdr.supabase.co/storage/v1/object/public/product-images/opt/fd8615db16a4f387a22a2a18.webp', true, '2026-05-31T11:04:26.373999+00:00', '2026-07-12T17:37:11.690995+00:00'),
  ('d824a822-442c-4a38-b486-0fc555859de3', NULL, 'tehillim-avodah-shebalev-pink', 'תהילים עבודה שבלב - כריכת כותל ורוד', NULL, 'תהילים עבודה שבלב בכריכה מהודרת בעיצוב אבני הכותל בגוון ורוד עדין עם סימניה ורודה', 130.0, 111.0, NULL, 'instock', 50, 'https://deyidkzuvwniioxjisdr.supabase.co/storage/v1/object/public/product-images/opt/0a0b2b6397f5ce8994efba09.webp', true, '2026-06-16T13:29:21.438221+00:00', '2026-07-12T17:37:11.101862+00:00'),
  ('d8aa3ae4-c632-4de6-a1d9-e76df5222b9e', 2871350, 'talit-2871350', 'טלית דגם יברכך', '<p>טלית "יברכך" היא הרבה יותר מפריט לבוש – היא סמל לקשר עמוק עם הקודש, המלווה אותך ברגעים המשמעותיים של התפילה. עשויה מחומרים איכותיים, היא ניחנה במגע רך ונעים, ובעיטורים עדינים המשדרים יוקרה ושלווה. כל פרט בעיצובה נבחר בקפידה כדי להעצים את חווית התפילה ולהוסיף נופך של קדושה ליום יום.</p>', 'טלית יברכך – הברכה שתתלווה אליך בכל תפילה. עשויה מבדים משובחים, מעוטרת בעיטורים מרהיבים.', 571.43, 350.0, NULL, 'instock', NULL, 'https://deyidkzuvwniioxjisdr.supabase.co/storage/v1/object/public/product-images/opt/9f95e1487e41d769f83903fd.webp', true, '2026-05-31T11:10:09.145533+00:00', '2026-07-12T17:37:16.618538+00:00'),
  ('d8d1f464-5ba4-43cb-ba40-ac30d68d9330', NULL, 'product-17', 'סידור כותל לגבר ג''ינס שחור הטבעה בכסף', '<p>הכירו את סידור הכותל בסטייל שלא הכרתם. מעוצב כג''ינס שחור אלגנטי, הוא משלב אורבניות עם קדושה, ומסמל חיבור עמוק למסורת. הטבעת כסף מבריקה מוסיפה נופך של יוקרה והופכת אותו למתנה בלתי נשכחת. סידור זה הוא לא רק פריט תפילה, אלא אמירה אישית של אמונה ואהבה לירושלים.</p>', 'סידור כותל מהודר לגבר, בעיצוב ג''ינס שחור יוקרתי עם הטבעת כסף מרשימה. מתנה מושלמת לאדם שמתחבר למסורת.', 186.0, NULL, NULL, 'instock', NULL, 'https://deyidkzuvwniioxjisdr.supabase.co/storage/v1/object/public/product-images/opt/400985dcce430f4509047efc.webp', true, '2026-05-31T11:04:26.373999+00:00', '2026-07-12T17:37:14.423589+00:00'),
  ('d8e01bbc-393a-4c04-a358-6432823b3057', NULL, 'product-14', 'סידור מעוצב האש שלי לגבר קורדרוי אפור בהיר', '<p>סידור תפילה ''האש שלי'' לגבר, המשלב עיצוב מודרני עם איכות בלתי מתפשרת. עשוי קורדרוי אפור בהיר ונעים למגע, הוא מעניק חווית תפילה נוחה ומכובדת. הסידור כולל את כל התפילות הדרושות, בתוספת עיצוב ייחודי המתאים לכל בית יהודי. מתנה מושלמת לגבר במחזור חייו, כזו שתלווה אותו ברגעיו הרוחניים.</p>', 'סידור תפילה ''האש שלי'' - קורדרוי אפור בהיר לגבר. עיצוב מודרני ויוקרתי לנוחות תפילה מרבית.', 186.0, NULL, NULL, 'instock', NULL, 'https://deyidkzuvwniioxjisdr.supabase.co/storage/v1/object/public/product-images/opt/6aaf2cb6c004c4d12bd64852.webp', true, '2026-05-31T11:04:26.373999+00:00', '2026-07-12T17:37:21.082497+00:00'),
  ('da49e872-abe7-4d1b-96d7-fafd47bf92bf', NULL, 'sefer-devarim-light-blue', 'ספר דברים - תכלת עם כסף', NULL, 'ספר דברים בכריכת בד מחורצת בגוון תכלת מרגיע עם הטבעת כסף', 143.0, 122.0, NULL, 'instock', 50, 'https://deyidkzuvwniioxjisdr.supabase.co/storage/v1/object/public/product-images/opt/ec048ff36410164be5cdd9e2.webp', true, '2026-06-16T13:29:21.438221+00:00', '2026-07-12T17:37:11.233521+00:00'),
  ('da4d3b0d-0b9b-4aea-b689-d6e8a4f9e4e6', 1246, 'סט-הבדלה-קריסטל-20-סמ-2', 'סט הבדלה קריסטל 20 ס"מ', '<p>הוסיפו גוון של אלגנטיות לאירועי השבת והחגים עם סט הבדלה קריסטל מהודר זה. מתאים לגובה של 20 ס"מ, הסט מעוצב בקפידה מחומרים איכותיים, ומעניק נוכחות מרשימה ומלאת הוד לשולחן. כל פרט בו משדרק את טקס ההבדלה, והופך אותו לחוויה בלתי נשכחת, המשלבת בין קדושת הזמן ליופי הנצחי.</p>', 'סט הבדלה קריסטל 20 ס"מ: מסורת מהודרת, ניחוח של קדושה.', 432.0, 359.98, 'UK82239', 'instock', NULL, 'https://deyidkzuvwniioxjisdr.supabase.co/storage/v1/object/public/product-images/opt/be8046aa48adc60071dd9270.webp', true, '2026-05-10T16:10:19.018791+00:00', '2026-07-12T17:37:19.831413+00:00'),
  ('da580eb4-7e0a-4d1f-8e3a-943373211ac4', NULL, 'product-34', 'סידור מעוצב כתר מובלט לגבר ג''ינס תכלת בהיר', '<p>הוסיפו נופך של יוקרה וייחודיות לתפילה היומיומית עם סידור זה, המשלב עיצוב מודרני עם מסורת עשירה. עור איכותי בגוון ג''ינס תכלת רגוע, מעוטר בהטבעת כתר מוזהב בולטת, מעניק לסידור מראה אלגנטי וגברי. הסידור עשיר בתפילות ובקשות, כתוב על דפי נייר משובח, ונוח לנשיאה. זהו פריט יודאיקה מרשים, שיהווה מתנה אידיאלית לכל אירוע משמעותי.</p>', 'סידור תפילה מהודר לגבר בעיצוב עור יוקרתי בצבע ג''ינס תכלת, עם הטבעת כתר מפוארת. מתנה מושלמת לכל גבר.', 186.0, NULL, NULL, 'instock', NULL, 'https://deyidkzuvwniioxjisdr.supabase.co/storage/v1/object/public/product-images/opt/8e3c3b53a747024ea98a422f.webp', true, '2026-05-31T11:04:26.373999+00:00', '2026-07-12T17:37:15.056215+00:00'),
  ('da7f952f-6c13-45a3-bb92-310185483880', 2871461, 'talit-2871461', 'טלית תשבץ  צמר פסים בצבע כסף עם עטרה לבנה יוקרתית האש שלי בצבע כסוף', '<p>טלית צמר עדינה בתשבץ, מעוטרת בפסים כסופים המעניקים לה מראה יוקרתי ומיוחד. עטרת ''האש שלי'' הלבנה, המשולבת בחוטי כסף, מוסיפה נופך של קדושה ועידון מודרני. עשויה מצמר איכותי, טלית זו מבטיחה נוחות ונעימות בתפילה, בעוד עיצובה הופך אותה לפריט ייחודי ומרשים, המשלב מסורת עשירה עם אמירה אופנתית.</p>', 'טלית צמר תשבץ עם עטרת האש שלי מכסף. שילוב יוקרתי של מסורת ועיצוב מודרני.', 1286.0, NULL, NULL, 'instock', NULL, 'https://deyidkzuvwniioxjisdr.supabase.co/storage/v1/object/public/product-images/opt/0a41e71f2df65126f818ef3e.webp', true, '2026-05-31T11:10:09.145533+00:00', '2026-07-12T17:37:17.262439+00:00'),
  ('dbad3836-c71e-432d-9ad5-ea21ba2097e8', 2153, 'סט-טלית-ותפילין-מבד-עור-pu-3831-סמ-עם-ידיות-ול', 'סט טלית ותפילין מבד עור PU 38*31 ס"מ עם ידיות ולוגו מוטבע - אפור', '<p>העניקו לעצמכם או ליקירכם מתנה מרשימה ואיכותית עם סט טלית ותפילין ייחודי זה. עשוי מבד עור PU משובח בגוון אפור קלאסי, הסט כולל ידיות נוחות לאחיזה ועיטור לוגו מוטבע המעניק לו מגע אישי ואלגנטי. בגודל אידיאלי של 38*31 ס"מ, הוא משלב פונקציונליות עם עיצוב מודרני, ויהווה תוספת מכובדת ומרגשת לחפצי הקודש שלכם.</p>', 'סט טלית ותפילין יוקרתי מבד עור PU איכותי, בעיצוב אפור אלגנטי. הסט כולל ידיות נוחות ולוגו מוטבע, בגודל 38*31 ס"מ.', 240.0, 199.98, 'UK66355', 'instock', NULL, 'https://deyidkzuvwniioxjisdr.supabase.co/storage/v1/object/public/product-images/opt/d87fbd7494dca85967aa7005.webp', true, '2026-05-10T16:10:19.018791+00:00', '2026-07-12T17:37:20.682158+00:00'),
  ('dbb63c41-20a0-4c9f-b00d-cd9973b56119', 2871972, 'talit-2871972', 'טלית פלטניום תשבץ 100% צמר רחלים דגם שויתי עטרה פינות וגב בצבע קרם', '<p>טלית פלטיניום מדגם שויתי, עשויה 100% צמר רחלים איכותי, שתלווה אותך ברגעים הקדושים ביותר. העיטורים הייחודיים בצבע קרם על העטרה, הפינות והגב מוסיפים נופך של אלגנטיות וקדושה, ומעצימים את תחושת החיבור בתפילה. מרקם הצמר הרך והנעים מבטיח נוחות מרבית, בעוד שהאיכות ללא פשרות מבטיחה שהטלית תישאר נכס לטווח ארוך.</p>', 'טלית פלטיניום יוקרתית, 100% צמר רחלים, דגם שויתי מושלם לתפילה.', 1572.0, NULL, NULL, 'instock', NULL, 'https://deyidkzuvwniioxjisdr.supabase.co/storage/v1/object/public/product-images/opt/6739172006f77037d477edb9.webp', true, '2026-05-31T11:10:09.145533+00:00', '2026-07-12T17:37:16.920273+00:00'),
  ('dc174d3d-580e-42a3-bd36-ffe204db46ce', NULL, 'מסגרת-אקריליק-מהודרת-עם-פלקטה-19x25-סמ-80777', 'מסגרת אקריליק מהודרת עם פלקטה 19x25 ס"מ', NULL, 'מסגרת אקריליק מהודרת עם פלקטה 19x25 ס"מ', 169.0, NULL, 'UK80777', 'instock', NULL, 'https://deyidkzuvwniioxjisdr.supabase.co/storage/v1/object/public/product-images/opt/4fee4bbfa9062f4628943099.webp', true, '2026-06-04T09:45:16.701677+00:00', '2026-07-12T17:37:12.350815+00:00'),
  ('dcbd15a6-11a5-4347-8489-2ce029e13fba', 2872429, 'chal-2872429', 'סט חלאקה פרימיום דגם כתר רקמה כסופה וספר תורה', '<p>גזירת השיער הראשונה היא רגע מכונן, וסט החלאקה "כתר רקמה כסופה" מעצים אותו לחוויה בלתי נשכחת. הכתר היוקרתי, מעוטר ברקמת כסף עדינה, מוסיף קסם ותחושת חגיגיות לתינוק. לצד ספר התורה המהודר, המהווה תזכורת למסורת, הסט משלב יופי, רוחניות וזיכרון מתוק. הפכו את היום המיוחד הזה לחגיגה של קדושה, משפחה והתחלה חדשה.</p>', 'סט חלאקה יוקרתי - "כתר רקמה כסופה" וספר תורה – מתנה מושלמת ליום הולדת שלוש, מעוצב ומרגש.', 1186.0, NULL, NULL, 'instock', NULL, 'https://deyidkzuvwniioxjisdr.supabase.co/storage/v1/object/public/product-images/opt/3bb841addf1e461bd99a73c4.webp', true, '2026-05-31T11:30:03.111272+00:00', '2026-07-12T17:37:07.675847+00:00'),
  ('dd02b9a2-ab8b-42ff-9488-084031d28b9f', NULL, 'product-19', 'סידור כותל לגבר לבן הטבעה בכסף', '<p>קחו הביתה פיסה מרגשת מהקודש עם סידור כותל מהודר, המיועד במיוחד לגבר. הכריכה הלבנה והנקייה מעוטרת בהטבעת כסף עדינה ומרהיבה, המוסיפה נופך של יוקרה וקדושה. הסידור איכותי ונוח לשימוש, ומכיל את התפילות החשובות ליום יום, לשבתות ולחגים. זוהי מתנה אידיאלית ומרגשת לבר המצווה, עלייה לתורה, גיוס או כל אירוע משמח אחר.</p>', 'סידור כותל מהודר לגבר, עם הטבעה כסף מרהיבה. מתנה אידיאלית ומיוחדת לעלייה לתורה או לחג.', 186.0, NULL, NULL, 'instock', NULL, 'https://deyidkzuvwniioxjisdr.supabase.co/storage/v1/object/public/product-images/opt/19d53ce004b2234b5f9465a1.webp', true, '2026-05-31T11:04:26.373999+00:00', '2026-07-12T17:37:14.45323+00:00'),
  ('ddb50d54-1e00-4c99-837b-a06fa1a1c3bf', NULL, 'כיפה-קטיפה-עם-ריקמה-האש-שלי-ירוק-בהיר-גודל-4-10001', 'כיפה קטיפה עם ריקמה האש שלי - ירוק בהיר (גודל 4)', NULL, 'כיפה קטיפה עם ריקמה האש שלי - ירוק בהיר (גודל 4)', 61.0, 40.0, 'UK10001', 'instock', NULL, 'https://deyidkzuvwniioxjisdr.supabase.co/storage/v1/object/public/product-images/opt/0a182c4b29716da0db509118.webp', true, '2026-06-04T09:45:18.160119+00:00', '2026-07-12T17:37:11.975909+00:00'),
  ('ddce98c5-dbeb-42aa-b5f8-15b91df5fd73', NULL, 'product-1', 'סידור מעוצב ברכת הכהנים לגבר ג''ינס שחור', '<p>הסידור המעוצב "ברכת הכהנים" לגבר, בדמוי ג''ינס שחור, הוא שילוב מושלם של מסורת סטייל. הסידור כולל את נוסח ברכת הכהנים המפורסם, המודפס על נייר איכותי, ועתיר בפרטים עדינים תואמי ג''ינס. מושלם להצגה בבית או במשרד, הוא מעניק נוכחות מרשימה ומרגשת, ומהווה מתנה ייחודית ומלאת כבוד לכל גבר.</p>', 'סידור ברכת הכהנים לגבר בעיצוב ג''ינס שחור – מתנה מרשימה ומלאת משמעות.', 186.0, NULL, NULL, 'instock', NULL, 'https://deyidkzuvwniioxjisdr.supabase.co/storage/v1/object/public/product-images/opt/a424a948fa02177e5e5d2958.webp', true, '2026-05-31T11:04:26.373999+00:00', '2026-07-12T17:37:11.561618+00:00'),
  ('e057d31c-6cff-4045-b275-406b5154b683', 2419, 'מזוזה-דמוית-אבן-פולימר-15-סמ-3', 'מזוזה דמוית אבן פולימר 15 ס"מ', '<p>הוסיפו נופך של קדושה ועיצוב מודרני לביתכם עם מזוזה מיוחדת זו, המעוצבת להיראות כאבן טבעית. עשויה מחומר פולימר איכותי ועמיד, היא מבטיחה מראה מרשים לאורך שנים. מזוזה זו אינה רק פריט עיצובי, אלא גם סמל להגנה רוחנית ומסורת יהודית עתיקה. מתנה מושלמת לכל בית, המשלבת יופי, איכות ומשמעות.</p>', 'מזוזה ייחודית דמוית אבן טבעית, מוסיפה חן וקדושה לכל פתח. הגנה רוחנית ועיצוב מרהיב.', 101.0, 59.98, 'UK24444', 'instock', NULL, 'https://deyidkzuvwniioxjisdr.supabase.co/storage/v1/object/public/product-images/opt/993c45cb4f8ddc8b5c1a5294.webp', true, '2026-05-10T16:10:19.018791+00:00', '2026-07-12T17:37:16.183668+00:00'),
  ('e0667739-90cc-466a-bf7f-9bb390461a2f', 2424, 'מזוזה-דמוית-אבן-כותל-15-סמ-אפורה', 'מזוזה דמוית אבן "כותל" 15 ס"מ - אפורה', '<p>העניקו לביתכם אווירה של קדושה והוד עם מזוזה ייחודית זו, המעוצבת להיראות כאילו עשויה מאבן הכותל האמיתית. הגוון האפור הטבעי והמרקם המדויק יוצרים מראה אותנטי ומרגש, המזכיר את ירושלים ואת קרבת מקום. המזוזה בגודל 15 ס"מ מתאימה לרוב המשקופים ומשדרת יציבות ונוכחות. היא עשויה מחומרים איכותיים ועמידים, המבטיחים שתשמש אתכם שנים רבות, כשומרת סף וכקישוט מרהיב.</p>', 'מזוזה מרשימה דמוית אבן הכותל, בגוון אפור טבעי, מוסיפה קדושה ויופי לכל פתח. גודל 15 ס"מ.', 72.0, 59.98, 'UK24664', 'instock', NULL, 'https://deyidkzuvwniioxjisdr.supabase.co/storage/v1/object/public/product-images/opt/2cfe4f199d435a6f59d1ca81.webp', true, '2026-05-10T16:10:19.018791+00:00', '2026-07-12T17:37:21.044252+00:00')
