INSERT INTO public.products (id, wp_id, slug, name, description, short_description, price, sale_price, sku, stock_status, stock_qty, thumbnail_url, is_active, created_at, updated_at) VALUES
  ('0128725c-e910-4314-bb4c-7d6f7d8eeee4', 2871985, 'talit-2871985', 'טלית פלטניום תשבץ 100% צמר רחלים דגם בבא סאלי עטרה פינות וגב בצבע אבן', '<p>הטלית פלטניום בתשבץ הינה יצירת מופת של אומנות וקדושה, עשויה 100% צמר רחלים משובח. דגם בבא סאלי, המעוטר בעטרה ייחודית בפינות ובגב בגוון אבן טבעי, מקנה נוכחות מרשימה וקדושה. מגע הצמר הרך והנפלא מבטיח נוחות מרבית בזמן התפילה, בעוד העיצוב המוקפד משלב בין מסורת עתיקה ליוקרה מודרנית. טלית זו היא מתנה מושלמת לעצמכם או ליקירכם, המשלבת איכות ללא פשרות וחיבור עמוק למקורות.</p>', 'טלית פלטניום, תשבץ צמר רחלים 100%. דגם בבא סאלי, עטרה פינות וגב בצבע אבן - חיבור בין מסורת לאיכות.', 1572.0, NULL, NULL, 'instock', NULL, 'https://deyidkzuvwniioxjisdr.supabase.co/storage/v1/object/public/product-images/opt/1b989c23c2ea12e447ab364c.webp', true, '2026-05-31T11:10:09.145533+00:00', '2026-07-12T17:37:16.423356+00:00'),
  ('0184a184-10d3-4f07-a515-f6632c690f7e', NULL, 'מסגרת-זכוכית-עם-אבנים-לבנות-ופלקטה-שיוויתי-24x33-סמ-48455', 'מסגרת זכוכית עם אבנים לבנות ופלקטה שיוויתי 24x33 ס"מ', NULL, 'מסגרת זכוכית עם אבנים לבנות ופלקטה שיוויתי 24x33 ס"מ', 202.0, NULL, 'UK48455', 'instock', NULL, 'https://deyidkzuvwniioxjisdr.supabase.co/storage/v1/object/public/product-images/opt/c36d0f2a9d804a926adae2d9.webp', true, '2026-06-04T09:45:15.540031+00:00', '2026-07-12T17:37:15.904551+00:00'),
  ('0185ebb9-80b3-4e5b-96dd-d33ef7bdced2', 2181, 'סט-טלית-דמוי-עור-לבן-3629-סמ-עם-אותיות-מוטב', 'סט טלית דמוי עור - לבן 36*29 ס"מ עם אותיות מוטבעות', '<p>העניקו לעצמכם או ליקיריכם מתנה מרשימה עם סט טלית דמוי עור איכותי. הסט, בגודל 36*29 ס"מ, משלב עיצוב מודרני ואלגנטי עם אותיות מוטבעות באופן מדויק, המוסיף נופך של קדושה ותחכום. דמוי העור העמיד והנעים למגע מבטיח שימוש לאורך שנים, והגוון הלבן הטהור משדר שלווה ויופי. מתנה מושלמת לבר מצווה, חגים או כל אירוע משמעותי.</p>', 'סט טלית דמוי עור יוקרתי - לבן 36*29 ס"מ. עיצוב אלגנטי עם אותיות מוטבעות, מושלם לכל אירוע.', 357.14, NULL, 'UK66480', 'instock', NULL, 'https://deyidkzuvwniioxjisdr.supabase.co/storage/v1/object/public/product-images/opt/84cc1c7d25db040ab0057e78.webp', true, '2026-05-10T16:10:19.018791+00:00', '2026-07-12T17:37:20.572389+00:00'),
  ('023267ba-fe1a-4e65-8b24-3bed8dba7187', NULL, 'מזוזה-פולימר-בטון-כותל-ברכת-הבית-שחור-15-סמ-24666', 'מזוזה "פולימר בטון" כותל ברכת הבית שחור 15 ס"מ', NULL, 'מזוזה "פולימר בטון" כותל ברכת הבית שחור 15 ס"מ', 101.0, NULL, 'UK24666', 'instock', NULL, 'https://deyidkzuvwniioxjisdr.supabase.co/storage/v1/object/public/product-images/opt/f555e90e2744defce0c7422e.webp', true, '2026-06-04T09:45:24.93769+00:00', '2026-07-12T17:37:12.080213+00:00'),
