  ('051afcd2-7b8e-4e6a-b0d2-fe35f5b7dff5', NULL, 'product-45', 'סידור מעוצב מזמור לתודה לגבר צבע לבן', '<p>סידור תפילה "מזמור לתודה" בעיצוב מינימליסטי ולבן, עוצב במיוחד עבור הגבר העכשווי. הוא משלב מסורת עתיקת יומין עם אסתטיקה מודרנית, ומוצע על גבי נייר איכותי ונעים למגע. הסידור כולל תפילות הודיה מרכזיות, והכריכה הלבנה מעניקה לו מראה יוקרתי ומרשים. זוהי מתנה אידיאלית להוקרה, לברכה, או כדרך להביע הערכה עמוקה.</p>', 'סידור תפילה "מזמור לתודה" לגבר בעיצוב לבן אלגנטי. מתנה מושלמת לאירועים מיוחדים.', 186.0, NULL, NULL, 'instock', NULL, 'https://deyidkzuvwniioxjisdr.supabase.co/storage/v1/object/public/product-images/opt/cfbcad45368f2274fe691143.webp', true, '2026-05-31T11:04:26.373999+00:00', '2026-07-12T17:37:15.605423+00:00'),
  ('05c7794e-c259-46af-a389-cdca04dd8d68', 2116, 'עטרה-לטלית-עם-רקמה-1009-סמ-לבן', 'עטרה לטלית עם רקמה 100*9 ס"מ - לבן', '<p>העטרה לטלית זו, במידות 100*9 ס"מ, עשויה מבד סאטן לבן איכותי ומשלבת רקמה עדינה ומדויקת. היא מעוצבת להוסיף נופך של יופי וקדושה לטלית שלכם, ולהפוך את חווית התפילה למיוחדת יותר. העיצוב הנקי והאלגנטי משתלב נפלא עם כל סוגי הטליתות, והאיכות מובטחת לאורך שנים.</p>', 'עטרת טלית מהודרת 100*9 ס"מ, רקמה עדינה על ריקמת סאטן לבן. הוסיפו יופי וקדושה לתפילה.', 168.0, 139.98, 'UK60421', 'instock', NULL, 'https://deyidkzuvwniioxjisdr.supabase.co/storage/v1/object/public/product-images/opt/d5a4e4ed86cd4d931e4f6923.webp', true, '2026-05-10T16:10:19.018791+00:00', '2026-07-12T17:37:20.873924+00:00'),
  ('06494336-ef05-4413-9ede-df4c8aaaaf78', NULL, 'product-25', 'סידור כתר לגבר ג''ינס שחור הטבעה בכסף', '<p>סידור "כתר" לגבר, המשלב עיצוב ייחודי של כריכת ג''ינס שחור עמיד ואיכותי עם הטבעה מוזהבת של כתר מלכות. הסידור מכיל את כל התפילות הנדרשות לתפילות השבת והחג, כתובות באותיות ברורות וקריאות. מתנה מרשימה ויוקרתית לגבר שמעריך איכות, סטייל וקדושה.</p>', 'סידור תפילה מהודר לגבר, בעיצוב ג''ינס שחור יוקרתי עם הטבעת כתר כסף.', 186.0, NULL, NULL, 'instock', NULL, 'https://deyidkzuvwniioxjisdr.supabase.co/storage/v1/object/public/product-images/opt/abae3b90abb06f6d32b526ac.webp', true, '2026-05-31T11:04:26.373999+00:00', '2026-07-12T17:37:14.744722+00:00'),
  ('069066d2-21d1-4af6-b744-06ceb1d8ae32', 2871952, 'talit-2871952', 'טלית פרימיום תשבץ  100% צמר רחלים דגם יברכך עטרה ופינות רקומות בצבע כסף', '<p>הטלית פרימיום מדגם ''יברכך'' משלבת איכות ללא פשרות עם עיצוב מרשים. עשויה כולה מ-100% צמר רחלים משובח, היא מתאפיינת בתחושה רכה ונעימה למגע. פינותיה ועטרתה מעוטרות ברקמה עדינה בצבע כסף, המוסיפה יוקרה וייחודיות. זוהי לא רק טלית, אלא אמירה של קדושה וסטייל, המעניקה חוויה רוחנית עשירה בכל תפילה.</p>', 'טלית פרימיום יברכך – עשויה 100% צמר רחלים, עם עיטורי כסף יוקרתיים. התברכו בברכת כהנים מרהיבה.', 643.0, NULL, NULL, 'instock', NULL, 'https://deyidkzuvwniioxjisdr.supabase.co/storage/v1/object/public/product-images/opt/57c13fa5d400a4ee0e110478.webp', true, '2026-05-31T11:10:09.145533+00:00', '2026-07-12T17:37:05.650901+00:00'),
  ('07359ae4-9403-480c-a045-f3557b4d6160', 2013, 'ברכות-הפרשת-חלה-מעור-דמוי-עור-לבן-40-סמ', 'ברכות "הפרשת חלה" מעור דמוי עור - לבן 40 ס"מ', '<p>העניקו חן וקדושה למצוות הפרשת חלה עם ברכה מעוצבת זו. עשויה מעור דמוי עור איכותי בגוון לבן נקי, הברכה מוסיפה יופי ורוחניות לכל מטבח. גודלה המרשים (40 ס"מ) הופך אותה לפריט מרכזי ומרשים על הקיר, המזכיר תמיד את חשיבות המצווה והשמחה שבה. מתנה מושלמת למארחות, לכלות או לכל בית יהודי.</p>', 'ברכת הפרשת חלה מהודרת מעור דמוי עור לבן, 40 ס"מ.', 236.0, 139.98, 'UK67000', 'instock', NULL, 'https://deyidkzuvwniioxjisdr.supabase.co/storage/v1/object/public/product-images/opt/718d891071ae3b45f39e41b4.webp', true, '2026-05-10T16:10:19.018791+00:00', '2026-07-12T17:37:13.412983+00:00'),
  ('077980cb-232b-4c44-84d5-0e788f9bc6bc', NULL, 'מים-אחרונים-פולימר-מהודר-12-סמ-דגם-3-42497', 'מים אחרונים פולימר מהודר 12 ס"מ (דגם 3)', NULL, 'מים אחרונים פולימר מהודר 12 ס"מ (דגם 3)', 270.0, NULL, 'UK42497', 'instock', NULL, 'https://deyidkzuvwniioxjisdr.supabase.co/storage/v1/object/public/product-images/opt/1f774ef952beccad10d2f401.webp', true, '2026-06-04T09:45:19.858602+00:00', '2026-07-12T17:37:12.337302+00:00'),
  ('07bb8561-9d88-40b2-b647-392a8d15f9eb', 2170, 'סט-טלית-ותפילין-מעור-מלאכותי-3831-סמ-לבן-ע', 'סט טלית ותפילין מעור מלאכותי 38*31 ס"מ - לבן עם אותיות מוטבעות', '<p>היכר את סט הטלית והתפילין המרהיב שלנו, עשוי מעור מלאכותי משובח בגוון לבן טהור. הסט, במידות 38*31 ס"מ, מתאפיין באותיות מוטבעות בעדינות, המוסיפות נופך יוקרתי ומיוחד. פריט זה משלב מסורת עתיקת יומין עם עיצוב מודרני, והוא אידיאלי לשימוש יומיומי או כמתנה יקרת ערך לאדם אהוב.</p>', 'סט טלית ותפילין אלגנטי מעור מלאכותי איכותי. עיצוב לבן קלאסי עם אותיות מוטבעות, מתנה מרגשת לכל אירוע.', 357.14, NULL, 'UK66725', 'instock', NULL, 'https://deyidkzuvwniioxjisdr.supabase.co/storage/v1/object/public/product-images/opt/67de1d7ba3080dde4ad95b4f.webp', true, '2026-05-10T16:10:19.018791+00:00', '2026-07-12T17:37:07.729071+00:00'),
  ('07d884ea-dada-4af0-8446-45b6f08eea06', 2873762, 'talit-2873762', 'טלית פלטניום תשבץ 100% צמר רחלים דגם בבא סאלי במגוון צבעים', '<p>התעטפו בקדושה ובפאר עם טלית הפלטניום מדגם בבא סאלי. עשויה בקפידה מ-100% צמר רחלים עדין, הטלית משלבת עיצוב תשבץ קלאסי עם נוכחות מרשימה. בחרו מתוך מגוון צבעים עשירים שיתאימו לטעמכם האישי ויוסיפו הוד על תפילותיכם. זוהי לא רק טלית, אלא יצירת אמנות שתלווה אתכם ברגעים הרוחניים החשובים שלכם.</p>', 'טלית פלטניום בבא סאלי - יוקרה, מסורת ואיכות ללא פשרות. עשויה 100% צמר רחלים משובח, עם עיצוב תשבץ מרהיב.', 1572.0, NULL, NULL, 'instock', NULL, 'https://deyidkzuvwniioxjisdr.supabase.co/storage/v1/object/public/product-images/opt/c8b8ae2a4d3bbd2ae50c6ac1.webp', true, '2026-05-31T11:10:09.145533+00:00', '2026-07-12T17:37:16.468517+00:00'),
  ('0826ff23-5d49-4c1b-b995-e79a2ba9f15e', 2091, 'קליפסים-לטלית-חושן-ניקל-9-סמ', 'קליפסים לטלית חושן ניקל 9 ס"מ', '<p>שדרגו את חווית הטלית שלכם עם קליפסים לטלית חושן בעיצוב מרהיב. עשויים מניקל איכותי ועמיד, באורך 9 ס"מ, הם מבטיחים אחיזה יציבה ומניעת החלקה של הטלית. הקליפסים משלבים פונקציונליות עם אסתטיקה, ומוסיפים נגיעה של יופי וסדר לתפילה. מתנה מושלמת לכל יהודי שומר מצוות, המעוניין בשימור כבוד הטלית.</p>', 'קליפסים לטלית חושן מניקל איכותי, באורך 9 ס"מ. פתרון אלגנטי ויעיל לשמירה על הטלית שלך. עיצוב מרהיב ושימושי.', 48.0, 39.98, 'UK45979', 'instock', NULL, 'https://deyidkzuvwniioxjisdr.supabase.co/storage/v1/object/public/product-images/opt/36bf94c357e4375b2c3f3f71.webp', true, '2026-05-10T16:10:19.018791+00:00', '2026-07-12T17:37:18.272086+00:00'),
  ('083c4ffb-c186-4b83-8d1d-89104aa0dd90', 2871426, 'talit-2871426', 'טלית תשבץ  צמר פסים בצבע כסף', '<p>התעטפו באלגנטיות עם טלית הצמר המרהיבה שלנו, בעיצוב תשבץ קלאסי המשלב פסים בצבע כסף עדין. עשויה מצמר טבעי ואיכותי, היא מעניקה תחושת רכות ויוקרה בכל פעם מחדש. הטלית מתאימה לתפילות יומיומיות ולאירועים מיוחדים, ומוסיפה נופך של אצילות מיוחדת. השילוב של החומר המשובח והעיצוב המוקפד הופך אותה למתנה אידיאלית ופריט אישי של קדושה.</p>', 'טלית צמר יוקרתית בעיצוב תשבץ פסים כסופים, מראה אצילי לכל תפילה.', 540.0, 450.0, NULL, 'instock', NULL, 'https://deyidkzuvwniioxjisdr.supabase.co/storage/v1/object/public/product-images/opt/f5ed9077d899aea35744481e.webp', true, '2026-05-31T11:10:09.145533+00:00', '2026-07-12T17:37:13.627181+00:00'),
  ('096ad296-8b9f-49f7-b41d-41f62810a8fa', 2871859, 'chal-2871859', 'סט חלאקה פרימיום דגם כתר רקמה בזהב', '<p>חגגו את רגע החלאקה הראשון של בנכם עם סט ''כתר רקמה'' המרהיב, מעוצב ככתר זהב עשיר ומעוטר ברקמת קודש עדינה. כל פרט בסט, הכולל חלוק, כרית לנענועים, וכיסוי לחלה, נוצר באהבה ובמסירות מחומרים איכותיים. הסט ישמש כמזכרת חמה ומרגשת לשנים רבות, ויעניק נופך של הוד קדושה לאירוע המשמעותי.</p>', 'סט חלאקה יוקרתי ''כתר רקמה'' בזהב – מזכרת יקרת ערך לרגע הקדוש. מושלם למתנה.', 900.0, NULL, NULL, 'instock', NULL, 'https://deyidkzuvwniioxjisdr.supabase.co/storage/v1/object/public/product-images/opt/268be8a2f53c0e28124f62ee.webp', true, '2026-05-31T11:30:03.111272+00:00', '2026-07-12T17:37:06.829501+00:00'),
  ('0a3a444f-8224-4a58-9e79-6741c247dfab', NULL, 'tehillim-hamevoar-tan', 'תהלים המבואר - כריכת בד חום קאמל', NULL, 'תהלים המבואר בכריכת בד מחורצת בגוון חום קאמל עם הטבעת זהב אלגנטית', 130.0, 111.0, NULL, 'instock', 50, 'https://deyidkzuvwniioxjisdr.supabase.co/storage/v1/object/public/product-images/opt/fac4d3455a194b0e479cf57d.webp', true, '2026-06-16T13:31:12.831392+00:00', '2026-07-12T17:37:12.255982+00:00'),
  ('0a526759-b788-4d09-a1e0-5a88d3887d72', 2871467, 'talit-2871467', 'טלית תשבץ  צמר פסים בצבע שחור עם עטרה שחורה יוקרתית האש שלי בצבע כסוף', '<p>טלית צמר תשבץ איכותית זו, בעיצוב פסים שחורים קלאסי, מציעה מראה מרשים ונעים. העטרה השחורה, משובצת בעיטור כסוף יוקרתי, מוסיפה נגיעה של אלגנטיות ייחודית. עשויה מצמר משובח, היא מחממת ונוחה ללבישה בכל עת. טלית זו היא הבחירה המושלמת עבור מי שמחפש שילוב של מסורת, איכות וסטייל.</p>', 'טלית צמר תשבץ יוקרתית, עם פסים שחורים מודגשים ועטרה כסופה נוצצת. איכות מעולה לכל יום תפילה.', 1286.0, NULL, NULL, 'instock', NULL, 'https://deyidkzuvwniioxjisdr.supabase.co/storage/v1/object/public/product-images/opt/d49b7c01a95fb48116a2e43f.webp', true, '2026-05-31T11:10:09.145533+00:00', '2026-07-12T17:37:17.011528+00:00'),
  ('0ae30fb5-e47b-4b07-9b57-256f45bd2bf8', NULL, 'קופת-צדקה-האש-שלי-מפולימר-13-סמ-81464', 'קופת צדקה "האש שלי" מפולימר 13 ס"מ', NULL, 'קופת צדקה "האש שלי" מפולימר 13 ס"מ', 169.0, NULL, 'UK81464', 'instock', NULL, 'https://deyidkzuvwniioxjisdr.supabase.co/storage/v1/object/public/product-images/opt/efc896d68eb9180348f5df9b.webp', true, '2026-06-04T09:45:13.187878+00:00', '2026-07-12T17:37:15.329913+00:00'),
  ('0b4a427b-f7c7-484d-b8e4-20843d208d7d', NULL, 'מזוזה-פולימר-בטון-ש-זהב-15-סמ-טבעי-24229', 'מזוזה פולימר בטון ש זהב 15 ס"מ - טבעי', NULL, 'מזוזה פולימר בטון ש זהב 15 ס"מ - טבעי', 135.0, NULL, 'UK24229', 'instock', NULL, 'https://deyidkzuvwniioxjisdr.supabase.co/storage/v1/object/public/product-images/opt/731e9d1895a652ce3c51fc23.webp', true, '2026-06-04T09:45:24.411677+00:00', '2026-07-12T17:37:11.385454+00:00'),
  ('0c674ba5-638a-4002-9311-2e57d29d868f', NULL, 'artj-uk60056', 'תיק מפואר לטלית דמוי עור לבן אותיות בולטות', '<p>הגנו על הטלית שלכם בסטייל עם תיק יוקרתי זה, עשוי ויניל לבן איכותי למראה אלגנטי ויוקרתי. האותיות הבולטות מעניקות נופך של הוד והדר, והעיצוב המוקפד מבטיח שמירה מרבית על הטלית ללא פשרות. פתרון אידיאלי לנשיאה ותצוגה מכובדת, המשלב פונקציונליות עם אסתטיקה מרשימה.</p>', 'תיק טלית יוקרתי מעור לבן, מעוטר באותיות בולטות, לשמירה על הטלית ולתצוגה מכובדת.', 357.14, NULL, 'UK60056', 'instock', NULL, 'https://deyidkzuvwniioxjisdr.supabase.co/storage/v1/object/public/product-images/opt/406240c10e43701ce9871e65.webp', true, '2026-05-31T11:25:25.72855+00:00', '2026-07-12T17:37:06.364791+00:00'),
  ('0d142f4c-f36d-4961-9d32-45f09a723ced', NULL, 'product-29', 'סידור כתר לגבר שחור הטבעה בכסף', '<p>סידור תפילה מהודר, במהדורה מיוחדת לגבר, בעיצוב קלאסי ומרשים. הכריכה השחורה המוצקה משלימה באופן מושלם את ההטבעה הייחודית של כתר מלכות בכסף אמיתי, המוסיפה ניחוח של יוקרה ומלכותיות. הסידור מכיל את כל התפילות החיוניות, כתובות בפונט ברור וקריא, על גבי נייר איכותי. זוהי מתנה מושלמת לגבר שמעריך איכות, אסתטיקה וקדושה.</p>', 'סידור כתר לגבר – עיצוב אלגנטי, הטבעה בכסף אמיתי. מתנה יוקרתית לכל גבר.', 186.0, NULL, NULL, 'instock', NULL, 'https://deyidkzuvwniioxjisdr.supabase.co/storage/v1/object/public/product-images/opt/513c7f00836f27e6c11c9241.webp', true, '2026-05-31T11:04:26.373999+00:00', '2026-07-12T17:37:07.067058+00:00'),
  ('0db3e289-e386-429f-a6b0-21e648646a22', NULL, 'product-55', 'סידור מבד טוויד – ורוד עתיק', '<p>הכירו את סידור התפילה המרהיב שלנו, עטוף בבד טוויד איכותי בגוון ורוד עתיק. כל סידור הוא פריט ייחודי בעבודת יד, המשלב אלגנטיות קלאסית עם נגיעה מודרנית. הבד העשיר והנעים למגע, לצד הכריכה המוקפדת, הופכים אותו למתנה שלא תשכח – מושלם לשבתות, חגים, או סתם כמחווה מרגשת. הוסיפו קסם לתפילותיכם וליהודאיקה שלכם.</p>', 'סידור תפילה יפהפה בעבודת יד מבד טוויד ורוד עתיק. מתנה מושלמת לכל אירוע.', 186.0, NULL, NULL, 'instock', NULL, 'https://deyidkzuvwniioxjisdr.supabase.co/storage/v1/object/public/product-images/opt/7e8c8997fbb23a5872ebf640.webp', true, '2026-05-31T11:04:26.373999+00:00', '2026-07-12T17:37:15.966374+00:00'),
  ('101fe139-4c09-45a9-a096-528ef2eed44c', NULL, 'product-12', 'סידור מעוצב האש שלי לגבר צבע חום עתיק', '<p>הסידור "האש שלי" הוא הרבה יותר מסתם ספר תפילה; הוא מסע רוחני מעוצב. בגוון חום עתיק ומרקם עור משובח, סידור זה לגבר משדר אלגנטיות נצחית. כל דף נפתח כמסע אל הקודש, מעוטר באותיות ברורות ונעימות לעין. זהו מתנה מושלמת, המשלבת יופי, קדושה וגעגוע לניצוץ הפנימי.</p>', 'סידור תפילה "האש שלי" - מתנה מרגשת לגבר. עיצוב עתיק בגוון חום, לחוויה רוחנית עשירה.', 186.0, NULL, NULL, 'instock', NULL, 'https://deyidkzuvwniioxjisdr.supabase.co/storage/v1/object/public/product-images/opt/205c6ed1aa24c5d869ebb8bd.webp', true, '2026-05-31T11:04:26.373999+00:00', '2026-07-12T17:37:19.666371+00:00'),
  ('103e8e33-0b66-4221-b5eb-fd647aa6dc76', NULL, 'artj-uk66260', 'תיק מפואר לטלית דמוי עור שחור אותיות בולטות "ויברכך" זהב 31X38 ס"מ', '<p>העניקו לכבוד התפילין את המקום הראוי להם עם תיק מפואר זה. עשוי דמוי עור שחור עמיד ויוקרתי, התיק מעוטר באותיות "ויברכך" בזהב בולטות, המוסיפות נופך של קדושה והדר. מידותיו הנדיבות (31X38 ס"מ) מתאימות לרוב גדלי התפילין, ומבטיחות הגנה מושלמת. המתנה המושלמת לכל יהודי ירא שמיים, המעריך איכות, יופי וכבוד לדברי קודש.</p>', 'תיק מהודר לדאלית – יוקרתיות, הגנה וכבוד לתפילין. דמוי עור שחור, עיטור זהב "ויברכך" בולט, מידות 31X38 ס"מ.', 357.14, NULL, 'UK66260', 'instock', NULL, 'https://deyidkzuvwniioxjisdr.supabase.co/storage/v1/object/public/product-images/opt/962cb17c6afdfc5e7976910f.webp', true, '2026-05-31T11:25:25.72855+00:00', '2026-07-12T17:37:06.27292+00:00'),
  ('1087a580-a0ef-4ce4-8923-6fc65a907144', NULL, 'קופת-צדקה-מפולימר-14-סמ-טבעי-82437', 'קופת צדקה מפולימר 14 ס"מ - טבעי', NULL, 'קופת צדקה מפולימר 14 ס"מ - טבעי', 202.0, NULL, 'UK82437', 'instock', NULL, 'https://deyidkzuvwniioxjisdr.supabase.co/storage/v1/object/public/product-images/opt/92f650bc0892bcfbb5f1ae67.webp', true, '2026-06-04T09:45:12.932622+00:00', '2026-07-12T17:37:15.02028+00:00'),
