  ('113c68d6-872c-4ab0-8c72-4dc1c1132bf2', NULL, 'סט-זוג-פמוטי-קריסטל-עם-מגש-מהודר-9-סמ-81471', 'סט זוג פמוטי קריסטל עם מגש מהודר 9 ס"מ', NULL, 'סט זוג פמוטי קריסטל עם מגש מהודר 9 ס"מ', 472.0, NULL, 'UK81471', 'instock', NULL, 'https://deyidkzuvwniioxjisdr.supabase.co/storage/v1/object/public/product-images/opt/2d82334757a76fca4b91192b.webp', true, '2026-06-04T09:45:11.714464+00:00', '2026-07-12T17:37:08.046093+00:00'),
  ('11682328-b330-48e4-8558-ff21f9c42118', NULL, 'סט-פולימר-מגש-להדלקת-נרות-וזוג-פמוטים-מהודרים-זהב-83144', 'סט פולימר מגש להדלקת נרות וזוג פמוטים מהודרים - זהב', NULL, 'סט פולימר מגש להדלקת נרות וזוג פמוטים מהודרים - זהב', 371.0, NULL, 'UK83144', 'instock', NULL, 'https://deyidkzuvwniioxjisdr.supabase.co/storage/v1/object/public/product-images/opt/73dc37b19c4695b7cccb1d4a.webp', true, '2026-06-04T09:45:11.92578+00:00', '2026-07-12T17:37:17.430403+00:00'),
  ('11aa8b97-9c6b-404d-afd3-d6207dd58770', NULL, 'artj-uk66732', 'תיק מפואר לטלית דמוי עור כחול אותיות בולטות "יב"', '<p>תיק טלית יוקרתי זה מותאם במיוחד לשמירה על הטלית בכבוד וקדושה. עשוי מדמוי עור איכותי בצבע כחול עמוק, הוא משלב עיצוב מודרני עם נגיעה מסורתית. האותיות "יב" בצבע זהב מבריק, מעניקות מראה מכובד ומרשים, והן בולטות למגע, ומוסיפות לאסתטיקה הכללית. תיק זה אינו רק פונקציונלי אלא גם פריט יודאיקה נאה, המהווה מתנה מושלמת או תוספת יפה לחפצי הקודש האישיים.</p>', 'תיק מהודר לטלית, עשוי דמוי עור כחול אלגנטי עם אותיות "יב" בולטות', 357.14, NULL, 'UK66732', 'instock', NULL, 'https://deyidkzuvwniioxjisdr.supabase.co/storage/v1/object/public/product-images/opt/e6bec9f9539d399fedba18f8.webp', true, '2026-05-31T11:25:25.72855+00:00', '2026-07-12T17:37:06.458005+00:00'),
  ('12e43a4d-14ee-4f15-8394-0c2bd77527f0', 2873202, 'talit-2873202', 'טלית פרימיום בחריטת לייזר בד תשבץ  100% צמר רחלים דגם ברכת כהנים במגוון צבעים', '<p>טלית ייחודית זו, עשויה 100% צמר רחלים איכותי, מציעה חוויה רוחנית יוצאת דופן. הבד בתצורת תשבץ קלאסית, משתלב נפלא עם חריטת לייזר מדויקת של ברכת כהנים, המעניקה לטלית נופך קדושה ועיצובי. כל טלית מיוצרת בקפידה, תוך הקפדה על הפרטים הקטנים, ומגיעה במגוון צבעים לבחירתכם, ליצירת פריט אישי ומרגש לתפילה.</p>', 'טלית פרימיום בתשבץ צמר רחלים טהור, מעוטרת בברכת כהנים בחריטת לייזר. איכות ללא פשרות, עיצוב מרהיב.', 1286.0, NULL, NULL, 'instock', NULL, 'https://deyidkzuvwniioxjisdr.supabase.co/storage/v1/object/public/product-images/opt/6afc271e8b72a5d42528b243.webp', true, '2026-05-31T11:10:09.145533+00:00', '2026-07-12T17:37:21.411627+00:00'),
  ('12f1504e-b522-4d2c-999c-2a7f9c7209ed', NULL, 'tehillim-avodah-shebalev-black', 'תהילים עבודה שבלב - כריכת כותל שחור', NULL, 'תהילים עבודה שבלב בכריכה מהודרת בעיצוב אבני הכותל בגוון שחור עם כיתוב כסוף', 130.0, 111.0, NULL, 'instock', 50, 'https://deyidkzuvwniioxjisdr.supabase.co/storage/v1/object/public/product-images/opt/944f991bf2b48dcbae5bbbe1.webp', true, '2026-06-16T13:29:21.438221+00:00', '2026-07-12T17:37:10.984825+00:00'),
  ('131b7769-e6d5-4340-8b1a-7572c03d42d6', 2872375, 'chal-2872375', 'כיסוי לתלתל שלי לבן שחור', '<p>הוסיפו מימד של הוד והדר לתפילה עם כיסוי ייחודי זה לתפילין. מעוצב בשילוב קלאסי של לבן ושחור, הוא משדר יוקרה וקדושה. עשוי מבדים משובחים, כיסוי זה נועד להגן על התפילין שלכם לאורך זמן, ולהבטיח שישמרו על שלמותם. מתנה מושלמת לעצמכם או ליקירכם, המשלבת יופי, פונקציונליות ורוחניות.</p>', 'כיסוי לתפילין, אלגנטי ואיכותי, מוסיף הוד והדר בכל תפילה.', 86.0, NULL, NULL, 'instock', NULL, 'https://deyidkzuvwniioxjisdr.supabase.co/storage/v1/object/public/product-images/opt/7242d0af390568a12319ea72.webp', true, '2026-05-31T11:30:03.111272+00:00', '2026-07-12T17:37:08.004619+00:00'),
  ('136bb7fa-d2e3-4d5e-96ee-dad63801e2af', NULL, 'artj-uk67722', 'תיק מפואר לטלית תפילין עם ידית 31X41 ס"מ', '<p>תנו לטלית ולתפילין שלכם את הכבוד הראוי להן עם התיק המפואר הזה. מעוצב בקפידה, הוא ישמש לא רק ככלי אחסון אלא גם כהצהרה אסתטית. עשוי מחומרים איכותיים, התיק (במידות 31X41 ס"מ) מבטיח שמירה על הפריטים היקרים מפז. הידית הנוחה שלו הופכת את הנשיאה לקלה ונעימה, אידיאלי לתפילות בבית הכנסת או לנסיעות. זהו הפריט המושלם שישלב בין הוד קדושה ליוקרה.</p>', 'תיק מהודר לטלית ותפילין, בעיצוב אלגנטי ומרשים, עם ידית נוחה לנשיאה. מתנה מושלמת לכל אירוע.', 400.0, NULL, 'UK67722', 'instock', NULL, 'https://deyidkzuvwniioxjisdr.supabase.co/storage/v1/object/public/product-images/opt/aa96694fff8e19a4e41fc9c2.webp', true, '2026-05-31T11:25:25.72855+00:00', '2026-07-12T17:37:21.705382+00:00'),
  ('140da789-2cfa-44a8-a423-04f40f162910', 2000, 'זוג-פמוטי-קריסטל-אלגנטיים-9-סמ-3', 'זוג פמוטי קריסטל אלגנטיים 9 ס"מ', '<p>הוסיפו ניצוץ של אלגנטיות לשולחן השבת או החג עם זוג פמוטי הקריסטל המרהיבים שלנו. בגובה 9 ס"מ, הם משלבים עיצוב קלאסי עם ברק זוהר, ויוצרים אווירה חמה ומזמינה. צפו בלהבות הנרות משתקפות בקריסטל הבוהק, מוסיפות עומק וקסם לכל רגע. מתנה אידיאלית לכל בית יהודי, או פינוק אישי שילווה אתכם שנים רבות.</p>', 'פמוטי קריסטל 9 ס"מ - נגיעה של יוקרה לבית. אור יקר ושמחה בכל ערב שבת וחג.', 336.0, 279.98, 'UK42124', 'instock', NULL, 'https://deyidkzuvwniioxjisdr.supabase.co/storage/v1/object/public/product-images/opt/d3b30d54a5e61d077bbd6207.webp', true, '2026-05-10T16:10:19.018791+00:00', '2026-07-12T17:37:11.839846+00:00'),
  ('156b3fc1-a4f3-4a10-9003-7d2c900d1619', NULL, 'פמוטי-נסיעה-ניקל-בקופסא-עם-מכסה-ירושלים-4x9-סמ-86870', 'פמוטי נסיעה ניקל בקופסא עם מכסה "ירושלים" 4x9 ס"מ', NULL, 'פמוטי נסיעה ניקל בקופסא עם מכסה "ירושלים" 4x9 ס"מ', 169.0, NULL, 'UK86870', 'instock', NULL, 'https://deyidkzuvwniioxjisdr.supabase.co/storage/v1/object/public/product-images/opt/c6d96e127cee30423d76577d.webp', true, '2026-06-04T09:45:12.555182+00:00', '2026-07-12T17:37:14.531059+00:00'),
  ('16767856-8794-4d6e-86e9-2f5e01987e63', 2029, 'ברכות-הפרשת-חלה-דמוי-עור-לבן-40-סמ', 'ברכות "הפרשת חלה" דמוי עור - לבן 40 ס"מ', '<p>הוסיפו נגיעה של קדושה ויופי לביתכם עם ברכת הפרשת חלה מעוצבת זו. עשויה מעור דמוי איכותי בגוון לבן נקי, בגודל מרשים של 40 ס"מ, היא מהווה פריט יודאיקה מהודר ואלגנטי. הברכה מעוטרת בעיצוב מרהיב, המוסיף חן ורוחניות לכל מטבח או פינת אוכל, ומזכירה את קדושת המצווה והמסורת.</p>', 'העניקו קדושה לביתכם עם ברכת הפרשת חלה יפהפייה מעור דמוי לבן, בגודל 40 ס"מ.', 120.0, 99.98, 'UK67158', 'instock', NULL, 'https://deyidkzuvwniioxjisdr.supabase.co/storage/v1/object/public/product-images/opt/4d75cce060410e618742c54c.webp', true, '2026-05-10T16:10:19.018791+00:00', '2026-07-12T17:37:20.17979+00:00'),
  ('16bb0547-0df1-4221-abaa-479c9c459aa4', 2871455, 'talit-2871455', 'טלית תשבץ  צמר פסים בצבע שחור עם עטרה שחורה יוקרתית שויתי ה'' לנגדי תמיד בצבע כסוף', '<p>התעטפו באווירה של קדושה ויופי עם טלית התשבץ המרהיבה הזו, עשויה 100% צמר משובח. עיצוב הפסים השחורים הקלאסי משתלב בהרמוניה עם העטרה היוקרתית, המעוטרת באמירת ''שויתי ה'' לנגדי תמיד'' בכסף מנצנץ. זוהי לא רק טלית, אלא יצירת אמנות רוחנית שתלווה אתכם בתפילותיכם ותעשיר כל רגע של התבוננות.</p>', 'טלית תשבץ צמר איכותית בעיצוב פסים שחור-כסף, עם עטרה יוקרתית ''שויתי ה'' לנגדי תמיד'' בכסף זוהר.', 1286.0, NULL, NULL, 'instock', NULL, 'https://deyidkzuvwniioxjisdr.supabase.co/storage/v1/object/public/product-images/opt/d4b60cd404367917d18531fd.webp', true, '2026-05-31T11:10:09.145533+00:00', '2026-07-12T17:37:17.149369+00:00'),
  ('16f08d72-c5e8-4bda-9d61-f2330453b635', 2871978, 'talit-2871978', 'טלית פלטניום תשבץ 100% צמר רחלים דגם האש שלי תוקד עטרה פינות וגב בצבע תכלת', '<p>טלית זו, העשויה מ-100% צמר רחלים איכותי במיוחד, משלבת יוקרה ומסורת. דוגמת התשבץ האלגנטית משדרת עוצמה ויופי, בעוד עטרת "האש שלי תוקד" המרוממת מוסיפה עומק רוחני וחיבור למורשת היהודית. העיטורים בפינות הטלית ובגבה, בצבע תכלת ענוג, משלימים את המראה המרהיב והמלכותי. טלית זו היא פריט יודאיקה איכותי שילווה את בעליו בתפילות ובאירועים מיוחדים לאורך שנים.</p>', 'טלית צמר יוקרתית בדוגמת תשבץ, עטורה בעיטור "האש שלי תוקד" בצבע תכלת.', 1572.0, NULL, NULL, 'instock', NULL, 'https://deyidkzuvwniioxjisdr.supabase.co/storage/v1/object/public/product-images/opt/75fee1b5af6d018562329c96.webp', true, '2026-05-31T11:10:09.145533+00:00', '2026-07-12T17:37:19.539209+00:00'),
  ('172aeb58-1ad0-4da2-b56d-ab5e0c2e0388', 1369, 'כוס-כביסה-פולימרית-14-סמ-2', 'כוס כביסה פולימרית 14 ס"מ', '<p>הוסיפו נגיעה של יופי וקדושה לשולחן השבת או לכל אירוע משמח עם כוס הקידוש והכביסה המעוצבת שלנו. עשויה מפולימר איכותי ועמיד, היא מציעה פתרון אלגנטי ופרקטי לכוס קידוש או כוס כביסה. העיצוב המוקפד והגודל האידיאלי (14 ס"מ) הופכים אותה לפריט שימושי ומרשים בכל בית יהודי.</p>', 'כוס קידוש וכביסה יפהפייה מפולימר עמיד, בקוטר 14 ס"מ. מתאימה גם לשימוש יומיומי וגם לאירועים מיוחדים.', 185.0, 109.98, 'UK42707', 'instock', NULL, 'https://deyidkzuvwniioxjisdr.supabase.co/storage/v1/object/public/product-images/opt/96a3362a5c6eece80b38f2be.webp', true, '2026-05-10T16:10:19.018791+00:00', '2026-07-12T17:37:13.182373+00:00'),
  ('1760ae05-a474-4bd9-b316-231b39a0a993', NULL, 'product-39', 'סידור מעוצב כתר מובלט לגבר קורדרוי אפור כהה', '<p>סידור תפילה אלגנטי ומרשים, הבחירה המושלמת עבור הגבר המודרני המחפש חיבור עמוק ומיוחד. כתר ה'' המוזהב, המעוצב בהבלטה מרהיבה, מוסיף נופך מלכותי ומשרטט את גבולות הקדושה. כריכת הקורדרוי בגוון אפור כהה, רכה ונעימה למגע, מבטיחה עמידות וסטייל לאורך שנים. סידור זה אינו רק ספר תפילה, אלא חפץ קודש אישי, מתנה יקרת ערך לכל גבר, המסמלת הערכה, אהבה וקשר אלוהי.</p>', 'סידור תפילה יוקרתי בסגנון מודרני, מעוצב עם כתר ה'' מוזהב בולט, בכריכת קורדרוי אפור עמוק לגבר. מתנה מושלמת לכל אירוע.', 186.0, NULL, NULL, 'instock', NULL, 'https://deyidkzuvwniioxjisdr.supabase.co/storage/v1/object/public/product-images/opt/02b187636a7b8b2d1b0399b7.webp', true, '2026-05-31T11:04:26.373999+00:00', '2026-07-12T17:37:15.309862+00:00'),
  ('17d477fa-8d0c-483d-8ef6-fcc7e2aade58', NULL, 'artj-uk60314', 'סט מפואר לטלית דמוי עור שחור אותיות בולטות', '<p>העניקו משמעות לכל תפילה עם סט טלית דמוי עור שחור מהודר זה. האלגנטיות של הדמוי עור האיכותי, בשילוב עם האותיות הבולטות והמוקפדות, יוצרים מראה יוקרתי ומרשים. הסט כולל כיסוי לטלית ומארז לתפילין, המותאמים בגודלם לנוחות שימוש מירבית. מתנה אידיאלית לבר מצווה, חגיגות אישיות או סתם כדי לפנק את עצמכם בפריט תפילה נצחי.</p>', 'סט מהודר לטלית - דמוי עור שחור יוקרתי עם אותיות בולטות. מתנה מושלמת לבר מצווה ולכל אירוע.', 357.14, NULL, 'UK60314', 'instock', NULL, 'https://deyidkzuvwniioxjisdr.supabase.co/storage/v1/object/public/product-images/opt/1e34d66a92ba3230573944e7.webp', true, '2026-05-31T11:25:25.72855+00:00', '2026-07-12T17:37:06.486478+00:00'),
  ('17e5b6f8-7990-4f83-b345-7689bbc30a04', 2048, 'פמוטי-קריסטל-7-5-סמ-עם-לוחית-מתכת-2', 'פמוטי קריסטל 7.5 ס"מ עם לוחית מתכת', '<p>הוסיפו אור וקסם לשבת או לחג עם פמוטי הקריסטל המרהיבים הללו, בגובה 7.5 ס"מ. כל פמוט משלב את הברק הצלול של הקריסטל עם עיטור מודרני של לוחית מתכת, היוצר שילוב הרמוני של מסורת ועיצוב עכשווי. הם מושלמים להצבה על שולחן השבת, אדן החלון, או כמתנה מיוחדת לאירוע משמעותי. האור הנשבר דרך הקריסטל ייצור אווירה חמה ומרשימה בביתכם.</p>', 'פמוטי קריסטל עדינים בגודל 7.5 ס"מ, מעוטרים בלוחית מתכת אלגנטית. מוסיפים נגיעה של חן ויופי לכל חלל.', 120.0, 99.98, 'UK81821', 'instock', NULL, 'https://deyidkzuvwniioxjisdr.supabase.co/storage/v1/object/public/product-images/opt/2c8d16cd18f40735f411663e.webp', true, '2026-05-10T16:10:19.018791+00:00', '2026-07-12T17:37:18.188639+00:00'),
  ('18ddac9f-000a-42b4-aedf-6b8ea27cc0bd', NULL, 'מזוזה-סמנט-בטון-רחבה-גוון-לבן-ש-להבה-זהב-20810', 'מזוזה "סמנט בטון" רחבה גוון לבן "ש" להבה זהב', NULL, 'מזוזה "סמנט בטון" רחבה גוון לבן "ש" להבה זהב', 152.0, NULL, 'UK20810', 'instock', NULL, 'https://deyidkzuvwniioxjisdr.supabase.co/storage/v1/object/public/product-images/opt/61885ec1505c4c3684dc5616.webp', true, '2026-06-04T09:45:25.52475+00:00', '2026-07-12T17:37:13.003245+00:00'),
  ('19b1b1a0-28dc-40a0-bd63-501b96699287', 2234, 'כוס-לחתן-10-סמ-עם-הכיתוב-אם-אשכך', 'כוס לחתן 10 ס"מ - עם הכיתוב "אם אשכך"', '<p>כוס זו, בגובה 10 ס"מ, עוצבה במיוחד עבור החתן, והיא נושאת את הכיתוב הנוגע ללב "אם אשכחך ירושלים". הכוס עשויה חומרים איכותיים (יש לציין חומר כמו: זכוכית, מתכת, קרמיקה - לפי המוצר בפועל) ומהווה תוספת אלגנטית ומלאת משמעות לחגיגת החתונה. היא תשמש תזכורת יומיומית לחיבור לשורשים ולמורשת, ותהיה מתנה מושלמת ומרגשת לחתן, המסמלת את תחילת דרכו החדשה בברכה ובקדושה.</p>', 'כוס לחתן מעוצבת, 10 ס"מ, עם הכיתוב "אם אשכחך ירושלים" – מתנה מרגשת לחגיגת החתונה.', 40.0, 23.98, 'UK89928', 'instock', NULL, 'https://deyidkzuvwniioxjisdr.supabase.co/storage/v1/object/public/product-images/opt/4b27fc18f2428c9eb290f703.webp', true, '2026-05-10T16:10:19.018791+00:00', '2026-07-12T17:37:13.143231+00:00'),
  ('19c8188e-f7a1-49fc-b62a-8c7241481dbe', 2872450, 'chal-2872450', 'כיסוי לטלית חלאקה לבן רקמה בצבע זהב', '<p>הכירו את כיסוי הטלית המרהיב הזה, שעוצב במיוחד עבור טקס החלאקה. עשוי מבד לבן איכותי, הוא מעוטר ברקמה עדינה ובוהקת בצבע זהב, המוסיפה יוקרה וקדושה. זהו פריט שישמר את זכר היום המיוחד הזה לשנים רבות, ויהווה מתנה מרגשת לילד ולמשפחתו.</p>', 'כיסוי מהודר לטלית חלאקה, רקום בעבודת יד מוזהבת. מתנה מיוחדת ליום הגדול.', 129.0, NULL, NULL, 'instock', NULL, 'https://deyidkzuvwniioxjisdr.supabase.co/storage/v1/object/public/product-images/opt/127a3a64f876080d67f4b6a1.webp', true, '2026-05-31T11:30:03.111272+00:00', '2026-07-12T17:37:07.9374+00:00'),
  ('1a687012-e3d3-4b5b-a7b2-8c19a1e3371b', NULL, 'product-28', 'סידור כתר לגבר לבן הטבעה בזהב', '<p>סידור תפילה ''כתר'' לגבר, בעיצוב קלאסי ובגוון לבן רגוע, מעוטר בהטבעת זהב עשירה ומדויקת. הסידור עשוי מחומרים איכותיים, מבטיח עמידות ויופי לאורך שנים. כל דף עוצב בקפידה, ומזמין אותך לחוויית תפילה עשירה ומרגשת. מתנה מושלמת לגבר המעריך יופי, מסורת ואיכות.</p>', 'סידור כתר לגבר: אלגנטיות נצחית עם הטבעת זהב עדינה. השלם את מראה התפילה שלך.', 186.0, NULL, NULL, 'instock', NULL, 'https://deyidkzuvwniioxjisdr.supabase.co/storage/v1/object/public/product-images/opt/d305f5a3303e05517dd71a06.webp', true, '2026-05-31T11:04:26.373999+00:00', '2026-07-12T17:37:14.821902+00:00'),
  ('1b707e56-b44a-4b4b-97bb-28990b432ce3', 2085, 'ברכה-ממוסגרת-עם-לבנים-לבנות-ולוח-מתכת-3324', 'ברכה ממוסגרת עם לבנים לבנות ולוח מתכת 33*24 ס"מ - אשת חיל', '<p>העניקו מתנה יקרת ערך עם ברכת "אשת חיל" ממוסגרת, יצירת אמנות מרשימה המשלבת לבנים לבנות עדינות עם לוח מתכת מלוטש, בגודל 34*24 ס"מ. כל ברכה מיוצרת בקפידה, ומבטיחה איכות ועמידות לאורך שנים. מושלמת כמתנה מרגשת לכל אירוע חשוב, היא תעשיר כל חלל בבית ותזכיר את עוצמתה והשראתה של האישה המוערכת.</p>', 'ברכה ממוסגרת "אשת חיל" - שילוב יוקרתי של לבנים לבנות ולוח מתכת, בעיצוב מרשים 33*24 ס"מ.', 202.0, 119.98, 'UK47799', 'instock', NULL, 'https://deyidkzuvwniioxjisdr.supabase.co/storage/v1/object/public/product-images/opt/6096b5e40ef234c3e7f88a09.webp', true, '2026-05-10T16:10:19.018791+00:00', '2026-07-12T17:37:13.86055+00:00'),
  ('1e91b0a3-3d0c-4cce-baa8-f320c1c668d1', 2872408, 'chal-2872408', 'סט חלאקה פרימיום דגם כתר רקמה בזהב', '<p>חגגו את טקס החלאקה הראשונה בתכם בסט פרימיום מעוצב - "כתר רקמה בזהב". הסט כולל את כל הפריטים הדרושים לטקס, רקומים בעבודת יד מרהיבה בחוטי זהב אמיתיים, המעניקים מגע מלכותי ויוקרתי. זוהי מתנה שתשמור על זיכרון מתוק לשנים רבות, ותהפוך את הרגע הקדוש לחוויה של קסם והוד.</p>', 'סט חלאקה יוקרתי "כתר רקמה בזהב" - מתנה בלתי נשכחת ליום המיוחד.', 471.0, NULL, NULL, 'instock', NULL, 'https://deyidkzuvwniioxjisdr.supabase.co/storage/v1/object/public/product-images/opt/145571085e185ee8b429e77b.webp', true, '2026-05-31T11:30:03.111272+00:00', '2026-07-12T17:37:07.157865+00:00'),
  ('20440dc3-7e2e-44fa-a7eb-b92e269e1823', 1374, 'כוס-כביסה-פולימרית-14-סמ', 'כוס כביסה פולימרית 14 ס"מ', '<p>הוסיפו נגיעה של אלגנטיות ופשטות לבית עם כוס הכיור הפולימרית הייחודית שלנו. בגובה 14 ס"מ, היא משתלבת באופן מושלם בכל חלל, בין אם בחדר האמבטיה או במטבח. הכוס עשויה מחומר פולימרי איכותי, קל ועמיד, המבטיח שימוש נוח לאורך שנים. עיצובה הנקי והמודרני הופך אותה לפריט פונקציונלי ואסתטי כאחד, המזמין אתכם להתחיל את היום באווירה של רוגע וקדושה.</p>', 'כוס כיור פולימרית מעוצבת, 14 ס"מ גובה. אידיאלית לנטילת ידיים בבוקר או לצרכי מקווה.', 132.0, 109.98, 'UK42710', 'instock', NULL, 'https://deyidkzuvwniioxjisdr.supabase.co/storage/v1/object/public/product-images/opt/c2ad6059474a121c54d6a33d.webp', true, '2026-05-10T16:10:19.018791+00:00', '2026-07-12T17:37:19.97327+00:00'),
  ('205ad406-a51d-4f40-b952-5aab9ac378a8', NULL, 'נטלה-מהודרת-מפולימר-ציפוי-כסף-14-סמ-82836', 'נטלה מהודרת מפולימר ציפוי כסף 14 ס"מ', NULL, 'נטלה מהודרת מפולימר ציפוי כסף 14 ס"מ', 202.0, NULL, 'UK82836', 'instock', NULL, 'https://deyidkzuvwniioxjisdr.supabase.co/storage/v1/object/public/product-images/opt/dcb7a312089bf2d35edff41c.webp', true, '2026-06-04T09:45:21.974636+00:00', '2026-07-12T17:37:12.449367+00:00'),
  ('20db5f7e-e75c-4c10-8817-1fe5193e7da9', 2872457, 'chal-2872457', 'סט חלאקה פרימיום דגם כתר רקמה בכסף כיסוי לטלית ולתלתל', '<p>אלגנטיות וקדושה מתחברות בסט החלאקה ''כתר רקמה'' היוקרתי. סט זה, מעוצב בכסף טהור ומעוטר ברקמה עדינה, הופך את טקס החלאקה לחוויה בלתי נשכחת. כולל כיסוי מרהיב לטלית ולתלתל, המשלב עיצוב קלאסי עם יוקרה מודרנית, זהו פריט אידיאלי כמתנה לבר מצווה שתלווה את הילד במסעו הרוחני.</p>', 'סט חלאקה פרימיום ''כתר רקמה'' – מתנה מלכותית לבר מצווה, מאוצרת בכסף טהור.', 729.0, NULL, NULL, 'instock', NULL, 'https://deyidkzuvwniioxjisdr.supabase.co/storage/v1/object/public/product-images/opt/fc4ff4fe22e0640e1bc2b362.webp', true, '2026-05-31T11:30:03.111272+00:00', '2026-07-12T17:37:20.129939+00:00'),
  ('20f2d985-2945-4cb6-8e2b-d1ba4c2f2941', NULL, 'כרית-מהודרת-לברית-דמוי-עור-עם-אותיות-בולטות-74x50-סמ-66857', 'כרית מהודרת לברית דמוי עור עם אותיות בולטות 74x50 ס"מ', NULL, 'כרית מהודרת לברית דמוי עור עם אותיות בולטות 74x50 ס"מ', 428.57, NULL, 'UK66857', 'instock', NULL, 'https://deyidkzuvwniioxjisdr.supabase.co/storage/v1/object/public/product-images/opt/06fb3bc2ecb4539589f70406.webp', true, '2026-06-04T09:45:19.134547+00:00', '2026-07-12T17:37:17.884673+00:00'),
  ('21ef511d-c212-456f-b151-cf2e76b0ff4d', NULL, 'product-9', 'סידור מעוצב האש שלי לגבר ג''ינס צבע שחור מט', '<p>הדלק את להבת התפילה שלך עם סידור ''האש שלי'', מעוצב במיוחד לגבר המודרני. הכריכה המרהיבה בגוון ג''ינס שחור מט מעניקה לו מראה יוקרתי וייחודי, המושלם לכל גבר שמחפש תפילה עם אמירה אישית. הסידור מכיל את כל תפילות השבת וחג, כתובות באותיות ברורות וקריאות, על נייר משובח. זהו לא רק סידור תפילה, אלא פריט אופנתי שינעם לך בכל שימוש.</p>', 'סידור תפילה ''האש שלי'' לגבר, בעיצוב ג''ינס שחור מט – תפילה בסטייל.', 186.0, NULL, NULL, 'instock', NULL, 'https://deyidkzuvwniioxjisdr.supabase.co/storage/v1/object/public/product-images/opt/c0c44f1d3ecbc53cb6eb369d.webp', true, '2026-05-31T11:04:26.373999+00:00', '2026-07-12T17:37:14.000891+00:00'),
  ('221dbe61-e948-4a13-b7c5-440e0df519e4', NULL, 'laser-misgan-habayit', 'משגן הבית - חיתוך לייזר', NULL, 'לוח אקרילי שקוף בחיתוך לייזר לברכת הבית', 357.0, NULL, NULL, 'instock', NULL, 'https://deyidkzuvwniioxjisdr.supabase.co/storage/v1/object/public/product-images/opt/58b118949ac1bea93542c8e7.webp', true, '2026-06-21T12:45:15.77172+00:00', '2026-07-12T17:37:14.03562+00:00'),
  ('223b4cff-a7e0-4541-9dff-dc2d342d2297', NULL, 'כיפה-קטיפה-ארט-מן-אותיות-בולטות-זהב-האש-שלי-אופוויט-גודל-4-10515', 'כיפה קטיפה "ארט-מן" אותיות בולטות זהב "האש שלי" - אופוויט (גודל 4)', NULL, 'כיפה קטיפה "ארט-מן" אותיות בולטות זהב "האש שלי" - אופוויט (גודל 4)', 67.0, 40.0, 'UK10515', 'instock', NULL, 'https://deyidkzuvwniioxjisdr.supabase.co/storage/v1/object/public/product-images/opt/e5dc1c29768847fa0c458729.webp', true, '2026-06-04T09:45:18.771462+00:00', '2026-07-12T17:37:12.105466+00:00'),
  ('23a1265d-84fc-42ce-bb5f-4bb1b68d83d6', 2445, 'מזוזה-פולימרית-לבנה-12-סמ', 'מזוזה פולימרית לבנה 12 ס"מ', '<p>הוסיפו נגיעה של שלווה ויופי לפתח ביתכם עם מזוזה פולימרית לבנה, בגודל 12 ס"מ. עיצובה המינימליסטי והאלגנטי מתאים לכל סגנון עיצוב, והצבע הלבן מסמל טוהר וברכה. עשויה מחומר פולימרי איכותי, היא עמידה ומרשימה, ותשמש כמגן וכסמל רוחני לביתכם לאורך שנים. מתנה נפלאה ומלאת משמעות לכל מי שאתם אוהבים.</p>', 'מזוזה פולימרית לבנה, 12 ס"מ – עיצוב נקי וטוהר לביתכם. מתנה מושלמת וברכה לכל מקום.', 96.0, 79.98, 'UK20693', 'instock', NULL, 'https://deyidkzuvwniioxjisdr.supabase.co/storage/v1/object/public/product-images/opt/7e48eedc2cf4a34848c0d5d4.webp', true, '2026-05-10T16:10:19.018791+00:00', '2026-07-12T17:37:21.060052+00:00'),
  ('23e55908-6d07-4406-a5db-049d87e1377b', 2874418, 'chal-2874418', 'סט חלאקה קלאסי דגם האש שלי רקמה כסופה וחריטה על המספריים', '<p>הפכו את טקס החלאקה לחוויה בלתי נשכחת עם סט ''האש שלי'' היוקרתי. הסט כולל מספריים איכותיים עם חריטה אישית, לצד פריטי חלאקה משלימים. הרקמה הכסופה העדינה על הפריטים מוסיפה נופך של קסם והוד, והופכת את הסט למזכרת מרגשת שתלווה את ילדכם שנים רבות. סט זה הוא לא רק כלי ליום מיוחד, אלא יצירת אומנות קטנה ואישית.</p>', 'סט חלאקה קלאסי ''האש שלי'' - מתנה מושלמת ליום הולדת עם רקמה כסופה יוקרתית וחריטה ייחודית.', 400.0, NULL, NULL, 'instock', NULL, 'https://deyidkzuvwniioxjisdr.supabase.co/storage/v1/object/public/product-images/opt/cc568e6c6117db0b177ebf12.webp', true, '2026-05-31T11:30:03.111272+00:00', '2026-07-12T17:37:08.021692+00:00'),
  ('248782df-2421-4ea3-b739-aac83b9e8c7c', 2160, 'טלית-דמוי-עור-סט-תפילין-3629-סמ-עם-לוגו-מוט', 'טלית דמוי עור - סט תפילין 36*29 ס"מ עם לוגו מוטבע - שחור', '<p>הסט המושלם לתפילין, המשלב איכות, סטייל ומסורת. עשוי מעור סינטטי משובח, הסט בעל מראה יוקרתי ומרשים, עם לוגו מוטבע המוסיף טאץ'' אישי. נוח ופרקטי לאחסון ולנשיאת התפילין, בגודל 36*29 ס"מ, בצבע שחור קלאסי. מתנה אידיאלית לכל אדם שומר מצוות, המעוניין בשמירה על כבודם של דברי קודש.</p>', 'סט תפילין יוקרתי מעור איכותי, מעוצב עם לוגו מוטבע. גודל 36*29 ס"מ, בצבע שחור אלגנטי.', 357.14, NULL, 'UK66585', 'instock', NULL, 'https://deyidkzuvwniioxjisdr.supabase.co/storage/v1/object/public/product-images/opt/4135c32c619262a3da187710.webp', true, '2026-05-10T16:10:19.018791+00:00', '2026-07-12T17:37:18.557245+00:00'),
  ('248f550f-8265-4222-b8d0-6ab04cd39452', 2042, 'פמוטי-קריסטל-19-5-סמ-עם-לוחית-מתכת', 'פמוטי קריסטל 19.5 ס"מ עם לוחית מתכת', '<p>הוסיפו נגיעה של זוהר וקדושה לשבת ולחגים עם פמוטי קריסטל יפהפיים אלו, בגובה מרשים של 19.5 ס"מ. כל פמוט משלב את הברק הצלול של הקריסטל עם חמימותה של לוחית מתכת מעוצבת, היוצרת שילוב קלאסי ומודרני. הפמוטים אידיאליים להדלקת נרות שבת, נרות יום הזיכרון או כל אירוע מיוחד, ומעניקים אווירה של שלווה ורוממות. מתנה נפלאה לכל בית יהודי.</p>', 'פמוטי קריסטל מרהיבים בגובה 19.5 ס"מ, מעוטרים בלוחית מתכת אלגנטית. השלימו את אווירת השבת והחג עם נרות מהבהבים.', 192.0, 159.98, 'UK40458', 'instock', NULL, 'https://deyidkzuvwniioxjisdr.supabase.co/storage/v1/object/public/product-images/opt/a8a615463cd368be09478cc4.webp', true, '2026-05-10T16:10:19.018791+00:00', '2026-07-12T17:37:19.675675+00:00'),
  ('251f45de-bd38-499e-b1c0-7259446b9c30', NULL, 'זוג-פמוטי-קריסטל-מרובע-עם-פלקטה-עיטור-8-סמ-טבעי-49203', 'זוג פמוטי קריסטל מרובע עם פלקטה "עיטור" 8 ס"מ - טבעי', NULL, 'זוג פמוטי קריסטל מרובע עם פלקטה "עיטור" 8 ס"מ - טבעי', 135.0, NULL, 'UK49203', 'instock', NULL, 'https://deyidkzuvwniioxjisdr.supabase.co/storage/v1/object/public/product-images/opt/7439075ee69d844811109ff3.webp', true, '2026-06-04T09:45:11.42644+00:00', '2026-07-12T17:37:07.11855+00:00'),
  ('2531e59f-0da2-47b7-ada0-0605a0452e37', 1151, 'כוס-קידוש-קריסטל-16-סמ-מכילה-100-מל-3-4-אונקיו-2', 'כוס קידוש קריסטל 16 ס"מ מכילה 100 מ"ל / 3.4 אונקיות', '<p>הוסיפו ברק ושמחה לקידוש שלכם עם כוס זו, עשויה קריסטל בוהק וצלול. גובהה 16 ס"מ וקיבולתה 100 מ"ל, אידיאלית לברכת היין. עיצובה האלגנטי משדר יוקרה ומכובד, והיא תהווה מתנה מושלמת לכל בית יהודי, לשבתות, חגים או אירועים מיוחדים. תנו ליין לזהור בכוס שתכבד את המסורת ותעשיר את הרגע.</p>', 'כוס קידוש קריסטל מעוצבת - 16 ס"מ גובה, 100 מ"ל נפח. יוקרה ושמחה לכל שבת וחג.', 168.0, 139.98, 'UK40229', 'instock', NULL, 'https://deyidkzuvwniioxjisdr.supabase.co/storage/v1/object/public/product-images/opt/bb8ae86c4496794598624b6a.webp', true, '2026-05-10T16:10:19.018791+00:00', '2026-07-12T17:37:08.850892+00:00'),
  ('2623d61c-665d-4acc-9616-8ed4d88e7417', 2871988, 'talit-2871988', 'טלית פלטניום תשבץ 100% צמר רחלים דגם שויתי עטרה פינות וגב בצבע אבן', '<p>הטלית פלטניום בדגם שויתי מציעה חוויה רוחנית ייחודית. עשויה 100% צמר רחלים משובח, היא נושמת ורכה למגע, ומבטיחה נוחות מרבית בתפילה. עיצוב תשבץ אלגנטי, עם עטרה, פינות וגב בצבע אבן, מוסיף נופך של קדושה ויוקרה. טלית זו היא יותר מסתם פריט לבוש; היא חיבור עמוק למסורת, עטופה באסתטיקה מודרנית.</p>', 'טלית פלטניום יוקרתית, 100% צמר רחלים, דגם שויתי. עיצוב מושלם לעטרת חזיונותיך.', 1572.0, NULL, NULL, 'instock', NULL, 'https://deyidkzuvwniioxjisdr.supabase.co/storage/v1/object/public/product-images/opt/a824ba1d30032f7d34a2f855.webp', true, '2026-05-31T11:10:09.145533+00:00', '2026-07-12T17:37:16.48695+00:00'),
  ('26ee5df0-10f9-4efd-b661-abead5025224', NULL, 'מזוזה-פולימר-בטון-ברוך-אתה-24447', 'מזוזה "פולימר בטון" ברוך אתה', NULL, 'מזוזה "פולימר בטון" ברוך אתה', 114.0, NULL, 'UK24447', 'instock', NULL, 'https://deyidkzuvwniioxjisdr.supabase.co/storage/v1/object/public/product-images/opt/155ca1bb0ffd7ee87667031f.webp', true, '2026-06-04T09:45:25.91304+00:00', '2026-07-12T17:37:12.90131+00:00'),
  ('275e79fa-4470-4c50-9e63-ce056867be8f', NULL, 'artj-uk67134', 'תיק מפואר לטלית דמוי עור "פשתן" 31X38 ס"מ', '<p>שדרגו את חווית העונג שלכם עם תיק מהודר ומפואר לדֻּכְנַת הטלית שלכם, בגודל אידיאלי של 31X38 ס"מ. התיק עשוי דמוי עור איכותי ''פשתן'', המעניק מראה יוקרתי ותחושה נעימה למגע. עיצובו האלגנטי והקפידה על הפרטים הקטנים מבטיחים שהטלית שלכם תישמר מכל משמר, תמיד במראה הכי מכובד. התיק הזה הוא גם מתנה ייחודית ומכובדת לכל אירוע.</p>', 'תיק מהודר לדֻּכְנַת הטלית, מעוצב בדמוי עור יוקרתי ''פשתן''. מתנה מושלמת ומרשימה.', 357.14, NULL, 'UK67134', 'instock', NULL, 'https://deyidkzuvwniioxjisdr.supabase.co/storage/v1/object/public/product-images/opt/34893f7e38a7926c87504990.webp', true, '2026-05-31T11:25:25.72855+00:00', '2026-07-12T17:37:10.598019+00:00'),
  ('295e3dd8-9202-4ea4-9a4b-0ca8bd1269bc', 2871979, 'talit-2871979', 'טלית פלטניום תשבץ 100% צמר רחלים דגם כהנים עטרה פינות וגב בצבע תכלת', '<p>טלית פלטניום דגם כהנים - עשויה 100% צמר רחלים משובח, הרגיש למגע ובעל ברק טבעי. עיצוב תשבץ מודרני משתלב עם עטרת כהנים ועוד 4 פינות וגב בצבע תכלת עדין, המעניקים טאץ'' מלכותי ומיוחד. הטלית מגיעה באריזה מהודרת, ומהווה מתנה מושלמת ומכובדת לכל אירוע, או חידוש מרגש לארון ההלבשה שלכם.</p>', 'טלית פלטניום יוקרתית, 100% צמר רחלים דק, בעיצוב תשבץ אלגנטי. עטרת כהנים ותכלת לטאץ'' מלכותי.', 1572.0, NULL, NULL, 'instock', NULL, 'https://deyidkzuvwniioxjisdr.supabase.co/storage/v1/object/public/product-images/opt/d6c78c9909adc1a5e8912415.webp', true, '2026-05-31T11:10:09.145533+00:00', '2026-07-12T17:37:12.154108+00:00'),
  ('296f930f-5679-4f04-9c5f-a3e29683a6f7', NULL, 'mizmor-bat-kol', 'מזמור בת קול', NULL, 'מזמור לתודה - חיתוך לייזר', 929.0, NULL, NULL, 'instock', NULL, 'https://deyidkzuvwniioxjisdr.supabase.co/storage/v1/object/public/product-images/opt/a8d5d9bf07af6828f23fecbc.webp', true, '2026-06-21T12:31:00.896671+00:00', '2026-07-12T17:37:12.860371+00:00'),
  ('2a03e6f0-3130-46b4-9fef-37369342c9a8', 1996, 'ברכות-הפרשת-חלה-מעור-מלאכותי-לבן-40-סמ', 'ברכות "הפרשת חלה" מעור מלאכותי - לבן 40 ס"מ', '<p>הוסיפו נופך של מסורת ויופי למטבח שלכם עם ברכת "הפרשת חלה" מעור מלאכותי יוקרתי. הברכה, בגודל 40 ס"מ ובגוון לבן אלגנטי, מעוצבת להדגשת חשיבותה של מצוות הפרשת חלה, ומוסיפה יראת שמיים וקסם לכל בית יהודי. היא מתאימה כמתנה נפלאה לחנוכת בית, לחג, או סתם כדי להביע אהבה והערכה. החומר האיכותי מבטיח עמידות לאורך שנים, והעיצוב הייחודי הופך אותה לפריט אמנותי שימושי.</p>', 'ברכה מהודרת "הפרשת חלה" מרשימה, מעור מלאכותי איכותי בצבע לבן, בגודל 40 ס"מ, להוספת קדושה ויופי למטבח.', 169.0, 99.98, 'UK67157', 'instock', NULL, 'https://deyidkzuvwniioxjisdr.supabase.co/storage/v1/object/public/product-images/opt/5657befc6c980c92ce0900cc.webp', true, '2026-05-10T16:10:19.018791+00:00', '2026-07-12T17:37:13.284102+00:00'),
  ('2b18e172-f2bb-46b7-9588-a6f5d1035490', 2872425, 'chal-2872425', 'סט חלאקה פרימיום דגם האש שלרקמה בכסף', '<p>היכונו לרגע הקדושה המרגש של סידור הפאות הראשון עם סט החלאקה "האש שלרקמה" - גולת כתר של אומנות בכסף טהור. כל פריט בסט עוצב בקפידה, משלב עיטורים עשירים וגימור מוקפד, היוצרים יחד חוויה חושית ורוחנית. החומרים האיכותיים מבטיחים עמידות ויופי נצחי, בעוד העיצוב המרהיב הופך את הסט לא רק לכלי טקסי, אלא גם ליצירת אמנות שתעשיר את ביתכם לשנים רבות.</p>', 'סט חלאקה מלכותי, יצירת אמנות בכסף טהור. מתנה שתהפוך את הרגע הקדוש לחוויה בלתי נשכחת.', 586.0, NULL, NULL, 'instock', NULL, 'https://deyidkzuvwniioxjisdr.supabase.co/storage/v1/object/public/product-images/opt/2ac62fe034503592afb9ab8c.webp', true, '2026-05-31T11:30:03.111272+00:00', '2026-07-12T17:37:07.731111+00:00'),
  ('2b1e0308-8fc6-4bad-b532-7af7de42bcbb', NULL, 'artj-uk67721', 'תיק מפואר לטלית תפילין עם ידית שחור 31X41 ס"מ', '<p>תיק איכותי ואלגנטי, עשוי חומרים עמידים בצבע שחור קלאסי. מידותיו 31X41 ס"מ מתאימות במיוחד לאחסון מסודר של טלית ותפילין, תוך שמירה על צורתם וקדושתם. הידית המעוצבת מאפשרת נשיאה קלה ובטוחה לבית הכנסת או לכל מקום. עיצובו המודרני משתלב עם פרקטיות מרבית לשמירה על חפצי הקודש.</p>', 'תיק מהודר לטלית ותפילין, נוח לנשיאה עם ידית חזקה, שומר על הקדושה והסדר.', 400.0, NULL, 'UK67721', 'instock', NULL, 'https://deyidkzuvwniioxjisdr.supabase.co/storage/v1/object/public/product-images/opt/4a06fd21c0a42c009d0ee041.webp', true, '2026-05-31T11:25:25.72855+00:00', '2026-07-12T17:37:18.959235+00:00'),
  ('2bb1f01a-f8ee-41fc-b79f-6208bf058a0c', NULL, 'פמוטי-קריסטל-חמשייה-מהודרים-19-5-סמ-41631', 'פמוטי קריסטל חמשייה מהודרים 19.5 ס"מ', NULL, 'פמוטי קריסטל חמשייה מהודרים 19.5 ס"מ', 270.0, NULL, 'UK41631', 'instock', NULL, 'https://deyidkzuvwniioxjisdr.supabase.co/storage/v1/object/public/product-images/opt/ae3b2137746bbae86ab2833c.webp', true, '2026-06-04T09:45:10.960252+00:00', '2026-07-12T17:37:07.084024+00:00'),
  ('2bd6719a-5f26-4437-967a-2acd1c349e4c', NULL, 'כיפה-קטיפה-ארט-מן-עם-ריקמה-האש-שלי-אפור-גודל-4-19305', 'כיפה קטיפה "ארט-מן" עם ריקמה האש שלי - אפור (גודל 4)', NULL, 'כיפה קטיפה "ארט-מן" עם ריקמה האש שלי - אפור (גודל 4)', 61.0, 40.0, 'UK19305', 'instock', NULL, 'https://deyidkzuvwniioxjisdr.supabase.co/storage/v1/object/public/product-images/opt/5e1005ab80155c645989be2a.webp', true, '2026-06-04T09:45:18.278468+00:00', '2026-07-12T17:37:10.246384+00:00'),
  ('2bf7430b-4da0-4a5c-a313-0e640e1d9f77', 2110, 'עטרה-לטלית-עם-רקמה-88x14-סמ', 'עטרה לטלית עם רקמה 88x14 ס"מ', '<p>העטרה לטלית עשויה מבד איכותי, מעוצבת להפליא עם רקמה עשירה ומדויקת. מידותיה 88x14 ס"מ, היא מתאימה לכיסוי מושלם ולמראה מלכותי. רקמת "קודש" או "שמע ישראל" מוסיפה נופך של קדושה ויופי, ומעניקה לטלית מראה ייחודי ומכובד. זוהי תוספת משמעותית המשדרגת את חוויית לבישת הטלית, ומדגישה את חשיבותה של מצוות ציצית.</p>', 'עטרת טלית מהודרת עם רקמה ייחודית, תשדרג כל טלית ביוקרה ובקדושה. מתנה מושלמת לכל אירוע.', 36.0, 29.98, 'UK66708', 'instock', NULL, 'https://deyidkzuvwniioxjisdr.supabase.co/storage/v1/object/public/product-images/opt/e4926aff195aef6e6e0fbd19.webp', true, '2026-05-10T16:10:19.018791+00:00', '2026-07-12T17:37:20.73526+00:00'),
  ('2bfba7e1-a0a4-4c2d-b76e-387512066e29', 2872398, 'chal-2872398', 'סט חלאקה קלאסי דגם כתר רקמה בזהב ורקמת שם הילד', '<p>אלגנטיות במיטבה ליום המילה המרגש. סט חלאקה קלאסי זה, מעוצב בכתר רקמה מפואר בזהב, מוסיף נופך מלכותי לחגיגה. ניתן לרקום את שם הילד, מה שהופך את המתנה לאישית ובלתי נשכחת. הסט עשוי מחומרים איכותיים, ומבטיח חוויה נוחה ונעימה לתינוק.</p>', 'סט מלאכי ליום המילה! פירוק הכלה בסט אקסלוסיבי, עם כתר רקמה מזהב, ורקמת שם הילד. מתנה מושלמת ליום המילה.', 357.0, NULL, NULL, 'instock', NULL, 'https://deyidkzuvwniioxjisdr.supabase.co/storage/v1/object/public/product-images/opt/701f3fac9ba6e585534f310d.webp', true, '2026-05-31T11:30:03.111272+00:00', '2026-07-12T17:37:21.098382+00:00'),
  ('2c15fffc-bb5b-48b8-a6a7-232e05541508', 2080, 'זוג-קופסאות-תפילין-מפלסטיק-גודל-35-צבע-כ', 'זוג קופסאות תפילין מפלסטיק גודל 35 - צבע כסף עם פלאק', '<p>שמרו על קדושת התפילין שלכם בכבוד וביופי בעזרת זוג קופסאות תפילין מפלסטיק איכותי, בגודל 35. צבע הכסף המרהיב מוסיף נופך אלגנטי, והפלאק המיוחד מעניק מראה יוקרתי ומבליט את ייחודיותן. קופסאות אלו לא רק מגנות על התפילין מפני נזקי אבק ולחות, אלא גם משמשות כתכשיט אמיתי, המבטא את הקשר העמוק שלכם ליהדות. בחירה מושלמת לכל מי שמחפש שילוב של פרקטיות, עיצוב מרהיב ורצון לשמר את קדושת המצווה.</p>', 'זוג קופסאות תפילין מהודרות בגודל 35, בצבע כסף מנצנץ עם פלאק ייחודי. פתרון אידאלי לשמירה על התפילין.', 65.0, 53.98, 'UK46375', 'instock', NULL, 'https://deyidkzuvwniioxjisdr.supabase.co/storage/v1/object/public/product-images/opt/d48baf016f4da5ec86a714c9.webp', true, '2026-05-10T16:10:19.018791+00:00', '2026-07-12T17:37:18.114548+00:00'),
  ('2c62ccdc-8689-4ed7-b4a0-138f594ecfbb', NULL, 'groom-set-liam-shalom-goli', 'מארז לחתן - דמוי פשתן עם האש שלי בגב', 'מארז חתן יוקרתי הכולל תיק טלית, תיק תפילין, כיפה וסידור עם רקמה אישית טלית צמר רכלים תשב"צ כולל עטרה ופינות ותיק תואם וכיפה תואמת עם אפשרות לרשום את השם בלייזר.', 'מארז חתן יוקרתי דמוי פשתן עם רקמת האש שלי בגב וטלית מעוטרת — דגם פרימיום.', 2572.0, 1800.0, NULL, 'instock', NULL, 'https://deyidkzuvwniioxjisdr.supabase.co/storage/v1/object/public/product-images/opt/5fbfa3c5cee1a51d086683f3.webp', true, '2026-06-09T10:37:37.638981+00:00', '2026-07-12T17:37:09.065247+00:00'),
  ('2eef7cc0-d5e9-4fdc-9f3f-4b09c316f9e7', NULL, 'פמוטי-קריסטל-מהודרים-18-סמ-42955', 'פמוטי קריסטל מהודרים 18 ס"מ', NULL, 'פמוטי קריסטל מהודרים 18 ס"מ', 337.0, NULL, 'UK42955', 'instock', NULL, 'https://deyidkzuvwniioxjisdr.supabase.co/storage/v1/object/public/product-images/opt/632f9ff613d8701bccebe1ff.webp', true, '2026-06-04T09:45:11.286537+00:00', '2026-07-12T17:37:09.481269+00:00'),
  ('307762fb-d7ca-42e8-a01f-998ab7f230e6', NULL, 'cover-gray-circle', 'כיסוי טלית ותפילין אפור בהיר עם מעגל פסוקים - לייזר בלבד', NULL, 'כיסוי טלית ותפילין אפור בהיר עם עיטור מעגלי. הטבעת שם אישי בלייזר בלבד.', 429.0, 300.0, NULL, 'instock', NULL, 'https://deyidkzuvwniioxjisdr.supabase.co/storage/v1/object/public/product-images/opt/de6bb7ddc382dd1e5503ada2.webp', true, '2026-06-09T10:43:24.061178+00:00', '2026-07-12T17:37:06.528444+00:00'),
  ('30d526c9-9b57-417c-87a2-c9ed78b5c849', 2449, 'concrete-polymer-15-cm-stone-like-black', 'Polymer concrete 15 cm, stone-like, black', '<p>פסל אבן מינימליסטי מיוצר מבטון פולימרי איכותי, המעניק לו מראה של אבן טבעית אך עמידות יוצאת דופן. בגודל 15 ס"מ, הוא משתלב בהרמוניה בכל חלל, מבית ומחוץ. צבעו השחור העמוק מוסיף אלגנטיות מודרנית, והטקסטורה העדינה מזמינה מגע. מתנה ייחודית או תוספת אישית לכל בית.</p>', 'אבן מלאכותית שחורה, 15 ס"מ. עיצוב מודרני ומינימליסטי לכל פינה בבית.', 96.0, 79.98, 'UK24382', 'instock', NULL, 'https://deyidkzuvwniioxjisdr.supabase.co/storage/v1/object/public/product-images/opt/cbb07cae8d2c266d6e274480.webp', true, '2026-05-10T16:10:19.018791+00:00', '2026-07-12T17:37:19.380129+00:00'),
  ('3289f3fe-72cd-4caa-bcb2-68bd09b847cd', 2871344, 'talit-2871344', 'טלית דגם כתר ברכת הכוהנים', '<p>טלית דגם ''כתר'' היא פריט יודאיקה ייחודי, המשלב מסורת עשירה עם אסתטיקה מלכותית. רקמת ברכת הכוהנים המוזהבת, המעטרת את פינות הטלית, מוסיפה נופך קסום וקדוש לתפילה. עשויה מבד פרימיום איכותי, היא נוחה לנשיאה ומעניקה תחושת כבוד והתעלות בכל לבישה. מתנה מושלמת שתלווה את בעליה ברגעים של קדושה והתבוננות.</p>', 'טלית יוקרתית בסגנון ''כתר'' עם רקמת ברכת הכוהנים המרהיבה. עוצבה להעניק השראה רוחנית ומראה מלכותי.', 571.43, 400.0, NULL, 'instock', NULL, 'https://deyidkzuvwniioxjisdr.supabase.co/storage/v1/object/public/product-images/opt/e38801fbd265549c919014a8.webp', true, '2026-05-31T11:10:09.145533+00:00', '2026-07-12T17:37:15.700805+00:00'),
  ('328d7f9b-a807-45b4-b732-bd5fe3ef9d8f', 2203, 'תיק-תפילין-מעור-דמוי-עור-2623-סמ-עם-ידית-שח', 'תיק תפילין מעור דמוי עור 26*23 ס"מ עם ידית - שחור עם אותיות מוטבעות', '<p>הציגו את התפילין שלכם במלוא הדרם עם תיק מעוצב זה. עשוי מעור דמוי איכותי ועמיד, הוא בגודל אידיאלי של 26*23 ס"מ, וכולל ידית אחיזה נוחה לנשיאה יומיומית. הגוון השחור העמוק והאותיות המוטבעות בעדינות מעניקים לתיק מראה אלגנטי ומרשים, המתאים לכל בית כנסת ואירוע. זהו לא רק תיק, אלא הצהרה של כבוד והערכה למצוות.</p>', 'תיק תפילין מעור דמוי יוקרתי, 26*23 ס"מ, עם ידית נוחה. עיצוב שחור קלאסי עם אותיות מוטבעות להשלמת המראה.', 240.0, 199.98, 'UK67523', 'instock', NULL, 'https://deyidkzuvwniioxjisdr.supabase.co/storage/v1/object/public/product-images/opt/e165552993389808f076adec.webp', true, '2026-05-10T16:10:19.018791+00:00', '2026-07-12T17:37:18.84553+00:00'),
  ('32ea412a-7420-4fe2-91c9-a9c6e6cb7a7a', 2095, 'ברכת-בית-לוסיט', 'ברכת בית לוסיט', '<p>הכניסו אור וברכה לביתכם עם ברכת הבית המרהיבה הזו, עשויה מלוחית לוסיט איכותי הצבוע בצבעי יין עמוקים. הברכה, הכוללת את פסוק "ברכו ה'' בית יעקב", עשויה להיפוך ומתאימה לתלייה או הצגה על מדף. שילוב החומר הבוהק והצבע העשיר יוצר פריט עיצובי עוצר נשימה, המשרה אווירה של קדושה, יופי והגנה על בני הבית. מתנה נפלאה לבית חדש, לחג, או פשוט כדרך להביע אהבה והערכה.</p>', 'ברכת בית מיוחדת מלוחית לוסיט, מוסיפה קסם ושמירה לכל חלל. מתנה אידיאלית לבית חדש או לכל השנה.', 240.0, 199.98, 'UK80198', 'instock', NULL, 'https://deyidkzuvwniioxjisdr.supabase.co/storage/v1/object/public/product-images/opt/1c21a7d2e9a911cb0423b5b8.webp', true, '2026-05-10T16:10:19.018791+00:00', '2026-07-12T17:37:18.387877+00:00'),
  ('335c4a67-888c-4452-8350-8335c1d281d8', 2152, 'חנוכייה-קריסטל-אלגנטית-21-סמ', 'חנוכייה קריסטל אלגנטית 21 ס"מ', '<p>העניקו לחג החנוכה שלכם נופך של מלכותיות עם חנוכיית הקריסטל האלגנטית שלנו. בעבודת יד מוקפדת, היא ניצבת על גבי בסיס יציב ומעוצב, וכל נרות החג ישתקפו בה בברק עוצר נשימה. קריסטל איכותי מבטיח שתיהנו ממנה לאורך שנים רבות, והיא תהווה מרכז שולחן מרשים בכל אירוע. מתנה מושלמת שתאיר כל חדר באור יקרות.</p>', 'חנוכיית קריסטל מפוארת - 21 ס"מ של זוהר והוד לחג החנוכה.', 264.0, 219.98, 'UK42197', 'instock', NULL, 'https://deyidkzuvwniioxjisdr.supabase.co/storage/v1/object/public/product-images/opt/1265d6702ec6917784984ee5.webp', true, '2026-05-10T16:10:19.018791+00:00', '2026-07-12T17:37:07.116989+00:00'),
  ('34980702-7fd8-45e2-9602-08b4eeb7bff2', NULL, 'cover-star-blue', 'כיסוי טלית ותפילין תכלת עם מגן דוד - הטבעת שם בלייזר', NULL, 'כיסוי טלית ותפילין בגוון תכלת רך עם הדפס מגן דוד. ניתן לחרוט שם אישי בלייזר בלבד.', 429.0, 300.0, NULL, 'instock', NULL, 'https://deyidkzuvwniioxjisdr.supabase.co/storage/v1/object/public/product-images/opt/893f449689f5a4425599b11e.webp', true, '2026-06-09T10:43:24.061178+00:00', '2026-07-12T17:37:08.610778+00:00'),
  ('3708d397-7cb8-43d2-8e47-f789f98b236d', 2870883, 'chal-2870883', 'סט חלאקה משודרג דגם יברכך כסף', '<p>מעניקים לחתן בר המצווה מתנה שתלווה אותו לאורך שנים. סט החלאקה ''יברכך'' משודרג, עשוי מכסף טהור, עוצב בקפידה מחשבה ליצירת חוויה בלתי נשכחת. הסט כולל את כל הפריטים הדרושים לטקס המשמעותי, ומעוטר בעיצובים עדינים המשדרים הוד וקדושה. זוהי מתנה מרגשת, יוקרתית ובעלת ערך רוחני, שתשאיר חותם עמוק על משפחתכם.</p>', 'סט חלאקה יברכך כסף - חוויה מושלמת לבר המצווה, שילוב של יופי, קדושה ואיכות בלתי מתפשרת.', 914.0, NULL, NULL, 'instock', NULL, 'https://deyidkzuvwniioxjisdr.supabase.co/storage/v1/object/public/product-images/opt/cc21fec6509210b1086cf210.webp', true, '2026-05-31T11:30:03.111272+00:00', '2026-07-12T17:37:19.79973+00:00'),
  ('3735e61f-a7d2-4030-8d51-318308fb0830', 2188, 'צלחת-פסח-עגולה-עם-גבעולים-40-סמ-עיצוב-מלכ', 'צלחת פסח עגולה עם גבעולים 40 ס"מ - עיצוב מלכותי', '<p>צרו אווירה מלכותית בליל הסדר עם צלחת הפסח המעוצבת שלנו. בקוטר 40 ס"מ, היא נושאת את סמלי החג בגאווה, משולבת עם גבעולי חיטה עדינים המסמלים שפע ופריחה. עשויה מחומרים איכותיים, היא לא רק פריט אמנותי אלא גם מרכז שולחן שיגרום לכל הסועדים להרגיש יוקרה והדר. צלחת זו תהפוך את הסדר שלכם לאירוע בלתי נשכח, המחבר בין מסורת יוקרתית ליום יום.</p>', 'צלחת ליל הסדר ''רויאל’ – 40 ס"מ של עוצמה יהודית. עיצוב מלכותי עם גבעולי חיטה, חוויה בלתי נשכחת.', 336.0, 279.98, 'UK02849', 'instock', NULL, 'https://deyidkzuvwniioxjisdr.supabase.co/storage/v1/object/public/product-images/opt/1b2b8121c7967304afa43e45.webp', true, '2026-05-10T16:10:19.018791+00:00', '2026-07-12T17:37:18.836863+00:00'),
  ('378f0014-eeab-4980-8274-21c82363ddaa', NULL, 'cover-royal-blue', 'כיסוי טלית ותפילין כחול רויאל עם מעגל פסוקים - לייזר בלבד', NULL, 'כיסוי טלית ותפילין בגוון כחול רויאל מהודר. הטבעת שם אישי בלייזר בלבד.', 429.0, 300.0, NULL, 'instock', NULL, 'https://deyidkzuvwniioxjisdr.supabase.co/storage/v1/object/public/product-images/opt/9917c7553bf3086cd8f565b0.webp', true, '2026-06-09T10:43:24.061178+00:00', '2026-07-12T17:37:08.578305+00:00'),
  ('38443230-0a52-48cc-ba40-d14d746a6b3c', NULL, 'product-35', 'סידור מעוצב כתר מובלט לגבר צבע חום עתיק', '<p>סידור תפילה לגבר בעיצוב ייחודי ומרשים, המשלב יוקרה וקדושה. הכריכה החומה-עתיקה, מעוטרת בכתר מובלט ובסמלים יהודיים מסורתיים, מעניקה תחושה של עושר והדר. הסידור כולל את כל התפילות המרכזיות בנוסח עדות מזרח, כתוב בכתב ברור וקריא, על גבי דפי נייר איכותי. מתנה מושלמת לאב, לסבא או לכל גבר יקר, שתזכיר לו בכל עת את הקשר העמוק ליהדות.</p>', 'סידור תפילה מהודר עם כתר מובלט, בעיצוב עתיק ויוקרתי לגבר.', 186.0, NULL, NULL, 'instock', NULL, 'https://deyidkzuvwniioxjisdr.supabase.co/storage/v1/object/public/product-images/opt/571b1af2d12f22cbe864cf4a.webp', true, '2026-05-31T11:04:26.373999+00:00', '2026-07-12T17:37:15.033723+00:00'),
  ('3872d9f8-7441-443d-907a-8b45dafc18b9', 1226, 'סט-הבדלה-קריסטל-20-סמ-4', 'סט הבדלה קריסטל 20 ס"מ', '<p>המוצר המושלם להשלמת שולחן השבת שלכם - סט הבדלה מעוצב מגבישי קריסטל עדינים, בגובה 20 ס"מ. כל כוסית קריסטל תוכננה בקפידה ומשדרת אלגנטיות וזוהר, מוסיפה נוכחות מרשימה ומוארכת לשולחן. תנו לקריסטל להאיר את רגע ההבדלה ולהפוך אותו לחוויה בלתי נשכחת.</p>', 'סט הבדלה קריסטל - 20 ס"מ גובה. מעניק נוכחות מרשימה ומוארכת לשולחן השבת.', 408.0, 339.98, 'UK80061', 'instock', NULL, 'https://deyidkzuvwniioxjisdr.supabase.co/storage/v1/object/public/product-images/opt/d090c8edef73e667a93fab0b.webp', true, '2026-05-10T16:10:19.018791+00:00', '2026-07-12T17:37:10.088808+00:00'),
  ('388efeab-3baf-4cb6-a1ca-c4864ce294fe', NULL, 'product-38', 'סידור מעוצב כתר מובלט לגבר קורדרוי אפור בהיר', '<p>סידור תפילה יפהפה זה, בעיצוב מודרני ויוקרתי, משלב את יופיו של הקורדרוי האפור הבהיר עם כתר מובלט, היוצר מראה ייחודי ומרשים. הסידור מיועד לגבר המחפש שילוב של מסורת וסגנון, ומספק חווית תפילה מעמיקה ואישית. בד הקורדרוי הרך והנעים למגע מוסיף טאץ'' של חמימות ותחכום, הופך את הסידור הזה למתנה מושלמת או תוספת מבורכת לאוסף האישי.</p>', 'סידור תפילה מעוצב עם כתר קורדרוי אפור בהיר לגבר – פשטות אלגנטית לכל תפילה.', 186.0, NULL, NULL, 'instock', NULL, 'https://deyidkzuvwniioxjisdr.supabase.co/storage/v1/object/public/product-images/opt/80d6970a7931ce3c1c5f2c0b.webp', true, '2026-05-31T11:04:26.373999+00:00', '2026-07-12T17:37:15.309982+00:00'),
  ('38b82d5c-6018-4f5e-9351-b1fadad3d9d2', NULL, 'artj-uk67172', 'תיק מפואר לטלית דמוי עור עם "ויברכך" 38X31 ס"מ - UK67172', '<p>התיק מעוצב בקפידה מבית היוצר של מותג יודאיקה מוכר, ומדמה עור איכותי במראה יוקרתי. עיטור רקמת "ויברכך" מוסיף נופך של קדושה וברכה, והגודל המרווח (38X31 ס"מ) מבטיח אחסון נוח ובטוח לטלית. זהו פריט שימושי ואלגנטי, מושלם להגנה על ערכו של הטלית, ומתנה מיוחדת שתעלה חיוך ותשמור על קשר רגשי.</p>', 'תיק מפואר לדברי קדושה, מעוצב לדטליים, עם רקמת "ויברכך" עשירה. מתנה אידיאלית שתשמור ותעטר את הטלית.', 357.14, NULL, 'UK67172', 'instock', NULL, 'https://deyidkzuvwniioxjisdr.supabase.co/storage/v1/object/public/product-images/opt/e9e29c0448754622977c2b2e.webp', true, '2026-05-31T11:25:25.72855+00:00', '2026-07-12T17:37:06.765376+00:00'),
  ('3a321d65-a6e5-467d-9da6-d3e560948fa3', 2871420, 'talit-2871420', 'טלית תשבץ  צמר פסים בצבע לבן', '<p>התעטפו בקדושה עם טלית צמר איכותית זו, המעוצבת בסגנון תשבץ על-זמני. הפסים הלבנים על הרקע הבהיר מעניקים מראה קלאסי ואלגנטי. עשויה 100% צמר טהור, היא נוחה ונעימה ללבישה בכל עת, ומעצימה את חווית התפילה. מתנה מושלמת ומרשימה לעצמכם או ליקירכם.</p>', 'טלית צמר קלאסית בעיצוב תשבץ, עם פסים לבנים עדינים. יוקרתיות ונוחות לכל תפילה.', 540.0, 450.0, NULL, 'instock', NULL, 'https://deyidkzuvwniioxjisdr.supabase.co/storage/v1/object/public/product-images/opt/b84caabd7fdb967caddfa89e.webp', true, '2026-05-31T11:10:09.145533+00:00', '2026-07-12T17:37:13.602816+00:00'),
  ('3a3b53c9-0690-44d6-a16c-49856d369438', NULL, 'product-24', 'סידור כתר לגבר ג''ינס כחול כהה הטבעה בכסף', '<p>סידור התפילה ''כתר'' לגבר, בעיצוב מודרני בגוון ג''ינס כחול כהה, הוא פריט חובה לכל מי שמחפש שילוב של הדרת קודש וסטייל. הסידור מעוטר בהטבעת כסף עדינה ומדויקת, המוסיפה נופך יוקרתי ומיוחד. הכריכה החזקה והאיכותית מבטיחה עמידות לאורך שנים, בעוד הדפים הנוחים לקריאה מאפשרים חיבור עמוק לתפילה. זהו סידור שיחבר אתכם למסורת, בסטייל אישי.</p>', 'סידור כתר לגבר: יוקרה וארגון בתכלת כהה, עם הטבעת כסף מרהיבה. מתנה מושלמת לכל גבר.', 186.0, NULL, NULL, 'instock', NULL, 'https://deyidkzuvwniioxjisdr.supabase.co/storage/v1/object/public/product-images/opt/ce40628525feed775ad0bc92.webp', true, '2026-05-31T11:04:26.373999+00:00', '2026-07-12T17:37:14.754314+00:00'),
  ('3ab2ad56-01f2-4683-a4a6-0876593b0e2d', 2180, 'צלחת-פסח-מזכוכית-40-סמ', 'צלחת פסח מזכוכית 40 ס"מ', '<p>הציגו את סדר הפסח שלכם על גבי צלחת מזכוכית אלגנטית ומרשימה, בקוטר 40 ס"מ. הצלחת המעוצבת באופן ייחודי תשמש כמרכז שולחן החג, ותעניק נופך של חגיגיות ויוקרה. עשויה מזכוכית איכותית, היא עמידה וקלה לניקוי, ומתאימה לשימוש חוזר משנה לשנה. הוסיפו קסם מיוחד לאווירת החג עם פריט יודאיקה אמיתי.</p>', 'צלחת פסח מרהיבה מזכוכית, בקוטר 40 ס"מ, שתוסיף יוקרה לכל שולחן חג. פריט מרשים ושימושי.', 357.14, 0.0, 'UK45788', 'instock', NULL, 'https://deyidkzuvwniioxjisdr.supabase.co/storage/v1/object/public/product-images/opt/949461a32da14cdf5c145d49.webp', true, '2026-05-10T16:10:19.018791+00:00', '2026-07-12T17:37:18.783153+00:00'),
