  ('3f968389-e657-40eb-99b0-51ce183001ec', 2084, 'ברכה-ממוסגרת-עם-לבנים-לבנות-ולוח-מתכת-3324-2', 'ברכה ממוסגרת עם לבנים לבנות ולוח מתכת 33*24 ס"מ - הדלקת נרות', '<p>הברכה הממוסגרת להדלקת נרות היא תוספת מרשימה ומלאת משמעות לכל חלל בבית. המסגרת, בגודל 33*24 ס"מ, משלבת עיצוב עדין של לבנים לבנות עם לוח מתכת איכותי, היוצר יחד קומפוזיציה אלגנטית ויוקרתית. הברכה מודפסת על גבי חומרים עמידים, המבטיחים שימור לאורך שנים. פריט זה אינו רק אמירה עיצובית, אלא גם חיבור עמוק למסורת היהודית, שילווה כל הדלקת נרות בשבת וחג בשמחה ובקדושה. מתנה מושלמת לכל אירוע משמעותי, שתעניק נופך של יופי ורוחניות.</p>', 'ברכה ממוסגרת מהודרת להדלקת נרות, בשילוב לבנים לבנות ולוח מתכת, להוספת קדושה ויופי לביתכם. מתנה נפלאה לכל בית יהודי.', 144.0, 119.98, 'UK47798', 'instock', NULL, 'https://deyidkzuvwniioxjisdr.supabase.co/storage/v1/object/public/product-images/opt/b789bd82c7e3451a0b1d1996.webp', true, '2026-05-10T16:10:19.018791+00:00', '2026-07-12T17:37:20.210613+00:00'),
  ('40a75b53-0efc-44cc-a74e-e353556e5dd9', 2059, 'זוג-פמוטי-קריסטל-אלגנטיים-18-סמ', 'זוג פמוטי קריסטל אלגנטיים 18 ס"מ', '<p>הזיווג המושלם בין ברק הקריסטל לטקסי השבת והחג. פמוטי קריסטל אלו, המתנשאים לגובה 18 ס"מ, יעטרו כל חלל באלגנטיות שקופה וזוהרת. איכות הגימור הגבוהה מבטיחה ברק עמיד לאורך זמן, והעיצוב המוקפד מתאים כמתנה משמעותית או כתוספת אישית לבית.</p>', 'פמוטי קריסטל מרהיבים, 18 ס"מ גובה. יוסיפו אור ויוקרה לכל שולחן.', 192.0, 159.98, 'UK41946', 'instock', NULL, 'https://deyidkzuvwniioxjisdr.supabase.co/storage/v1/object/public/product-images/opt/ae2d5a368949dc086c9d4fe7.webp', true, '2026-05-10T16:10:19.018791+00:00', '2026-07-12T17:37:19.61147+00:00'),
  ('40db59d9-4e7b-4421-b274-f034e1c93582', 2872447, 'chal-2872447', 'ספר תורה לבן עם חריטת שם הילד על בסיס זהב', '<p>הכירו את ספר התורה הלבן המרהיב, יצירת מופת של קדושה ועונג אסתטי. בסיס העשוי זהב טהור מעוטר בחריטת שם הילד, הופך את הספר למזכרת אישית ויחידה מסוגה. ספר תורה זה, עשוי קלף משובח, משלב מסורת עתיקה עם עיצוב מודרני ויוקרתי, ומבטיח לשמור על ערכו ויופיו לאורך שנים רבות. מתנה שתלווה את הילד לכל החיים, ותהווה חיבור מיוחד למורשת.</p>', 'ספר תורה לבן עם חריטת שם אישית על בסיס יוקרתי. מתנה מושלמת לבר מצווה או לברית.', 329.0, NULL, NULL, 'instock', NULL, 'https://deyidkzuvwniioxjisdr.supabase.co/storage/v1/object/public/product-images/opt/e9e67607dddd9daa33253d4b.webp', true, '2026-05-31T11:30:03.111272+00:00', '2026-07-12T17:37:21.644948+00:00'),
  ('4127f8d9-2474-4b8e-9519-41948fb2c1b5', NULL, 'כיפה-קטיפה-ארט-מן-עם-ריקמה-האש-שלי-כחול-גודל-3-10229', 'כיפה קטיפה "ארט-מן" עם ריקמה האש שלי - כחול (גודל 3)', NULL, 'כיפה קטיפה "ארט-מן" עם ריקמה האש שלי - כחול (גודל 3)', 61.0, 40.0, 'UK10229', 'instock', NULL, 'https://deyidkzuvwniioxjisdr.supabase.co/storage/v1/object/public/product-images/opt/b660171554bee9a478c8c597.webp', true, '2026-06-04T09:45:18.52115+00:00', '2026-07-12T17:37:10.237254+00:00'),
