  ('423c638f-b9bc-4820-ba3b-c8c1c6bdec5b', NULL, 'נטלה-מהודרת-מפולימר-14-סמ-דגם-9-48986', 'נטלה מהודרת מפולימר 14 ס"מ (דגם 9)', NULL, 'נטלה מהודרת מפולימר 14 ס"מ (דגם 9)', 152.0, NULL, 'UK48986', 'instock', NULL, 'https://deyidkzuvwniioxjisdr.supabase.co/storage/v1/object/public/product-images/opt/5f497e20531954101dcd2555.webp', true, '2026-06-04T09:45:21.691521+00:00', '2026-07-12T17:37:10.695642+00:00'),
  ('439e0ba3-8471-4b3b-8ec5-671bbf1f9f61', NULL, 'artj-uk66983', 'תיק מפואר לטלית דמוי עור שחור אותיות בולטות "טלית" 31X38 ס"מ', '<p>הגן על הטלית שלך בכבוד ובהדר עם תיק דמוי עור שחור ומפואר זה. עוצב במיוחד לשמירה על הטלית, התיק משלב חומרים איכותיים עם עיצוב חד-פעמי. האותיות "טלית" הבולטות בצבע ניגודי מוסיפות נופך של יוקרה ומבטיחות זיהוי קל. בגודל 31X38 ס"מ, הוא מציע מקום נדיב לרוב הטליתות, ושומר עליהן מוגנות ומסודרות.</p>', 'תיק דמוי עור יוקרתי לשמירה על הטלית שלך. עיצוב אלגנטי עם שם הטלית באותיות בולטות.', 357.14, NULL, 'UK66983', 'instock', NULL, 'https://deyidkzuvwniioxjisdr.supabase.co/storage/v1/object/public/product-images/opt/4b2585833c8c72ee52e517e1.webp', true, '2026-05-31T11:25:25.72855+00:00', '2026-07-12T17:37:05.911178+00:00'),
  ('446aa3dc-bb26-4a85-958e-2d2616f9a54d', 2871360, 'talit-2871360', 'טלית דגם פאר כסוף', '<p>תתעטפו בפאר ובקדושה עם טלית דגם פאר כסוף. עשויה משי איכותי ומשובצת ברקמת כסף מרהיבה, טלית זו מעניקה תחושת יוקרה ורוממות בכל תפילה. עיצובה המיוחד משלב מסורת עם אסתטיקה מודרנית, ומבטיח שתחוו רגעים של התעלות רוחנית. מתנה מושלמת לעצמכם או ליקרים לכם.</p>', 'טלית דגם פאר כסוף - עשויה משי עשיר ורקמת כסף ייחודית, לחוויה תפילה יוקרתית ובלתי נשכחת.', 500.0, NULL, NULL, 'instock', NULL, 'https://deyidkzuvwniioxjisdr.supabase.co/storage/v1/object/public/product-images/opt/73ba7f27d2147d89356806ee.webp', true, '2026-05-31T11:10:09.145533+00:00', '2026-07-12T17:37:05.589143+00:00'),
  ('446abec0-7e4e-448c-b431-183b0936c130', NULL, 'product-42', 'סידור מעוצב מזמור לתודה לגבר צבע ג''ינס בהיר', '<p>הכירו את סידור התפילה ''מזמור לתודה'', פריט ייחודי ומעוצב שיהווה מתנה בלתי נשכחת לגבר היקר לכם. הסידור, המעוצב בגוון ג''ינס בהיר, משדר קלילות וסטייל, ומביא נגיעה מודרנית לעולם התפילה. הכריכה החזקה והנעימה למגע מבטיחה שימוש נוח לאורך זמן, בעוד שהטקסט ברור וקריא. זהו סידור תפילה שמזמין התבוננות, הוקרה ושמחה, ויהפוך כל תפילה לחוויה אישית ומשמעותית יותר.</p>', 'סידור תפילה ''מזמור לתודה'' – מתנה מרגשת לגבר, בעיצוב ג''ינס בהיר שמשלב מסורת וסטייל.', 186.0, NULL, NULL, 'instock', NULL, 'https://deyidkzuvwniioxjisdr.supabase.co/storage/v1/object/public/product-images/opt/a1d148a4cb149963cc2ad125.webp', true, '2026-05-31T11:04:26.373999+00:00', '2026-07-12T17:37:15.404917+00:00'),
  ('44fa0685-05ab-40ec-8c8c-95dbf759b5d0', NULL, 'cover-corduroy-eli', 'כיסוי טלית ותפילין קורדרוי אפור - הטבעת שם בלייזר', NULL, 'כיסוי טלית ותפילין מבד קורדרוי איכותי בגוון אפור. הטבעת שם אישי בלייזר בלבד.', 429.0, 300.0, NULL, 'instock', NULL, 'https://deyidkzuvwniioxjisdr.supabase.co/storage/v1/object/public/product-images/opt/d6f690ebd1fbf061e3907596.webp', true, '2026-06-09T10:43:24.061178+00:00', '2026-07-12T17:37:07.658919+00:00'),
  ('4571edd1-a942-4efa-8c90-1fdfb137517f', 2872438, 'chal-2872438', 'סט חלאקה פרימיום דגם מגן דוד רקמה בתכלת', '<p>הפוך את טקס החלאקה לזיכרון בלתי נשכח עם סט הפרימיום "מגן דוד". עשוי מכותנה איכותית במיוחד, הסט כולל חלוק רחצה רך, מגבת סופגת ומכנסונים, כולם מעוטרים ברקמת מגן דוד עדינה בתכלת. מתנה מרגשת ושימושית לחתן הבר מצווה, שתלווה אותו בשנים הבאות. העיצוב היוקרתי והחומרים המעולים מבטיחים איכות שתחזיק מעמד.</p>', 'סט חלאקה פרימיום "מגן דוד" רקמה בתכלת - מתנה יוקרתית לבר המצווה.', 586.0, NULL, NULL, 'instock', NULL, 'https://deyidkzuvwniioxjisdr.supabase.co/storage/v1/object/public/product-images/opt/e5bdbdde0d9a3910f475a41b.webp', true, '2026-05-31T11:30:03.111272+00:00', '2026-07-12T17:37:07.883641+00:00'),
  ('45b70f6b-0667-4a6e-bd17-523c51328ee2', 2060, 'זוג-קופסאות-תפילין-מפלסטיק-גודל-32-שחור', 'זוג קופסאות תפילין מפלסטיק גודל 32 - שחור עם פלאק', '<p>שמרו על קדושת התפילין שלכם בכבוד וביופי עם זוג קופסאות תפילין איכותיות אלו. עשויות פלסטיק עמיד בצבע שחור קלאסי, הן מגיעות בגודל 32 ומצוידות בפלאק מעוצב המוסיף נופך אישי ומיוחד. הקופסאות נועדו להגן על התפילין מפני נזקים, אבק ולחות, תוך שמירה על מראן המכובד לאורך שנים. הן הפתרון הפרקטי והאלגנטי לכל מתפלל.</p>', 'זוג קופסאות תפילין מעוצבות, שחורות ועמידות, בגודל 32, עם פלאק ייחודי. הפתרון המושלם לשמירה על התפילין.', 65.0, 53.98, 'UK47237', 'instock', NULL, 'https://deyidkzuvwniioxjisdr.supabase.co/storage/v1/object/public/product-images/opt/b5791af53883923434b64c01.webp', true, '2026-05-10T16:10:19.018791+00:00', '2026-07-12T17:37:08.882048+00:00'),
  ('462f7573-309a-4e1e-8b45-9f6e3aab42b7', NULL, 'sefer-devarim-tan', 'ספר דברים - חום קאמל עם זהב', NULL, 'ספר דברים בכריכת בד מחורצת בגוון חום קאמל עם הטבעת זהב אלגנטית', 143.0, 122.0, NULL, 'instock', 50, 'https://deyidkzuvwniioxjisdr.supabase.co/storage/v1/object/public/product-images/opt/812066aa15b83ed64a7cc83a.webp', true, '2026-06-16T13:29:21.438221+00:00', '2026-07-12T17:37:08.478908+00:00'),
  ('464af386-96f5-40f7-a1eb-d48088c87494', 2235, 'מזוזה-מפלסטיק-שקופה-עם-פקק-גומי-12-סמ-יר', 'מזוזה מפלסטיק שקופה עם פקק גומי 12 ס"מ - "ירושלים" עם שוק כסף', '<p>הוסיפו נגיעה של קדושה ויופי לביתכם עם מזוזה מפלסטיק שקוף ואיכותי, מעוטרת בשוק כסף יוקרתי ועיטורי ירושלים. הפקק הגומי מבטיח עמידות וקלות החלפה של הקלף. גודלה האידיאלי (12 ס"מ) מתאים לכל דלת, והעיצוב המודרני ישתלב נפלא בכל סגנון עיצוב. מתנה מתחשבת ומבורכת לכל בית, שתחבר אתכם תמיד לירושלים.</p>', 'מזוזה שקופה בעיצוב ירושלים, עשויה פלסטיק עמיד עם שוק כסף. מתנה מושלמת לבית או לחבר.', 26.0, 21.98, 'UK22265', 'instock', NULL, 'https://deyidkzuvwniioxjisdr.supabase.co/storage/v1/object/public/product-images/opt/d13dfcaf651d665a795f118e.webp', true, '2026-05-10T16:10:19.018791+00:00', '2026-07-12T17:37:18.8403+00:00'),
  ('4988d366-1a48-4af8-a94c-9bc2cbfcd715', 2228, 'מזוזה-מפלסטיק-שקופה-12-סמ-כסף-shin-עם-פקק-גומ', 'מזוזה מפלסטיק שקופה 12 ס"מ - כסף SHIN עם פקק גומי', '<p>הוסיפו נגיעה של קדושה ועיצוב מודרני לביתכם עם מזוזת פלסטיק שקופה זו. בגודל 12 ס"מ, היא מתאימה באופן מושלם לכל דלת, ומעוטרת באות שי"ן כסופה אלגנטית. עשויה מחומרים איכותיים ועמידים, עם פקק גומי פרקטי לשמירה על הקלף. מזוזה זו משלבת בצורה הרמונית בין המסורת היהודית לסטייל עכשווי, והיא מתנה אידיאלית לכל בית חדש או כתוספת מעוצבת למשכן קיים.</p>', 'מזוזה מודרנית מפלסטיק שקוף, 12 ס"מ, עם אות שי"ן כסופה מיוחדת. מושלמת לכל בית, מחברת בין מסורת לעיצוב עכשווי.', 24.0, 19.98, 'UK24604', 'instock', NULL, 'https://deyidkzuvwniioxjisdr.supabase.co/storage/v1/object/public/product-images/opt/8abb48477372fa39724e6471.webp', true, '2026-05-10T16:10:19.018791+00:00', '2026-07-12T17:37:20.863305+00:00'),
  ('4b5a1bc8-d001-4a0f-a163-d7b6f22dcfc1', NULL, 'product-4', 'סידור מעוצב ברכת הכהנים לגבר צבע לבן', '<p>העניקו מתנה בעלת משמעות עמוקה עם סידור ברכת הכהנים המעוצב שלנו. הסידור, בצבע לבן נקי ויוקרתי, נועד להכיל את ברכת הכהנים בקדושה ובכבוד. הוא עשוי מחומרים איכותיים, המבטיחים עמידות ויופי לאורך זמן. זוהי מתנה מושלמת לגבר, המסמלת הגנה, ברכה ואהבה.</p>', 'סידור ברכת הכהנים יוקרתי לגבר, בעיצוב לבן אלגנטי – מתנה אישית ומרגשת לכל אירוע.', 186.0, NULL, NULL, 'instock', NULL, 'https://deyidkzuvwniioxjisdr.supabase.co/storage/v1/object/public/product-images/opt/cac89c9af6369fd5202a639f.webp', true, '2026-05-31T11:04:26.373999+00:00', '2026-07-12T17:37:12.050914+00:00'),
  ('4b5ccff0-2fc5-4c65-a0c6-1ea613eca22f', 2406, 'מזוזה-דמוית-אבן-פולימר-12-סמ', 'מזוזה דמוית אבן פולימר 12 ס"מ', '<p>העניקו לביתכם נוכחות קדושה ומעוצבת עם מזוזה מרהיבה זו, המחקה בעדינות טבעית מראה של אבן. עשויה מחומר פולימרי איכותי ועמיד, היא מבטיחה לשמור על קדושת הבית לאורך שנים. תוספת אלגנטית ובעלת משמעות לכל דלת, המשלבת מסורת עם עיצוב מודרני. מזוזה זו היא גם מתנה נפלאה לכל בית חדש או לאירוע משמח.</p>', 'מזוזה ייחודית דמוית אבן, מוסיפה נגיעה של קדושה ויופי לכל פתח בבית. גודל אידיאלי 12 ס"מ.', 65.0, 53.98, 'UK24449', 'instock', NULL, 'https://deyidkzuvwniioxjisdr.supabase.co/storage/v1/object/public/product-images/opt/232cb0dd31b786beabffe0c0.webp', true, '2026-05-10T16:10:19.018791+00:00', '2026-07-12T17:37:20.990612+00:00'),
  ('4b76e34d-97a1-4ff3-a2e2-a0726b77011c', 2192, 'צלחת-דבש-קריסטל-77-סמ-עם-לוחית-מתכת', 'צלחת דבש קריסטל 7*7 ס"מ עם לוחית מתכת', '<p>העניקו טאץ'' של אלגנטיות ושפע לשולחן ראש השנה עם צלחת דבש מהודרת זו. עשויה קריסטל נוצץ בגודל אידיאלי של 7*7 ס"מ, ומעוטרת בלוחית מתכת עדינה המוסיפה נגיעה של יוקרה. הצלחת לא רק יפהפייה אלא גם פרקטית, ומזמינה כל אחד לטבול בתקווה ובמתיקות את השנה החדשה. מתנה שתשאיר רושם נעים ומרגש.</p>', 'צלחת דבש קריסטל מעוצבת, 7*7 ס"מ, עם לוחית מתכת - מתנה מושלמת ומרהיבה לראש השנה.', 89.0, 73.98, 'UK41371', 'instock', NULL, 'https://deyidkzuvwniioxjisdr.supabase.co/storage/v1/object/public/product-images/opt/5ca88ed25a9efcfc35c21d84.webp', true, '2026-05-10T16:10:19.018791+00:00', '2026-07-12T17:37:18.729427+00:00'),
  ('4b8002a6-405c-41a5-9aa1-bfa27acea561', NULL, 'artj-uk66729', 'תיק מפואר לטלית דמוי עור שחור אותיות בולטות "שי"', '<p>שדרגו את חווית הנשיאה של תשמישי הקדושה שלכם עם תיק דמוי עור שחור יוקרתי זה. מעוצב בקפידה, התיק מציע הגנה מעולה לטלית ולתפילין, תוך שהוא משלים את המראה האלגנטי שלכם. אותיות "שי" בולטות מוסיפות נגיעה של ייחודיות וקדושה, וכיסיות רחבה מבטיחה נוחות מירבית. בחירה מושלמת לכל מי שמחפש לשלב בין פונקציונליות, יופי ורוחניות.</p>', 'תיק מהודר לדברי קדושה, מעוצב באלגנטיות לדשדוש נוח של טלית ותפילין. עיצוב ייחודי עם אותיות "שי" בולטות, ללא פשרות על איכות.', 357.14, NULL, 'UK66729', 'instock', NULL, 'https://deyidkzuvwniioxjisdr.supabase.co/storage/v1/object/public/product-images/opt/5bcc5df9e5eba3e8b8401e1f.webp', true, '2026-05-31T11:25:25.72855+00:00', '2026-07-12T17:37:05.937356+00:00'),
  ('4d03e1c3-cada-4a62-b3a7-07e0912ff7ab', 2387, 'מזוזה-מפלסטיק-שקופה-עם-פקק-גומי-12-סמ-עם', 'מזוזה מפלסטיק שקופה עם פקק גומי 12 ס"מ - עם האות שין ולוחית', '<p>הוסיפו נגיעה של קדושה וסגנון לכל דלת בבית או בעסק עם מזוזה ייחודית זו. עשויה מפלסטיק שקוף איכותי ועמיד, בגודל 12 ס"מ, היא משלבת עיצוב מודרני עם סמליות עתיקה. האות "שין" המפורסמת, סמל לשם ש-ד-י, מעטר אותה יחד עם לוחית מעוצבת, היוצרת מראה מרשים ומזמין. הפקק הגומי מבטיח שהמגילה תישאר מוגנת ויבשה. זוהי לא רק מצווה, אלא גם פריט עיצובי המשדר יוקרה ומסורת.</p>', 'מזוזה מרשימה ואיכותית מפלסטיק שקוף 12 ס"מ, מעוצבת עם האות שין ולוחית, משלבת מראה מודרני עם קדושה מסורתית.', 26.0, 21.98, 'UK23606', 'instock', NULL, 'https://deyidkzuvwniioxjisdr.supabase.co/storage/v1/object/public/product-images/opt/11235ba1f0143d12c8f983ad.webp', true, '2026-05-10T16:10:19.018791+00:00', '2026-07-12T17:37:20.86442+00:00'),
  ('4d2fd805-a56f-40b9-bc53-1ff6137a29cb', NULL, 'product-52', 'סידור ויברך דוד – תכלת קורדרוי', '<p>היכרות עם "ויברך דוד" – סידור תפילה מרהיב במהדורת קורדרוי מיוחדת בצבע תכלת, המעניק תחושה של רוגע ושלווה. עיצובו המוקפד והבד הייחודי הופכים אותו למתנה מושלמת לעצמכם או ליקירכם. הסידור כתוב באותיות ברורות, ומכיל את כל התפילות והברכות הדרושות לפסוקי תפילה סדורים, המלווים אתכם בכל רגע.</p>', 'סידור "ויברך דוד" במהדורה מיוחדת בצבע תכלת עדין, עטוף בקורדרוי יוקרתי. תפילה משובחת לחוויה רוחנית עמוקה.', 186.0, NULL, NULL, 'instock', NULL, 'https://deyidkzuvwniioxjisdr.supabase.co/storage/v1/object/public/product-images/opt/dc40c270415e3eb95aa03c8e.webp', true, '2026-05-31T11:04:26.373999+00:00', '2026-07-12T17:37:15.878613+00:00'),
  ('4d376740-8473-4fb7-8710-f5906b94df29', 2871374, 'talit-2871374', 'טלית דגם פאר תכלת', '<p>גלו את היופי השלו של טלית דגם פאר תכלת, יצירת מופת מבית מיטב האומנים שלנו. הטלית עשויה 100% צמר מרינו משובח, הרגיש ונושם, ומעוטרת בפסים עדינים בגוון תכלת רגוע, המשרים אווירה של קדושה ושלווה. עיצובה החד-פעמי, המשלב מסורת ומודרניות, הופך אותה לפריט חובה בכל בית יהודי, ולמתנה אידיאלית לבר-מצווה, חתונה או כל אירוע משמעותי. התעטפו בקדושה ובאלגנטיות.</p>', 'טלית דגם פאר תכלת - עשויה 100% צמר מרינו איכותי, עם עיטורים עדינים בגוון תכלת מרגיע. מושלמת לתפילה.', 500.0, 450.0, NULL, 'instock', NULL, 'https://deyidkzuvwniioxjisdr.supabase.co/storage/v1/object/public/product-images/opt/db7d9f2c36fbcc6f57cec85b.webp', true, '2026-05-31T11:10:09.145533+00:00', '2026-07-12T17:37:09.448529+00:00'),
  ('4d9a1640-316e-4cd0-8a2e-bc6733722f8c', 2069, 'פמוטי-זכוכית-1710-סמ', 'פמוטי זכוכית 17*10 ס"מ', '<p>הדליקו נרות באווירה קסומה עם פמוטי הזכוכית המרהיבים שלנו. בגודל אידיאלי של 17*10 ס"מ, הם משתלבים בהרמוניה בכל פינה בבית, מחדר האוכל ועד לפינת התפילה. עשויים זכוכית איכותית, הם שקופים ומאפשרים לאור הנרות למלא את החדר באור חם ומזמין. הוסיפו נגיעה של אלגנטיות ורוחניות לשבתות, חגים ולאירועים מיוחדים, או פשוט צרו רגע של שלווה יומיומית.</p>', 'פמוטי זכוכית מעוצבים, 17*10 ס"מ. מוסיפים חן ורוחניות לכל חלל.', 65.0, 53.98, 'UK80069', 'instock', NULL, 'https://deyidkzuvwniioxjisdr.supabase.co/storage/v1/object/public/product-images/opt/4a81ddf9426cf16d2d9aadfd.webp', true, '2026-05-10T16:10:19.018791+00:00', '2026-07-12T17:37:18.18728+00:00'),
  ('4f73bad9-55fa-48f7-b88c-0450917dcc4c', 2427, 'מזוזה-פולימרית-קלחת-15-סמ', 'מזוזה פולימרית "קלחת" 15 ס"מ', '<p>המזוזה, בגודל 15 ס"מ, משלבת עיצוב עתיק של קלחת עם חומר פולימרי עמיד וקל משקל. היא מהווה פריט יודאיקה ייחודי ומרגש, המשלב אומנות מסורתית עם טוויסט עכשווי. מתאימה לכל דלת ומוסיפה נופך של קדושה ויופי לבית. אינה כוללת קלף.</p>', 'מזוזת פולימר מעוצבת בצורת "קלחת" גדולה, מרהיבה ביופייה ומוסיפה נופך של מסורת מודרנית לבית.', 96.0, 79.98, 'UK24852', 'instock', NULL, 'https://deyidkzuvwniioxjisdr.supabase.co/storage/v1/object/public/product-images/opt/d009c51df56c0a4915a2e762.webp', true, '2026-05-10T16:10:19.018791+00:00', '2026-07-12T17:37:07.959369+00:00'),
  ('4fadb58e-4550-4149-8150-89ec01e92e2c', 2049, 'זוג-קופסאות-תפילין-מפלסטיק-גודל-32-צבע-כ', 'זוג קופסאות תפילין מפלסטיק גודל 32 - צבע כסף עם פלאק', '<p>שמרו על קדושת התפילין שלכם עם זוג קופסאות תפילין מעוצבות מפלסטיק איכותי. בגודל 32, צבע כסף עשיר, ועם פלאק מרשים, קופסאות אלו מספקות הגנה מצוינת ומוסיפות נופך של יוקרה. אידיאלי לבית או לנסיעות, ומבטיח שהתפילין שלכם יישארו במצב מושלם, מוכנים לשימוש בכל עת.</p>', 'זוג קופסאות תפילין מפלסטיק איכותי, בגודל 32, בצבע כסף אלגנטי עם פלאק. השמירה המכובדת על קדושת התפילין.', 65.0, 53.98, 'UK46372', 'instock', NULL, 'https://deyidkzuvwniioxjisdr.supabase.co/storage/v1/object/public/product-images/opt/95508215d4d0fbfb0208a917.webp', true, '2026-05-10T16:10:19.018791+00:00', '2026-07-12T17:37:19.692874+00:00'),
  ('50453989-d9da-4ef1-9123-4144c3560b40', 2872452, 'chal-2872452', 'כיסוי לטלית חלאקה לבן רקמה  בצבע כסף', '<p>שדרגו את טקס החלאקה עם כיסוי טלית לבן עשיר, רקום באלגנטיות עם חוטי כסף זוהרים. הכיסוי מעוצב להגן על טלית החלאקה ולשמור עליה לאורך זמן, תוך שהוא מוסיף נופך של קדושה והוד ליום החגיגי. עשוי מחומרים איכותיים, הוא מהווה מתנה משמעותית ובלתי נשכחת, שתלווה את הילד שנים רבות.</p>', 'כיסוי מהודר לטלית חלאקה, רקום בכסף עדין – מתנה מושלמת ליום מיוחד.', 129.0, NULL, NULL, 'instock', NULL, 'https://deyidkzuvwniioxjisdr.supabase.co/storage/v1/object/public/product-images/opt/5856f19da34f7f9e4ba809eb.webp', true, '2026-05-31T11:30:03.111272+00:00', '2026-07-12T17:37:07.286385+00:00'),
  ('5147a477-f231-4051-852c-fced5d80e310', NULL, 'product-40', 'סידור מעוצב מזמור לתודה לגבר צבע אפור כהה', '<p>גלו את סידור התפילה ''מזמור לתודה'', עוצב במיוחד עבור גברים שמעריכים איכות וסטייל. הבטנה המרהיבה בצבע אפור כהה מעניקה תחושה של עושר ורוגע, בעוד העיצוב הנקי והמודרני משתלב באופן מושלם בכל סביבה – מהבית ועד למשרד. הסידור מכיל תפילות נבחרות, כולל ''מזמור לתודה'', כתובות באותיות ברורות ונעימות לקריאה, על גבי נייר איכותי. זהו לא רק ספר תפילה, אלא פריט עיצובי שיעורר השראה ויזכיר את חשיבות ההודיה בכל יום.</p>', 'סידור ''מזמור לתודה'' לגבר – עיצוב מודרני ואלגנטי לאמירת תודה יומיומית. מתנה מושלמת שתלווה אותו בכל רגע.', 186.0, NULL, NULL, 'instock', NULL, 'https://deyidkzuvwniioxjisdr.supabase.co/storage/v1/object/public/product-images/opt/1230dcc532ff69a93a23cda9.webp', true, '2026-05-31T11:04:26.373999+00:00', '2026-07-12T17:37:15.317102+00:00'),
