  ('5380d080-cecf-4b84-acee-a4048d660e35', 2871386, 'talit-2871386', 'טלית דגם כתר עם עטרה שחורה יוקרתית רקמת שויתי ה לנגדי תמיד בכסוף', '<p>טלית "כתר" מעוצבת, המשלבת אלגנטיות מסורתית עם עיצוב יוקרתי. עטרה שחורה עשירה, רקמה כסופה מרהיבה של הפסוק "שויתי ה'' לנגדי תמיד" - כל אלו הופכים אותה לחוויה רוחנית נעלה. עשויה ממיטב הבדים, היא נוחה ונעימה בעת התפילה, ומספקת כיסוי מושלם. מתנה אידיאלית או תוספת אישית שתרומם את חווית התפילה.</p>', 'טלית כתר יוקרתית עם רקמת ''שויתי'' בכסף. עטרה שחורה אלגנטית - תוספת של קדושה ויופי לתפילה.', 714.0, NULL, NULL, 'instock', NULL, 'https://deyidkzuvwniioxjisdr.supabase.co/storage/v1/object/public/product-images/opt/1a27ec5d6f1641ad5f2671a4.webp', true, '2026-05-31T11:10:09.145533+00:00', '2026-07-12T17:37:05.472273+00:00'),
  ('5433a9de-08f8-45c7-9d84-f68ff8d6dc75', NULL, 'cover-camel-star-laser', 'כיסוי לטלית ותפילין - קמל מגן דוד לייזר', 'כיסוי איכותי לטלית ותפילין בגוון קמל/חאקי עם הדפס לייזר של מגן דוד וכיתוב "שיוויתי ה'' לנגדי תמיד". הרקמה ניתנת ללייזר בשם בלבד.', 'קמל עם מגן דוד - לייזר', 429.0, 300.0, NULL, 'instock', NULL, 'https://deyidkzuvwniioxjisdr.supabase.co/storage/v1/object/public/product-images/opt/6f6ff5d667ec814aa37ec573.webp', true, '2026-06-09T10:46:32.34945+00:00', '2026-07-12T17:37:08.292793+00:00'),
  ('554c967c-ae81-41db-bd10-84cb137ff45d', 2872365, 'chal-2872365', 'כיסוי לתלתל שלי לבן תכלת', '<p>כיסוי תפילין מהודר ומלא חיבה, שישמור על קדושת התפילין של ראש שלכם. בד איכותי, משלב גוונים עדינים של לבן ותכלת, יוצר מראה רגוע ומרשים. הכיסוי רך למגע, נעים לנשיאה ומגן מצוין. מתנה מושלמת לכל גבר.</p>', 'הגנה יומיומית יפיפייה לתפילין של ראש, בשילוב מושלם של לבן ותכלת.', 86.0, NULL, NULL, 'instock', NULL, 'https://deyidkzuvwniioxjisdr.supabase.co/storage/v1/object/public/product-images/opt/87dd070e9fadca4cfbdcda14.webp', true, '2026-05-31T11:30:03.111272+00:00', '2026-07-12T17:37:08.027413+00:00'),
