  ('5c43813c-202d-4d78-8f90-7017f2c8553d', NULL, 'product-56', 'סידור מבד טוויד – צבע חול ים', '<p>הכירו את סידור התפילה הייחודי שלנו, עטוף בבד טוויד יוקרתי בגוון של חול ים. זהו לא רק סידור תפילה, אלא פריט אומנות שמכניס רכות וסטייל לחיי היום-יום שלכם. הבד הנעים למגע והצבע העדין מעניקים תחושה של שלווה וחמימות, בזמן שאתם מתחברים לקדושה. מושלם כמתנה או כפינוק אישי, סידור זה יללווה אתכם בתפילותיכם, בבית, בנסיעות, או בכל מקום שתרצו להרגיש מחוברים.</p>', 'סידור תפילה מבד טוויד בצבע חול ים – רכות, סטייל וקדושה בכל מקום.', 186.0, NULL, NULL, 'instock', NULL, 'https://deyidkzuvwniioxjisdr.supabase.co/storage/v1/object/public/product-images/opt/7dca728ba814db72a5ddedd4.webp', true, '2026-05-31T11:04:26.373999+00:00', '2026-07-12T17:37:16.016702+00:00'),
  ('5ce041a6-303f-439c-bffe-ac7ca5596ef8', 2453, 'מזוזה-פולימרית-קלחת-20-סמ', 'מזוזה פולימרית "קלחת" 20 ס"מ', '<p>הוסיפו נגיעה של קדושה וסגנון לביתכם עם מזוזה פולימרית מעוצבת "קלחת". בגודל 20 ס"מ, היא משלבת עיצוב עכשווי עם מסורת עתיקה. הפולימר האיכותי מבטיח עמידות וקלות תחזוקה, בעוד שהעיצוב הייחודי "קלחת" מוסיף אלגנטיות לכל פתח. מזוזה זו אינה רק מצווה, אלא גם פריט אמנות שיכניס ברכה ושמחה לחלל.</p>', 'מזוזה פולימרית "קלחת" – 20 ס"מ של קדושה ויופי. עיצוב מודרני שמשתלב בכל בית, עם מסר של הגנה ושגשוג.', 120.0, 99.98, 'UK24853', 'instock', NULL, 'https://deyidkzuvwniioxjisdr.supabase.co/storage/v1/object/public/product-images/opt/fc5e66563d7d43f0af3d35ef.webp', true, '2026-05-10T16:10:19.018791+00:00', '2026-07-12T17:37:20.467856+00:00'),
  ('5d4a8ca5-dc99-48eb-b886-82a7b872a88d', 2141, 'נר-הבדלה-אלגנטי-משעווה-30-סמ', 'נר הבדלה אלגנטי משעווה 30 ס"מ', '<p>הוסיפו קסם וקדושה לסיום השבת עם נר הבדלה אלגנטי זה, המעוצב בקפידה משעווה טבעית איכותית. אורו הרך והנעים, בשילוב עם ניחוח עדין, יוצרים רגע של שלווה והתחדשות לקראת השבוע החדש. גובהו המרשים (30 ס"מ) מבטיח בעירה יציבה וממושכת, והופך אותו לפריט מרכזי בכל שולחן שבת. מתנה מושלמת ליקירים, או פריט שיעשיר כל בית ביופיו ובמשמעותו.</p>', 'נר הבדלה מפואר 30 ס"מ משעווה טבעית, להפצת ניחוח מרגיע וסיום שבת באווירה קדושה.', 38.0, 31.98, 'UK42999', 'instock', NULL, 'https://deyidkzuvwniioxjisdr.supabase.co/storage/v1/object/public/product-images/opt/76afc1e9f969117b742bb7b5.webp', true, '2026-05-10T16:10:19.018791+00:00', '2026-07-12T17:37:18.671512+00:00'),
