  ('619939a9-9869-4e4d-bf41-7cbc6a4fe770', 1265, 'נר-הבדלה-23-סמ-אלגנטי-וצבעוני', 'נר הבדלה 23 ס"מ - אלגנטי וצבעוני', '<p>הוסיפו נגיעה של צבע וקסם לטקס ההבדלה עם נר מיוחד זה, באורך 23 ס"מ. עשוי מחומרים איכותיים, הוא בוער באופן אחיד ומשרה אווירה של קדושה ויופי. העיצוב האלגנטי והצבעוני שלו הופך אותו לאביזר מרשים על שולחן השבת, ומזכיר את הפרידה מהקודש והחזרה לשגרה. מתנה אידיאלית לכל בית יהודי.</p>', 'הדליקו את סוף השבוע עם נר הבדלה צבעוני ואלגנטי באורך 23 ס"מ. משלים כל שולחן שבת ומכניס קדושה לבית.', 36.0, 29.98, 'UK55061', 'instock', NULL, 'https://deyidkzuvwniioxjisdr.supabase.co/storage/v1/object/public/product-images/opt/b434e747ea0f89aea9b5a34a.webp', true, '2026-05-10T16:10:19.018791+00:00', '2026-07-12T17:37:19.3944+00:00'),
  ('6242f09f-dc7f-48d3-b8c1-ddf171cee3a3', NULL, 'כיפה-אולטרא-סוויד-לבן-האש-שלי-זהב-19-סמ-17718', 'כיפה אולטרא סוויד לבן "האש שלי" זהב 19 ס"מ', NULL, 'כיפה אולטרא סוויד לבן "האש שלי" זהב 19 ס"מ', 61.0, NULL, 'UK17718', 'instock', NULL, 'https://deyidkzuvwniioxjisdr.supabase.co/storage/v1/object/public/product-images/opt/c68c716da0ef41e4b77f9635.webp', true, '2026-06-04T09:45:17.425583+00:00', '2026-07-12T17:37:13.171285+00:00'),
  ('6268ffd3-f7ee-4e89-8085-37264a1bae17', 2871987, 'talit-2871987', 'טלית פלטניום תשבץ  100% צמר רחלים דגם כהנים עטרה פינות וגב בצבע אבן', '<p>טלית פלטניום תשבץ עשויה 100% צמר רחלים משובח, העוטפת ברכות ונעימות. דגם כהנים המעודכן, עם עטרה ופינות בגוון אבן טבעי, מוסיף נופך של קדושה ויוקרה לתפילה. התשבץ המדויק והגימור המוקפד מבטיחים טלית שתלווה אותך בשנים הבאות, תוך חיבור עמוק למסורת.</p>', 'טלית פלטניום תשבץ: איכות צמר רחלים נדירה, עיצוב כהנים יוקרתי, עם עטרת פינות וגב בצבע אבן ייחודי.', 1572.0, NULL, NULL, 'instock', NULL, 'https://deyidkzuvwniioxjisdr.supabase.co/storage/v1/object/public/product-images/opt/15cc5c48944b2c2e97bbd0c1.webp', true, '2026-05-31T11:10:09.145533+00:00', '2026-07-12T17:37:16.568244+00:00'),
  ('6323c8e3-8569-4372-814c-584b9ae3e49a', 2873749, 'talit-2873749', 'טלית פלטניום תשבץ 100% צמר רחלים דגם כתר יברכך ה''  במגוון צבעים', '<p>התעטפו בברכה עם טלית פלטניום ''כתר יברכך ה''''. זוהי יצירת מופת מ-100% צמר רחלים טהור, מבטיחה רכות, נשימה ונוחות לאורך זמן. עיטורי התשבץ הייחודיים, בשילוב עם כתר מלכותי, מעניקים לטלית מראה יוקרתי ומרשים. בחרו מבין מגוון צבעים עשיר, והפכו כל תפילה לחוויה רוחנית ומעוצבת.</p>', 'טלית פלטניום יברכך ה'' – פסגת האיכות והיוקרה. עשויה 100% צמר רחלים משובח, דגם ''כתר'' בעיטור תשבץ אלגנטי.', 1572.0, NULL, NULL, 'instock', NULL, 'https://deyidkzuvwniioxjisdr.supabase.co/storage/v1/object/public/product-images/opt/5cdb8b2f4ea9de244c3b173f.webp', true, '2026-05-31T11:10:09.145533+00:00', '2026-07-12T17:37:21.156694+00:00'),
  ('63e73750-71e3-4266-93d9-27edaf97e81e', NULL, 'cover-cream-circle', 'כיסוי טלית ותפילין שמנת עם מעגל פסוקים - לייזר בלבד', NULL, 'כיסוי טלית ותפילין בגוון שמנת רך עם עיטור מעגלי. הטבעת שם אישי בלייזר בלבד.', 429.0, 300.0, NULL, 'instock', NULL, 'https://deyidkzuvwniioxjisdr.supabase.co/storage/v1/object/public/product-images/opt/252c3cf76bdfb3c7828bfff5.webp', true, '2026-06-09T10:43:24.061178+00:00', '2026-07-12T17:37:06.229295+00:00'),
  ('65792e35-87bf-4520-8d86-e488b00a08f5', 2083, 'קליפסים-לטלית-ניקל-לוחות-33-סמ-עם-שרשרת', 'קליפסים לטלית ניקל "לוחות" 3*3 ס"מ עם שרשרת', '<p>הוסיפו נופך של קדושה ויופי לטלית שלכם עם קליפסים מרהיבים מצופים ניקל, המעוצבים בדמות לוחות הברית. בגודל קומפקטי של 3x3 ס"מ, הם מספקים אחיזה יציבה ונוחה לטלית, ומבטיחים שהיא תישאר במקומה בכל עת. השרשרת הנלווית משלימה את המראה האלגנטי ומוסיפה פרקטיות. דרך נפלאה להראות הערכה לסידור התפילה ולשמירה על כבוד הדבר.</p>', 'קליפסים לטלית ניקל מעוצבים ב''לוחות הברית'' 3x3 ס"מ, עם שרשרת תואמת. עיצוב מרשים לחיבור נוח ומדויק של הטלית.', 43.0, 35.98, 'UK59334', 'instock', NULL, 'https://deyidkzuvwniioxjisdr.supabase.co/storage/v1/object/public/product-images/opt/e0fa2dcadee87ccfa0e18d13.webp', true, '2026-05-10T16:10:19.018791+00:00', '2026-07-12T17:37:09.174257+00:00'),
  ('65eac89c-31f9-425d-92c6-108f1f72b91e', 2129, 'עטרה-לטלית-929-סמ-עם-אבנים', 'עטרה לטלית 92*9 ס"מ עם אבנים', '<p>העניקו הוד והדר לתפילתכם עם עטרת טלית יפהפייה זו, שתלווה אתכם ברגעים הקדושים ביותר. העטרה, במידות 92*9 ס"מ, מעוצבת בקפידה ומשובצת באבנים זוהרות המוסיפות נופך של פאר ויוקרה. היא תהפוך כל טלית פשוטה ליצירת אמנות שתעורר השראה ותעצים את החוויה הרוחנית. מתנה מושלמת לעצמך או ליקיריכם.</p>', 'עטרת טלית מפוארת, מעוטרת באבנים נוצצות, תוסיף הוד והדר לתפילה. גודל 92*9 ס"מ.', 168.0, 139.98, 'UK47661', 'instock', NULL, 'https://deyidkzuvwniioxjisdr.supabase.co/storage/v1/object/public/product-images/opt/acc0aad6793b66e57207bb4c.webp', true, '2026-05-10T16:10:19.018791+00:00', '2026-07-12T17:37:09.19913+00:00'),
  ('6644b65f-72d0-4c1c-9bfb-f2490697e7b9', NULL, 'artj-uk66933', 'תיק מפואר לטלית דמוי עור אותיות בולטות "יברכך" כסף', '<p>הוסיפו אווירה של קדושה והדר לטלית שלכם עם תיק מפואר זה, העשוי דמוי עור משובח. האותיות הבולטות והנוצצות של "יברכך" בכסף טהור מעניקות מגע של יוקרה וייחודיות. התיק מעוצב להגן על הטלית שלכם בצורה אסתטית ומכובדת, ויהווה מתנה אידיאלית לאירועים חשובים או כאות הוקרה. שילוב של פונקציונליות, יופי ומשמעות רוחנית.</p>', 'תיק מהודר לדלית, מעוצב בדמוי עור איכותי עם הטבעת כסף "יברכך" באותיות בולטות. מתנה מושלמת ויוקרתית.', 357.14, NULL, 'UK66933', 'instock', NULL, 'https://deyidkzuvwniioxjisdr.supabase.co/storage/v1/object/public/product-images/opt/78df2e74049e22a30f809eaf.webp', true, '2026-05-31T11:25:25.72855+00:00', '2026-07-12T17:37:21.578182+00:00'),
  ('66c64b1e-66e9-4422-9a3e-9c4bfb71570c', 2871413, 'talit-2871413', 'טלית דגם פאר שחור עם עטרה שחורה יוקרתית רקמת יברכך ה'' וישמרך בכסוף', '<p>טלית דגם פאר שחורה זו היא הצהרה של יוקרה וקדושה. העטרה השחורה, מעוטרת ברקמת ''יברכך ה'' וישמרך'' בכסף טהור, מוסיפה נופך של אצילות מיוחדת. עשויה מבנה איכותי ונעים למגע, היא נועדה להעניק תחושת כבוד והגנה בכל תפילה. זוהי מתנה מושלמת לגבר או לאירוע מיוחד, המשלבת מסורת עתיקה עם עיצוב עכשווי ומרהיב.</p>', 'טלית פאר שחורה יוקרתית עם עטרת יברכך ה'' וישמרך בכסוף. איכות בלתי מתפשרת למראה מרשים וחוויה רוחנית עשירה.', 714.0, NULL, NULL, 'instock', NULL, 'https://deyidkzuvwniioxjisdr.supabase.co/storage/v1/object/public/product-images/opt/57046514dabd4c6a76e161c8.webp', true, '2026-05-31T11:10:09.145533+00:00', '2026-07-12T17:37:05.6268+00:00'),
  ('66d60dbc-cffc-40b1-9a95-42d7b0fd6aa3', NULL, 'laser-mizmor-letoda-white', 'מזמור לתודה לבן - חיתוך לייזר', NULL, 'לוח אקרילי לבן עם מזמור לתודה בחיתוך לייזר', 357.0, NULL, NULL, 'instock', NULL, 'https://deyidkzuvwniioxjisdr.supabase.co/storage/v1/object/public/product-images/opt/dc11eecfbe31b48e78299693.webp', true, '2026-06-21T12:45:15.77172+00:00', '2026-07-12T17:37:21.973671+00:00'),
  ('694868e0-22a9-4c9b-88f3-65d335e0ad82', NULL, 'נטלה-מהודרת-מפולימר-ציפוי-זהב-14-סמ-דגם-2-82820', 'נטלה מהודרת מפולימר ציפוי זהב 14 ס"מ (דגם 2)', NULL, 'נטלה מהודרת מפולימר ציפוי זהב 14 ס"מ (דגם 2)', 202.0, NULL, 'UK82820', 'instock', NULL, 'https://deyidkzuvwniioxjisdr.supabase.co/storage/v1/object/public/product-images/opt/2ca142cae050727949249445.webp', true, '2026-06-04T09:45:20.018148+00:00', '2026-07-12T17:37:10.026379+00:00'),
  ('6996595d-f36b-4f35-9a05-578d5eaa5cd5', 1272, 'כיסוי-חלה-מעור-דמוי-עור-4252-סמ-עם-רקמה', 'כיסוי חלה מעור דמוי עור 42*52 ס"מ עם רקמה', '<p>קבלו את כיסוי החלה הייחודי שלנו, עשוי עור דמוי עור איכותי בגודל מרשים של 42*52 ס"מ. הכיסוי מעוטר ברקמה עשירה ועדינה, המוסיפה נגיעה של אלגנטיות ושמחה לכל שולחן שבת. פרקטי וקל לניקוי, הוא ישמור על טריות החלה ויהפוך את הגשתה לחוויה קולינרית ותצוגתית כאחד. מתנה מושלמת או תוספת יוקרתית למטבח שלכם.</p>', 'כיסוי חלה מעור דמוי עור מפואר, בגודל 42*52 ס"מ, עם רקמה עשירה. מוסיף יוקרה ושמחה לשולחן השבת.', 192.0, 159.98, 'UK67359', 'instock', NULL, 'https://deyidkzuvwniioxjisdr.supabase.co/storage/v1/object/public/product-images/opt/900e9c17218ea72e4a0c764b.webp', true, '2026-05-10T16:10:19.018791+00:00', '2026-07-12T17:37:19.89319+00:00'),
  ('6a20cc8b-a707-452b-b766-704cd217d57a', 1985, 'סט-הפרשת-חלה-מעור-מלאכותי-40-סמ', 'סט "הפרשת חלה" מעור מלאכותי 40 ס"מ', '<p>הסט כולל מפה חגיגית מבד דמוי עור איכותי, המעוטרת בריקמת פרחים מרהיבה. נלווים לה כיסוי חלה תואם ושקית לבצק, המוסיפים נופך של קדושה. הסט מעוצב בקפידה כדי לשמש לטקס הפרשת החלה המשפחתי, ומעניק לו חוויה רוחנית ויוקרתית. אינו מצריך גיהוץ וקל לניקוי, מושלם לשמירה על טהרתו לאורך זמן.</p>', 'סט מרשים ואלגנטי להפרשת חלה, מתנה מושלמת לכל אירוע יהודי.', 120.0, 99.98, 'UK67310', 'instock', NULL, 'https://deyidkzuvwniioxjisdr.supabase.co/storage/v1/object/public/product-images/opt/5502eada6fc08e1af1da876a.webp', true, '2026-05-10T16:10:19.018791+00:00', '2026-07-12T17:37:11.860899+00:00'),
  ('6ae2fad6-e421-4fbd-b03d-b8629d05862d', NULL, 'product-21', 'סידור כותל לגבר שחור הטבעה בכסף', '<p>סידור תפילה לגבר, מהודר ואלגנטי, עשוי חומרים איכותיים ועמידים. כריכתו מעור שחור רך ונעים למגע, ועליה מוטבעת בטכניקת הטבעה חמה תמונת הכותל המערבי בגוון כסף מבריק. גודלו הקומפקטי ועיצובו המודרני הופכים אותו למתאים במיוחד לנשיאה לבית הכנסת, לטיולים או לכל עת בה תרצו להתפלל בנוחות ובכבוד. מתנה מושלמת לבר מצווה, חתונה או לכל מאורע משמח.</p>', 'סידור מהודר בגודל קומפקטי עטוף עור שחור ויוקרתי, עם הטבעה כסופה של תמונת הכותל המערבי.', 186.0, NULL, NULL, 'instock', NULL, 'https://deyidkzuvwniioxjisdr.supabase.co/storage/v1/object/public/product-images/opt/1dbce8e12e2ab10d6cef2907.webp', true, '2026-05-31T11:04:26.373999+00:00', '2026-07-12T17:37:14.607092+00:00'),
  ('6b169c67-be97-48e1-8746-6a28e430ea2c', NULL, 'esh-sheli-gold-ring-classic', 'טבעת זהב "האש שלי" קלאסית', 'טבעת "האש שלי" קלאסית מזהב 14K בעיצוב להבה עדין ומרשים. ניתן להזמין במידות שונות.<br><br><strong>המחיר משתנה לפי שער הזהב היומי.</strong><br>לתיאום הזמנה ובחירת מידה - צרו קשר בטלפון או בוואטסאפ.', 'טבעת "האש שלי" מזהב 14K בעיצוב להבה. ✦ המחיר משתנה לפי שער הזהב היומי.', 0.0, NULL, NULL, 'instock', NULL, 'https://deyidkzuvwniioxjisdr.supabase.co/storage/v1/object/public/product-images/opt/285a3315a23a9095a2476d67.webp', true, '2026-06-24T12:36:25.537318+00:00', '2026-07-12T17:37:18.917897+00:00'),
  ('6b4ab643-b8d6-481b-ab39-5b5066763de7', NULL, 'artj-uk67216', 'תיק מפואר לטלית קורדרוי ודמוי עור אותיות בולטות 31X38 ס"מ', '<p>הגן על הטלית היקרה שלך באלגנטיות מרבית עם תיק מרהיב זה. שילוב קטיפתי של קורדרוי איכותי עם דמוי עור יוקרתי יוצר מראה עשיר ומרשים. האותיות הבולטות מוסיפות נגיעה אישית ומיוחדת, והגודל האידיאלי (31X38 ס"מ) מבטיח נוחות מרבית. זהו הפריט המושלם לשמירה על הטלית, להגעה בית הכנסת או כמתנה מרגשת לכל אירוע.</p>', 'תיק טלית מהודר ואלגנטי מקורדרוי ודמוי עור, מעוטר באותיות בולטות. בגודל 31X38 ס"מ, המתנה המושלמת שמשלבת פונקציונליות וסגנון.', 357.14, NULL, 'UK67216', 'instock', NULL, 'https://deyidkzuvwniioxjisdr.supabase.co/storage/v1/object/public/product-images/opt/c6a57df3e28c6ec9ca0f30cd.webp', true, '2026-05-31T11:25:25.72855+00:00', '2026-07-12T17:37:06.141495+00:00'),
  ('6b75b0b4-1821-43e8-9cc5-e470e04fd061', NULL, 'גביע-קידוש-מהודר-מפולימר-עם-תחתית-15-סמ-דגם-2-47685', 'גביע קידוש מהודר מפולימר עם תחתית 15 ס"מ (דגם 2)', NULL, 'גביע קידוש מהודר מפולימר עם תחתית 15 ס"מ (דגם 2)', 202.0, NULL, 'UK47685', 'instock', NULL, 'https://deyidkzuvwniioxjisdr.supabase.co/storage/v1/object/public/product-images/opt/13ef8059d016c6784491a17a.webp', true, '2026-06-04T09:45:22.340788+00:00', '2026-07-12T17:37:12.427761+00:00'),
  ('6bec4158-d36e-47e8-92cf-1c50ad6569eb', NULL, 'גביע-קידוש-גימור-זהב-פיליגרין-עם-ברכה-ויכלו-8-5-סמ-120-מל-40866', 'גביע קידוש גימור זהב פיליגרין עם ברכה "ויכלו" 8.5 ס"מ - 120 מ"ל', NULL, 'גביע קידוש גימור זהב פיליגרין עם ברכה "ויכלו" 8.5 ס"מ - 120 מ"ל', 270.0, NULL, 'UK40866', 'instock', NULL, 'https://deyidkzuvwniioxjisdr.supabase.co/storage/v1/object/public/product-images/opt/9f2e95fcb27c966cdf0955d6.webp', true, '2026-06-04T09:45:23.206609+00:00', '2026-07-12T17:37:12.630607+00:00'),
  ('6bf7662f-cb56-4f40-aa01-b7b5a7f36a2c', NULL, 'כיפה-קטיפה-ארט-מן-עם-ריקמה-האש-שלי-אפור-גודל-3-10223', 'כיפה קטיפה "ארט-מן" עם ריקמה האש שלי - אפור (גודל 3)', NULL, 'כיפה קטיפה "ארט-מן" עם ריקמה האש שלי - אפור (גודל 3)', 61.0, 40.0, 'UK10223', 'instock', NULL, 'https://deyidkzuvwniioxjisdr.supabase.co/storage/v1/object/public/product-images/opt/bed6e912f3cd861bc2d006fd.webp', true, '2026-06-04T09:45:18.399591+00:00', '2026-07-12T17:37:10.214086+00:00'),
  ('6c159230-4410-43a2-94ee-3c201e5ec3d7', NULL, 'מסגרת-אקריליק-מהודרת-עם-פלקטה-23x24-סמ-80771', 'מסגרת אקריליק מהודרת עם פלקטה 23x24 ס"מ', NULL, 'מסגרת אקריליק מהודרת עם פלקטה 23x24 ס"מ', 270.0, NULL, 'UK80771', 'instock', NULL, 'https://deyidkzuvwniioxjisdr.supabase.co/storage/v1/object/public/product-images/opt/5e1ae1fa5cafd429df72d234.webp', true, '2026-06-04T09:45:16.823365+00:00', '2026-07-12T17:37:16.281184+00:00'),
  ('6c8cb00a-377e-4ed7-b4b6-42326e43e118', 1990, 'סט-פמוטים-קריסטל-אלגנטי-ומגש', 'סט פמוטים קריסטל אלגנטי ומגש', '<p>הוסיפו נגיעה של אלגנטיות נצחית לביתכם עם סט פמוטי קריסטל ומגש מעוצב. עשויים קריסטל איכותי, הפמוטים משדרים זוהר עדין המדגיש את להבת הנרות, בעוד המגש הרחב מקנה יציבות ומראה מושלם. מושלם להדלקת נרות שבת, חגים ואירועים מיוחדים, הוא ישדרג כל שולחן ויצור אווירה קסומה ומכובדת. מתנה נפלאה לכל משק בית, שתלווה אתכם לאורך שנים.</p>', 'יוקרה וזוהר לשבת: סט פמוטים קריסטל ומגש מהודר. מתנה מושלמת לכל בית יהודי.', 405.0, 239.98, 'UK81786', 'instock', NULL, 'https://deyidkzuvwniioxjisdr.supabase.co/storage/v1/object/public/product-images/opt/0873e7951b1d65382c531b21.webp', true, '2026-05-10T16:10:19.018791+00:00', '2026-07-12T17:37:13.212952+00:00'),
  ('6cc1290b-fd66-47b0-8176-80cf686a51a5', NULL, 'מזוזה-פולימר-בטון-כותל-ברכת-הבית-לבן-15-סמ-24642', 'מזוזה "פולימר בטון" כותל ברכת הבית לבן 15 ס"מ', NULL, 'מזוזה "פולימר בטון" כותל ברכת הבית לבן 15 ס"מ', 114.0, NULL, 'UK24642', 'instock', NULL, 'https://deyidkzuvwniioxjisdr.supabase.co/storage/v1/object/public/product-images/opt/08be64d0cce5146528b58ea9.webp', true, '2026-06-04T09:45:25.057137+00:00', '2026-07-12T17:37:12.901093+00:00'),
  ('6de8a276-4421-45fc-a2a0-935e8083cc78', 2871977, 'talit-2871977', 'טלית פלטניום תשבץ 100% צמר רחלים דגם בבא סאלי עטרה פינות וגב בצבע תכלת', '<p>טלית פלטניום דגם בבא סאלי – שילוב מרתק של מסורת וחדשנות. גוף הטלית עשויה 100% צמר רחלים משובח, טבעי ונושם, המעניק תחושה רכה ונעימה. עיטורי תשבץ עדינים מוסיפים אלגנטיות, בעוד שהעטרה וארבע הפינות בצבע תכלת מעניקים נגיעה של צבע ומבליטים את קדושת השימוש. טלית זו, המזכירה את דמותו של הצדיק בבא סאלי, היא הבחירה המושלמת למי שמחפש איכות, יופי וחיבור רוחני.</p>', 'טלית פלטניום במראה יוקרתי, מעוצבת בדוגמת תשבץ עדינה, עם עטרה ופינות תכלת. 100% צמר רחלים לאיכות מן המעלה.', 1572.0, NULL, NULL, 'instock', NULL, 'https://deyidkzuvwniioxjisdr.supabase.co/storage/v1/object/public/product-images/opt/929d91d2cca90934a2dace99.webp', true, '2026-05-31T11:10:09.145533+00:00', '2026-07-12T17:37:16.534848+00:00'),
  ('6e1a6b4a-3aa2-4a35-8a2a-69a631f3fe35', NULL, 'מזוזה-פולימר-בטון-שיש-גס-לבן-ש-ציפוי-זהב-12-סמ-21817', 'מזוזה "פולימר בטון" שיש גס לבן ש ציפוי זהב 12 ס"מ', NULL, 'מזוזה "פולימר בטון" שיש גס לבן ש ציפוי זהב 12 ס"מ', 135.0, NULL, 'UK21817', 'instock', NULL, 'https://deyidkzuvwniioxjisdr.supabase.co/storage/v1/object/public/product-images/opt/1a1e9fa0623518afdf2eba2b.webp', true, '2026-06-04T09:45:24.8188+00:00', '2026-07-12T17:37:11.799081+00:00'),
  ('6f164efd-d55f-4224-ba1e-a94bfd165f09', NULL, 'נטלה-מהודרת-מפולימר-ציפוי-זהב-14-סמ-דגם-3-82835', 'נטלה מהודרת מפולימר ציפוי זהב 14 ס"מ (דגם 3)', NULL, 'נטלה מהודרת מפולימר ציפוי זהב 14 ס"מ (דגם 3)', 202.0, NULL, 'UK82835', 'instock', NULL, 'https://deyidkzuvwniioxjisdr.supabase.co/storage/v1/object/public/product-images/opt/27cf20e7b273e6ed3ee487de.webp', true, '2026-06-04T09:45:22.096722+00:00', '2026-07-12T17:37:12.533662+00:00'),
  ('70bc78da-758a-4ba3-94c2-a41989216cbf', NULL, 'גביע-קריסטל-מהודר-האש-שלי-עם-אבנים-כסף-16-סמ-100-מל-47107', 'גביע קריסטל מהודר "האש שלי" עם אבנים כסף 16 ס"מ - 100 מ"ל', NULL, 'גביע קריסטל מהודר "האש שלי" עם אבנים כסף 16 ס"מ - 100 מ"ל', 171.43, NULL, 'UK47107', 'instock', NULL, 'https://deyidkzuvwniioxjisdr.supabase.co/storage/v1/object/public/product-images/opt/36fc5fb0d5ce05251208dcdc.webp', true, '2026-06-04T09:45:23.619957+00:00', '2026-07-12T17:37:09.676287+00:00')
INSERT INTO public.products (id, wp_id, slug, name, description, short_description, price, sale_price, sku, stock_status, stock_qty, thumbnail_url, is_active, created_at, updated_at) VALUES
  ('7204a574-6d86-477f-9fc9-ef510498ce87', NULL, 'artj-uk66248', 'תיק מפואר לטלית דמוי עור שחור אותיות בולטות "ויברכ"', '<p>מארז מפואר זה, עשוי דמוי עור שחור איכותי, נועד לשמור על טלית התפילין שלכם בכבוד וביוקרה. האותיות הבולטות "ויברכ" מעניקות לו נופך של קדושה ויהדות, בעוד המראה האלגנטי מבטיח שהוא יתאים לכל אירוע. העיצוב המוקפד והחומרים המשובחים הופכים אותו למתנה אידיאלית לבר מצווה, חתונה או כל אדם יקר שתרצו לפנק בפריט יודאיקה ייחודי.</p>', 'תיק מהודר לדברי קדושה, מעוצב ביוקרה ותשומת לב לפרטים. מתנה אידיאלית שתישמר לאורך שנים.', 357.14, NULL, 'UK66248', 'instock', NULL, 'https://deyidkzuvwniioxjisdr.supabase.co/storage/v1/object/public/product-images/opt/d9b2c9eea21966159270219f.webp', true, '2026-05-31T11:25:25.72855+00:00', '2026-07-12T17:37:06.513598+00:00'),
  ('7248d933-7b50-43b9-9cd7-fb4472d47aaf', NULL, 'artj-uk65787', 'תיק מפואר לטלית תפילין דמוי עור גוון שחור "יברכך"', '<p>העניקו כבוד והגנה לטלית ולתפילין שלכם עם התיק המפואר שלנו. עשוי דמוי עור איכותי בגוון שחור עמוק, הוא משדר יוקרה וקדושה. הטבעת המוזהבת של הפסוק "יברכך" מוסיפה נופך של ברכה והגנה, והתפירה המוקפדת מבטיחה עמידות לאורך שנים. זהו פריט חובה לכל מי שרוצה לשמור על קדושת ספרי התורה שלו בצורה מכובדת ואלגנטית.</p>', 'תיק מהודר לדברי קדושה: טלית ותפילין. עיצוב יוקרתי בצבע שחור, עם הטבעת ''יברכך'' להגנה וברכה.', 357.14, NULL, 'UK65787', 'instock', NULL, 'https://deyidkzuvwniioxjisdr.supabase.co/storage/v1/object/public/product-images/opt/b33d25b7051fce2fe73c4982.webp', true, '2026-05-31T11:25:25.72855+00:00', '2026-07-12T17:37:06.525949+00:00'),
  ('72a5f89e-619d-4079-972b-5e4ddb313b46', NULL, 'artj-uk67180', 'תיק מפואר לטלית דמוי עור עם "ויברכך" 38X31 ס"מ', '<p>תיק טלית איכותי ומהודר, מעוצב בקפידה מדמוי עור יוקרתי, בצבע חום כהה. במרכז התיק רקמת "ויברכך" מוזהבת, המוסיפה לו נופך רוחני ואסתטי. התיק מרופד מבפנים, מגן על הטלית מפני לכלוך או קמטים, ומגיע עם רוכסן נוח לפתיחה וסגירה. גודלו 38X31 ס"מ, מתאים לאחסון ושינוע של רוב הטליתות.</p>', 'תיק טלית מהודר דמוי עור עם רקמת "ויברכך", שומר על הטלית ומוסיף יופי לתפילה.', 357.14, NULL, 'UK67180', 'instock', NULL, 'https://deyidkzuvwniioxjisdr.supabase.co/storage/v1/object/public/product-images/opt/24a420b9f1045260a03292b5.webp', true, '2026-05-31T11:25:25.72855+00:00', '2026-07-12T17:37:06.211331+00:00'),
  ('72f3dd05-bc32-4df2-8bc3-da6aa57686e4', 2871986, 'talit-2871986', 'טלית פלטניום תשבץ 100% צמר רחלים דגם האש שלי תוקד עטרה פינות וגב בצבע אבן', '<p>התעטפו בסמל קדושה ויופי עם טלית פלטיניום ייחודית זו. עשויה 100% צמר רחלים משובח, היא נוחתת בעדינות על הכתפיים ומעניקה תחושת קדושה ונוחות. עיטור "שלי תוקד" בחלק העליון, בטכניקת תשבץ מודרנית, מוסיף נופך של עוצמה רוחנית. פינות הטלית, מעוטרות בצבע אבן טבעי, משלימות את המראה המלכותי והאלגנטי, והופכות אותה לבחירה מושלמת לתפילה ומתנה בלתי נשכחת.</p>', 'טלית פלטיניום יוקרתית, 100% צמר רחלים, עם עיטור האש "שלי תוקד". עיצוב תשבץ מודרני ופינות בצבע אבן.', 1572.0, NULL, NULL, 'instock', NULL, 'https://deyidkzuvwniioxjisdr.supabase.co/storage/v1/object/public/product-images/opt/7028187512bd5cf0db24e616.webp', true, '2026-05-31T11:10:09.145533+00:00', '2026-07-12T17:37:16.703838+00:00'),
