  ('e13f223c-24c6-4d92-8f25-8b4ab7da8a00', 2873755, 'talit-2873755', 'טלית פלטניום תשבץ 100% צמר רחלים דגם האש שלי  במגוון צבעים', '<p>טלית פלטניום תשבץ, עשויה 100% צמר רחלים איכותי, מציעה חוויית קדושה מחודשת. דגם "האש שלי" מתאפיין בגיאומטריה מודרנית ופאטרן תשבץ אלגנטי, המעניק לטלית מראה יוקרתי וייחודי. זמינה במגוון צבעים עשירים, היא משלבת מסורת עם עיצוב עכשווי, ומהווה מתנה מושלמת או תוספת אישית שתלווה אתכם בתפילותיכם.</p>', 'טלית פלטניום תשבץ - צמר רחלים 100% בעיצוב "האש שלי" בצבעים מרהיבים. גאווה יהודית, איכות ללא פשרות, עיצוב השראה.', 1572.0, NULL, NULL, 'instock', NULL, 'https://deyidkzuvwniioxjisdr.supabase.co/storage/v1/object/public/product-images/opt/32003ca6889da8dded6d56e2.webp', true, '2026-05-31T11:10:09.145533+00:00', '2026-07-12T17:37:21.142673+00:00'),
  ('e1cfb9b9-5e38-4296-921f-e637510aeab2', NULL, 'esh-sheli-silver-pendant-diamonds', 'שרשרת כסף "האש שלי" משובצת יהלומים', 'תליון "האש שלי" יוקרתי מכסף 925 משובץ אבני זרקון מבריקות בעבודת פאווה עדינה.<br><br><strong>המחיר משתנה לפי שער הכסף.</strong><br>לתיאום הזמנה וקבלת הצעת מחיר עדכנית - צרו קשר בטלפון או בוואטסאפ.', 'תליון "האש שלי" מכסף 925 משובץ אבני זרקון נוצצות, על שרשרת עדינה. ✦ המחיר משתנה לפי שער הכסף והאבנים.', 0.0, NULL, NULL, 'instock', NULL, 'https://deyidkzuvwniioxjisdr.supabase.co/storage/v1/object/public/product-images/opt/85c2608e1a6988aacd868ca8.webp', true, '2026-06-24T12:36:25.537318+00:00', '2026-07-12T17:37:18.488063+00:00'),
  ('e24f6897-13b4-474c-9959-203c21c625ed', NULL, 'product-18', 'סידור כותל לגבר ג''ינס תכלת בהיר הטבעה בכסף', '<p>הביאו את קדושת הכותל אל ליבו של כל יום עם סידור תפילה אלגנטי זה, המיועד במיוחד לגברים. הכריכה המיוחדת מג''ינס תכלת בהיר משלבת חוזק ועדינות, ומעליה מתנוססת הטבעת כסף איכותית, המוסיפה נגיעה של יוקרה וקדושה. סידור זה מהווה מתנה אישית ומרגשת, המשלבת יופי, איכות ומסורת, ומזמינה למרחב של שקט והתחדשות רוחנית בכל רגע.</p>', 'סידור כותל יוקרתי לגבר, מעוצב בג''ינס תכלת בהיר עם הטבעת כסף מרהיבה. מתנה שתלווה אותו בתפילה.', 186.0, NULL, NULL, 'instock', NULL, 'https://deyidkzuvwniioxjisdr.supabase.co/storage/v1/object/public/product-images/opt/2c5266acd89f2cb36e0b59e8.webp', true, '2026-05-31T11:04:26.373999+00:00', '2026-07-12T17:37:14.452996+00:00'),
  ('e29b4979-abf2-4165-9bfd-b870b98bfb86', NULL, 'artj-uk53706', 'תיק טלית גדול גוון שחור פיו מפואר אותיות בולטות "ה"', '<p>קחו את הטלית והתפילין שלכם לכל מקום בסטייל ובהגנה. התיק היוקרתי, העשוי מעור שחור פיו משובח, עוצב במיוחד לאחסון נוח ובטוח. האות "ה" המוזהבת הבולטת מוסיפה נופך של קדושה והדר, ומבטיחה שהחפצים היקרים שלכם יישמרו בכבוד הראוי. מתנה מושלמת לכל גבר, לקראת יום הנישואין, בר מצווה או כל אירוע משמח.</p>', 'תיק מהודר לאחסון טלית ותפילין, מעור שחור פיו יוקרתי עם אותיות "ה" מוטבעות.', 357.14, NULL, 'UK53706', 'instock', NULL, 'https://deyidkzuvwniioxjisdr.supabase.co/storage/v1/object/public/product-images/opt/384b6d704874e71ee13dc687.webp', true, '2026-05-31T11:25:25.72855+00:00', '2026-07-12T17:37:21.929226+00:00'),
  ('e2ec0c60-e6ac-4db9-8e1a-33a653c9f772', NULL, 'product-23', 'סידור כותל לגבר אפור הטבעה בכסף', '<p>התפללו בסטייל והוד עם סידור כותל זה, המיועד לגבר המודרני. הסידור בגוון אפור אלגנטי, משלים במראה יוקרתי עם הטבעת כסף עדינה המנצנצת באור. עשוי מחומרים איכותיים, הסידור הזה אינו רק כלי תפילה, אלא תכשיט רוחני המלווה אתכם ברגעים הקדושים ביותר. מתנה אידיאלית לאירועים מיוחדים, המוסיפה נופך של קדושה ויופי לכל בית.</p>', 'סידור כותל מהודר לגבר, מעוצב בגוון אפור מלכותי עם הטבעת כסף נוצצת. מתנה מושלמת עם משמעות עמוקה.', 186.0, NULL, NULL, 'instock', NULL, 'https://deyidkzuvwniioxjisdr.supabase.co/storage/v1/object/public/product-images/opt/9c1c627b478694a1633678aa.webp', true, '2026-05-31T11:04:26.373999+00:00', '2026-07-12T17:37:14.688804+00:00'),
  ('e2f655e8-52dd-44a6-b63e-6612edf105cf', 2090, 'תמונה-מפולימר-2619-סמ-אשר-יצר-אשכנז', 'תמונה מפולימר 26*19 ס"מ "אשר יצר" אשכנז', '<p>הוסיפו נופך של קדושה והגנה לביתכם עם תליון הפולימר המרהיב "אשר יצר" מאת אשכנז. בגודל 26*19 ס"מ, היצירה המעוצבת הזו משלבת אמנות מודרנית עם ברכה מסורתית, היוצרת אווירה של שלווה וביטחון. עשויה מחומרים איכותיים, היא מתאימה לתלייה בכניסה לבית, במטבח או בכל מקום בו תרצו להשרות אווירה חיובית ומוגנת.</p>', 'תליון מפולימר 26*19 ס"מ "אשר יצר" אשכנז – ברכה והגנה לביתכם.', 202.0, 119.98, 'UK40869', 'instock', NULL, 'https://deyidkzuvwniioxjisdr.supabase.co/storage/v1/object/public/product-images/opt/ce76f84ffdce596005f0b755.webp', true, '2026-05-10T16:10:19.018791+00:00', '2026-07-12T17:37:14.005117+00:00'),
  ('e4decc4b-6cdb-4ad1-a3dc-7086a52f6e7a', 1203, 'ברכת-הבדלה-מקרטון-עם-בזיליקום-בשמים-17-513-ס', 'ברכת הבדלה מקרטון עם בזיליקום בשמים 17.5*13 ס"מ', '<p>האירו את סוף השבת עם ברכת הבדלה מיוחדת זו, עשויה בקפידה מקרטון איכותי. המארז כולל בזיליקום עשיר בניחוחו, המוסיף קדושה ושמחה לטקס. העיצוב המרהיב בגודל 17.5*13 ס"מ משתלב נפלא בכל בית, והופך את רגע ההבדלה לחוויה בלתי נשכחת ורבת משמעות. מתנה מושלמת שתעשיר כל שבת מחדש.</p>', 'ברכת הבדלה מהודרת במארז קרטון מפואר, כוללת בזיליקום בשמים, בגודל 17.5*13 ס"מ.', 19.0, 15.98, 'UK48853', 'instock', NULL, 'https://deyidkzuvwniioxjisdr.supabase.co/storage/v1/object/public/product-images/opt/1ceb5ba7d7dc843929853515.webp', true, '2026-05-10T16:10:19.018791+00:00', '2026-07-12T17:37:09.066977+00:00'),
  ('e5226780-2550-47eb-819d-ec07bf2e67ce', NULL, 'פמוטי-קריסטל-חמשייה-מהודרים-19-5-סמ-דגם-2-41630', 'פמוטי קריסטל חמשייה מהודרים 19.5 ס"מ (דגם 2)', NULL, 'פמוטי קריסטל חמשייה מהודרים 19.5 ס"מ (דגם 2)', 270.0, NULL, 'UK41630', 'instock', NULL, 'https://deyidkzuvwniioxjisdr.supabase.co/storage/v1/object/public/product-images/opt/29a17e27ebd1ae66831c03a2.webp', true, '2026-06-04T09:45:11.141317+00:00', '2026-07-12T17:37:09.645849+00:00'),
  ('e5ae24db-bc39-4943-90fd-8707e77c0e03', 2872428, 'chal-2872428', 'סט חלאקה פרימיום דגם כתר רקמה בזהב וציצית גופיה', '<p>חגגו את רגע החלאקה הראשון של ילדכם עם סט פרימיום עוצר נשימה, "כתר רקמה". הכתר המרהיב, מעוטר ברקמה עשירה בחוטי זהב, מעניק תחושת מלכותיות לחגיגה. הגופייה המצורפת, עשויה מבד נעים ונושם, מבטיחה נוחות מקסימלית ותואמת את רוח האירוע הקדוש. סט זה הוא לא רק פריט לבוש, אלא מזכרת יקרה שתשאיר חותם של קדושה ויופי.</p>', 'סט חלאקה יוקרתי "כתר רקמה" - חווית קודש בלתי נשכחת. כולל גופיית ציצית מושלמת.', 686.0, NULL, NULL, 'instock', NULL, 'https://deyidkzuvwniioxjisdr.supabase.co/storage/v1/object/public/product-images/opt/eaf2a3e08b1966d9192f2d6c.webp', true, '2026-05-31T11:30:03.111272+00:00', '2026-07-12T17:37:07.122043+00:00'),
  ('e5f79a5e-5cba-4da4-8487-d49c2c5cb67e', NULL, 'product-26', 'סידור כתר לגבר ג''ינס תכלת בהיר הטבעה בכסף', '<p>סידור תפילה ''כתר'' לגבר, בגוון ג''ינס תכלת בהיר ייחודי, משלב עיצוב מודרני עם קדושת התפילה. הטבעת כסף עדינה מוסיפה נופך של יוקרה וייחודיות. הסידור מושלם לשימוש יומיומי, כמתנה מרגשת לבר מצווה, ליום הולדת או לכל אירוע משמעותי. חווית תפילה מחודשת, באסתטיקה על-זמנית.</p>', 'סידור ''כתר'' לגבר: מעוצב בגוון ג''ינס תכלת בהיר, עם הטבעה יוקרתית בכסף. אלגנטיות וקדושה בכל תפילה.', 186.0, NULL, NULL, 'instock', NULL, 'https://deyidkzuvwniioxjisdr.supabase.co/storage/v1/object/public/product-images/opt/ec90e23d013e1f25e7edf336.webp', true, '2026-05-31T11:04:26.373999+00:00', '2026-07-12T17:37:14.820615+00:00'),
  ('e6a4260e-8aff-410b-8992-d7e8ede8bf24', 2030, 'זוג-פמוטי-קריסטל-אלגנטיים-9-סמ', 'זוג פמוטי קריסטל אלגנטיים 9 ס"מ', '<p>האירו את ביתכם באלגנטיות עם זוג פמוטי קריסטל מרהיבים בגובה 9 ס"מ. כל פמוט מעוצב בקפידה מחומר קריסטל איכותי, המעניק ברק ייחודי ומשחק אורות מהפנט. מושלמים כמנורות לשבת, לבר מצווה, לחגים או כפריט עיצובי מרשים בכל פינה. הוסיפו נגיעה של זוהר ושמחה לחלל שלכם עם פמוטים שאין דומה להם.</p>', 'זוג פמוטי קריסטל מהודרים 9 ס"מ – אור חגיגי לעיצוב שובה לב. מושלמים לכל אירוע, מוסיפים נגיעה של יוקרה.', 180.0, 149.98, 'UK42123', 'instock', NULL, 'https://deyidkzuvwniioxjisdr.supabase.co/storage/v1/object/public/product-images/opt/2d92a3b05a87d70868df9e1f.webp', true, '2026-05-10T16:10:19.018791+00:00', '2026-07-12T17:37:17.98628+00:00'),
  ('e71f1e9a-6494-4706-9698-307d01334b97', NULL, 'product-49', 'סידור ויברך דוד – לבן קורדרוי', '<p>סידור "ויברך דוד" במהדורה מיוחדת, עטוף בבד קורדרוי לבן ורך למגע. הבד היוקרתי מעניק תחושה נעימה ואינטימית בזמן התפילה, ושומר על הסידור לאורך שנים. העיצוב הנקי והקלאסי משתלב בכל סגנון עיצוב, והופך אותו למתנה מושלמת לכל אירוע. חווית תפילה מעודנת ומלאת הוד.</p>', 'סידור ויברך דוד – לבן קורדרוי: תפילה בנוחות וסטייל. כיסוי קורדרוי רך ויוקרתי, מושלם לכל בית.', 186.0, NULL, NULL, 'instock', NULL, 'https://deyidkzuvwniioxjisdr.supabase.co/storage/v1/object/public/product-images/opt/f32de52616b850338ed43394.webp', true, '2026-05-31T11:04:26.373999+00:00', '2026-07-12T17:37:15.601671+00:00'),
  ('e7fbb4bb-f3df-442a-88bf-e1aec0c42515', 1080, 'גביע-קידוש-קריסטל-9-סמ-ללא-גבעול-מכיל-100-מ-2', 'גביע קידוש קריסטל 9 ס"מ - ללא גבעול מכיל 100 מ"ל / 3.4 אונקיות', '<p>הוסיפו נופך של הוד לטקסי השבת והחג עם גביע קידוש קריסטל עוצר נשימה ביופיו. העיצוב המודרני ללא גבעול מעניק לו יציבות וסטייל, בעוד שהקריסטל הצלול מבטיח שהיין ינצנץ באור. גביע זה, בנפח 100 מ"ל, הוא הבחירה האידיאלית לקידוש יומי או כמתנה יוקרתית ומרגשת לכל מי שמעריך יופי וקדושה.</p>', 'גביע קידוש קריסטל אלגנטי 9 ס"מ, מושלם לבית או למתנה. מעוצב ללא גבעול, בנפח 100 מ"ל.', 219.0, 129.98, 'UK47092', 'instock', NULL, 'https://deyidkzuvwniioxjisdr.supabase.co/storage/v1/object/public/product-images/opt/1ea86ec0a733cdd10a8f2061.webp', true, '2026-05-10T16:10:19.018791+00:00', '2026-07-12T17:37:09.224361+00:00'),
  ('e80d5316-f196-483d-927d-4227c116e121', 2871958, 'talit-2871958', 'טלית פרימיום תשבץ  100% צמר רחלים דגם יברכך עטרה ופינות רקומות בצבע לבן', '<p>הטלית מדגם ''יברכך'' מבית היוצר של פרימיום תשבץ, עשויה 100% צמר רחלים משובח, מגלמת בתוכה יוקרה וקדושה. העטרה והפינות מעוטרות ברקמה לבנה עדינה, המוסיפה נופך של אלגנטיות לכל תפילה. טלית זו היא לא רק פריט לבוש, אלא חוויה רוחנית עשירה, נוחה ומרשימה, שתלווה אתכם ברגעים הקדושים ביותר.</p>', 'טלית פרימיום תשבץ, 100% צמר רחלים, דגם ''יברכך'' עם עטרה ופינות רקומות לבן. איכות מרהיבה לתפילה.', 786.0, NULL, NULL, 'instock', NULL, 'https://deyidkzuvwniioxjisdr.supabase.co/storage/v1/object/public/product-images/opt/d6b7733342eef134b1a5f4de.webp', true, '2026-05-31T11:10:09.145533+00:00', '2026-07-12T17:37:16.966093+00:00'),
  ('e883b56a-e13f-4f07-ae57-a34f17693a12', NULL, 'mizmor-premium', 'מזמור דגם פרימיום', NULL, 'מזמור לתודה - חיתוך לייזר', 929.0, NULL, NULL, 'instock', NULL, 'https://deyidkzuvwniioxjisdr.supabase.co/storage/v1/object/public/product-images/opt/2b5cf77944c8191dc53e38ef.webp', true, '2026-06-21T12:31:00.896671+00:00', '2026-07-12T17:37:13.493355+00:00'),
  ('e89edd26-55a9-4954-ad99-d2bba1935b06', NULL, 'groom-set-yaron-biton', 'מארז לחתן - דמוי עור חום', 'מארז חתן יוקרתי הכולל תיק טלית, תיק תפילין, כיפה וסידור עם רקמה אישית טלית צמר רכלים תשב"צ כולל עטרה ופינות ותיק תואם וכיפה תואמת עם אפשרות לרשום את השם בלייזר.', 'מארז חתן יוקרתי הכולל תיק טלית, תיק תפילין, כיפה וסידור עם רקמה אישית', 2000.0, 1400.0, NULL, 'instock', NULL, 'https://deyidkzuvwniioxjisdr.supabase.co/storage/v1/object/public/product-images/opt/4336cd6389a8470ad33d87e8.webp', true, '2026-06-09T10:37:37.638981+00:00', '2026-07-12T17:37:08.92677+00:00'),
  ('e8ac3b7e-8a76-40af-8643-6ad184da922d', 2437, 'מזוזה-פולימר-לבן-שוק-זהב-15-סמ', 'מזוזה פולימר לבן שוק זהב 15 ס"מ', '<p>הוסיפו נגיעת קדושה ויוקרה לביתכם עם מזוזה פולימר לבנה מעוצבת, בגודל 15 ס"מ. עיטורי שוק הזהב המתכתיים מוסיפים אלגנטיות עדינה, והפולימר האיכותי מבטיח עמידות לאורך שנים. מזוזה זו אינה רק אביזר דקורטיבי, אלא סמל למסורת ולברכה, המחבר בין הבית לעולם היהדות. מתנה מושלמת לכל בית, המשלבת יופי, איכות ומשמעות.</p>', 'מזוזה פולימר לבנה עם עיטורי שוק זהב, 15 ס"מ. תוספת יוקרתית ומבורכת לכל דלת.', 108.0, 89.98, 'UK21383', 'instock', NULL, 'https://deyidkzuvwniioxjisdr.supabase.co/storage/v1/object/public/product-images/opt/c38bbe9da63adf595c89a1c2.webp', true, '2026-05-10T16:10:19.018791+00:00', '2026-07-12T17:37:19.237415+00:00'),
  ('e9740a67-561e-46c5-ace5-93fc47ba8306', NULL, 'מסגרת-נצנצים-מזכוכית-עיצוב-קווים-ברכת-העסק-22x17-סמ-81129', 'מסגרת נצנצים מזכוכית עיצוב "קווים" ברכת העסק 22x17 ס"מ', NULL, 'מסגרת נצנצים מזכוכית עיצוב "קווים" ברכת העסק 22x17 ס"מ', 113.0, NULL, 'UK81129', 'instock', NULL, 'https://deyidkzuvwniioxjisdr.supabase.co/storage/v1/object/public/product-images/opt/43ff63539046dbf43db1bd93.webp', true, '2026-06-04T09:45:16.325586+00:00', '2026-07-12T17:37:09.931891+00:00'),
  ('ea5485c9-a92b-46e4-b517-28b9a22641dc', 2872424, 'chal-2872424', 'סט חלאקה פרימיום דגם כתר רקמה בכסף וציצית גופיה', '<p>העניקו לחתן בר המצווה שלכם מתנה שתישאר לעד. סט חלאקה דגם ''כתר רקמה'' מציג כתר מפואר, מעוטר ברקמה עדינה בכסף אמיתי, המוסיף נופך מלכותי ליום המיוחד. הסט כולל גם גופיית ציצית איכותית, עשויה מבד נושם ונעים למגע, המבטיחה נוחות מירבית. כל פרט בסט עוצב בקפידה, משלב מסורת עשירה עם אסתטיקה מודרנית, ויוצר מזכרת יוקרתית ומרגשת.</p>', 'סט פרימיום לחינה – כתר רקמה בכסף וגופיית ציצית, מתנה מושלמת לבר מצווה, בעבודת יד מרהיבה.', 686.0, NULL, NULL, 'instock', NULL, 'https://deyidkzuvwniioxjisdr.supabase.co/storage/v1/object/public/product-images/opt/2a6589885aceabbdfb3ff9aa.webp', true, '2026-05-31T11:30:03.111272+00:00', '2026-07-12T17:37:07.451827+00:00'),
  ('ea6eb81c-abd2-4cb7-8b3d-f0e239736a90', 2870871, 'chal-2870871', 'סט חלאקה קלאסי דגם האש שלי רקמה בכסף', '<p>חגגו את רגע ה"חלאקה" הראשון של ילדכם עם סט יוקרתי ומלא משמעות. הסט, "האש שלי", מקושט ברקמת כסף אמיתית ועדינה, המוסיפה נגיעה של קסם ומסורת. עשוי מחומרים איכותיים, הסט כולל את כל הפריטים החיוניים לטקס מרגש זה, והופך אותו למזכרת עוצרת נשימה שתלווה אתכם ואת ילדכם לשנים רבות. זהו לא סתם סט, זוהי התחלה של סיפור, מעוצב בקפידה להבטיח חוויה בלתי נשכחת.</p>', 'סט חלאקה עשיר ומעוצב, "האש שלי" – מתנה יוקרתית לציון אירוע מרגש. רקמת כסף אמיתית מוסיפה נופך אלגנטי.', 357.0, NULL, NULL, 'instock', NULL, 'https://deyidkzuvwniioxjisdr.supabase.co/storage/v1/object/public/product-images/opt/4c029e9f90a4eeaea9523c65.webp', true, '2026-05-31T11:30:03.111272+00:00', '2026-07-12T17:37:21.370346+00:00'),
  ('ea98690b-463a-4c6d-ad33-cee0672c1515', 2411, 'מזוזה-דמוית-אבן-פולימר-15-סמ', 'מזוזה דמוית אבן פולימר 15 ס"מ', '<p>הוסיפו נופך של יוקרה והגנה לפתח ביתכם עם מזוזה מהודרת זו. עשויה מפולימר איכותי המעוצב להפליא להיראות כאבן טבעית, היא משלבת עמידות עם אסתטיקה מרשימה. מידותיה (15 ס"מ) הופכות אותה לבחירה מושלמת לרוב המשקופים. מזוזה זו, כתר של קדושה ויופי, מזמינה שפע וברכה לכל פינה בבית.</p>', 'מזוזה דמוית אבן פולימר 15 ס"מ – מגע קלאסי ומודרני בכניסה לביתכם.', 101.0, 59.98, 'UK24448', 'instock', NULL, 'https://deyidkzuvwniioxjisdr.supabase.co/storage/v1/object/public/product-images/opt/410f44d858cde6c55d745bfb.webp', true, '2026-05-10T16:10:19.018791+00:00', '2026-07-12T17:37:16.244956+00:00'),
  ('eb505f43-4cc8-4001-a4fc-7d40feabab9d', NULL, 'הדלקת-נרות-בלוק-אקריליק-מסגרת-זהב-80507', 'הדלקת נרות בלוק אקריליק מסגרת זהב', NULL, 'הדלקת נרות בלוק אקריליק מסגרת זהב', 270.0, 200.0, 'UK80507', 'instock', NULL, 'https://deyidkzuvwniioxjisdr.supabase.co/storage/v1/object/public/product-images/opt/14047b1cd84674e06f83f87a.webp', true, '2026-06-04T09:45:16.943935+00:00', '2026-07-12T17:37:17.634956+00:00'),
  ('ec7436d2-2cf9-4794-ae38-494b265701ff', 2873089, 'talit-2873089', 'טלית פרימיום בחריטת לייזר בד תשבץ  100% צמר רחלים דגם יברכך ה'' במגוון צבעים', '<p>טלית פרימיום זו, עשויה100% צמר רחלים משובח, מציעה חוויה של התעלות רוחנית לצד גימור אומנותי ללא פשרות. בד התשבץ האלגנטי מחבק בגופך בחום ורכות, בעוד חריטת הלייזר הדקיקה של הפסוק "יברכך ה''" מוסיפה נופך אישי ומשמעותי. בחרו את הצבע המועדף עליכם, והתעטפו בברכה, ביופי ובמסורת.</p>', 'טלית פרימיום בתשבץ, 100% צמר רחלים, בעיצוב לייזר ייחודי "יברכך ה''" – השילוב המושלם של איכות, סטייל וקדושה.', 1286.0, NULL, NULL, 'instock', NULL, 'https://deyidkzuvwniioxjisdr.supabase.co/storage/v1/object/public/product-images/opt/ff564ffd9aba7d038d0d24c6.webp', true, '2026-05-31T11:10:09.145533+00:00', '2026-07-12T17:37:21.132525+00:00'),
  ('ec8f7edc-8017-4797-bf9c-5699d6bd8a0e', NULL, 'product-27', 'סידור כתר לגבר לבן הטבעה בכסף', '<p>סידור כתר מרשים לגבר, מעוצב בקפידה מנייר איכותי ובכריכת עור אלגנטית. במרכז הכריכה, הטבעת כסף טהור מוסיפה נופך של יוקרה וייחודיות. הסידור מכיל תפילות יומיות, שבת וחגים, ומגיע בעיצוב נקי וקלאסי המתאים לכל אדם. זוהי מתנה אידיאלית לכל אירוע משמעותי בחייו של גבר, המשלבת מסורת עשירה עם אסתטיקה מודרנית.</p>', 'סידור כתר לגבר – עיצוב קלאסי ויוקרתי, עם הטבעה בכסף טהור. מתנה מושלמת לכל גבר.', 186.0, NULL, NULL, 'instock', NULL, 'https://deyidkzuvwniioxjisdr.supabase.co/storage/v1/object/public/product-images/opt/dff990e78ed442f4a59d9881.webp', true, '2026-05-31T11:04:26.373999+00:00', '2026-07-12T17:37:14.747954+00:00'),
  ('ed8ff043-65c2-4f4b-b3ed-769b3c4d3c16', 2025, 'זוג-פמוטי-קריסטל-אלגנטיים-7-סמ', 'זוג פמוטי קריסטל אלגנטיים 7 ס"מ', '<p>הוסיפו נגיעה של יוקרה וקסם לביתכם עם זוג פמוטי קריסטל עוצרי נשימה. בגודל אידיאלי של 7 ס"מ, הם משתלבים נפלא בכל חלל, מהדהדים את אור הנרות ויוצרים אווירה חגיגית ומיוחדת. עשויים קריסטל איכותי, הם מהווים מתנה נפלאה ומרשימה לכל אירוע, או פינוק אישי שילווה אתכם בשבתות וחגים.</p>', 'פמוטי קריסטל מהודרים במידה 7 ס"מ, מוסיפים ברק ושמחה לכל שולחן שבת וחג.', 156.0, 129.98, 'UK42401', 'instock', NULL, 'https://deyidkzuvwniioxjisdr.supabase.co/storage/v1/object/public/product-images/opt/3c33babf8dbc61a13edc8718.webp', true, '2026-05-10T16:10:19.018791+00:00', '2026-07-12T17:37:19.698013+00:00'),
