  ('eefa4231-c472-4761-b4bc-33ddbf537d27', NULL, 'product-36', 'סידור מעוצב כתר מובלט לגבר צבע לבן', '<p>העניקו נופך של קדושה והוד ללימוד ולתפילה עם סידור תפילה מעוצב במיוחד לגבר. הכריכה הלבנה הנקייה מעוטרת בכתר תלת-מימדי מוזהב, מרשים ובולט, המסמל את מלכות שמיים. הסידור איכותי, מתוכנן לנוחות קריאה מרבית, ומהווה מתנה אידיאלית לכל אירוע משמעותי בחייו של אדם יקר.</p>', 'סידור תפילה מהודר לגבר: כתר תלת-מימדי מוזהב על לבן, יוקרתי ומרשים.', 186.0, NULL, NULL, 'instock', NULL, 'https://deyidkzuvwniioxjisdr.supabase.co/storage/v1/object/public/product-images/opt/f96f5d948a96adcd210b7d0e.webp', true, '2026-05-31T11:04:26.373999+00:00', '2026-07-12T17:37:15.113311+00:00'),
  ('ef163a9a-5111-461a-89c1-31a548d0c222', NULL, 'נטלה-פולימר-מהודרת-גוון-שחור-עם-כיתוב-על-נטילת-ידים-14-סמ-דגם-2-47289', 'נטלה פולימר מהודרת גוון שחור עם כיתוב "על נטילת ידים" 14 ס"מ (דגם 2)', NULL, 'נטלה פולימר מהודרת גוון שחור עם כיתוב "על נטילת ידים" 14 ס"מ (דגם 2)', 185.0, NULL, 'UK47289', 'instock', NULL, 'https://deyidkzuvwniioxjisdr.supabase.co/storage/v1/object/public/product-images/opt/cf05b7bcddc708af9f46d689.webp', true, '2026-06-04T09:45:21.312987+00:00', '2026-07-12T17:37:10.614888+00:00'),
  ('ef44e371-3435-406b-87c3-5dcacdd3d2f4', 2873061, 'talit-2873061', 'טלית פרימיום בחריטת לייזר בד תשבץ  100% צמר רחלים דגם שמע ישראל', '<p>חוו דואט של קודש ועיצוב עם טלית פרימיום זו, עשויה 100% צמר רחלים טהור. בד התשבץ הקלאסי מקנה לה מראה יוקרתי, בעוד חריטת הלייזר המדויקת של "שמע ישראל" מוסיפה נופך רוחני ייחודי. כל סיב של צמר רחלים טבעי נבחר בקפידה כדי להבטיח רכות, נוחות ועמידות לאורך שנים. טלית זו אינה רק פריט לבוש מרשים לתפילה, אלא גם מתנה מהודרת ובעלת משמעות לכל אירוע חשוב.</p>', 'טלית פרימיום בתשבץ צמר רחלים טהור, עם חריטת לייזר "שמע ישראל" – עוטפת ברכה ועומק.', 1286.0, NULL, NULL, 'instock', NULL, 'https://deyidkzuvwniioxjisdr.supabase.co/storage/v1/object/public/product-images/opt/3b9715340425ce1f22acebad.webp', true, '2026-05-31T11:10:09.145533+00:00', '2026-07-12T17:37:06.194517+00:00'),
  ('ef782833-30bf-44df-bd1b-39f98cf575b7', NULL, 'product-6', 'סידור מעוצב ברכת הכהנים לגבר קורדרוי אפור בהיר', '<p>סידור ברכת הכהנים לגבר, עטוף בקורדרוי אפור בהיר בעל מגע רך ויוקרתי. העיצוב המודרני והאלגנטי הופך אותו לפריט שקל לשלב בכל חלל, מחדר השינה ועד לפינה מיוחדת בסלון. כל סידור מגיע עם ברכת הכהנים המתנוססת מעל, עשויה איכותית, ומוכן להעניק השראה והגנה. זוהי מתנה אידיאלית ומרגשת לכל אירוע משמעותי.</p>', 'סידור ברכת הכהנים לגבר בעיצוב קורדרוי אפור בהיר. מתנה יוקרתית ומקורית לכל גבר.', 186.0, NULL, NULL, 'instock', NULL, 'https://deyidkzuvwniioxjisdr.supabase.co/storage/v1/object/public/product-images/opt/adc3b188a9954072a1be7cfc.webp', true, '2026-05-31T11:04:26.373999+00:00', '2026-07-12T17:37:13.73286+00:00'),
  ('ef80c997-ee2c-475f-b1a1-df1e52a5cf96', NULL, 'product-33', 'סידור מעוצב כתר מובלט לגבר ג''ינס שחור', '<p>הסידור הזה הוא לא עוד מחזור תפילה, אלא פריט עיצובי שישדרג כל רגע כנס. כתר תלת-ממדי מובלט מעניק לו נופך מלכותי, בעוד עיצוב ג''ינס שחור מעניק לו מראה מודרני ואלגנטי. עשוי מנייר משובח ועם טקסט קריא וברור, הוא אידיאלי לשימוש יומיומי או כמתנה מרגשת ומכובדת. סידור יפהפה שיעורר השראה בכל תפילה.</p>', 'סידור תפילה יוקרתי לגבר, כתר מובלט ועיצוב ג''ינס שחור. מתנה מושלמת לכל אחד.', 186.0, NULL, NULL, 'instock', NULL, 'https://deyidkzuvwniioxjisdr.supabase.co/storage/v1/object/public/product-images/opt/4fb77da3cbfecdd3a3fa6842.webp', true, '2026-05-31T11:04:26.373999+00:00', '2026-07-12T17:37:15.115494+00:00'),
  ('ef853673-8e5b-4292-b8ee-3f1393db1a5c', NULL, 'tehillim-avodah-shebalev-silver', 'תהילים עבודה שבלב - כריכת כותל כסף', NULL, 'תהילים עבודה שבלב בכריכה מהודרת בעיצוב אבני הכותל בגוון כסף מטאלי', 130.0, 111.0, NULL, 'instock', 50, 'https://deyidkzuvwniioxjisdr.supabase.co/storage/v1/object/public/product-images/opt/7f7b35277db5b9109677e6de.webp', true, '2026-06-16T13:31:12.831392+00:00', '2026-07-12T17:37:11.455789+00:00'),
  ('ef935d79-c41a-47ec-8f85-25d40f904223', NULL, 'נטלה-מהודרת-מפולימר-14-סמ-41139', 'נטלה מהודרת מפולימר 14 ס"מ', NULL, 'נטלה מהודרת מפולימר 14 ס"מ', 185.0, NULL, 'UK41139', 'instock', NULL, 'https://deyidkzuvwniioxjisdr.supabase.co/storage/v1/object/public/product-images/opt/0d4e85ef1f59ddb8c903cf4e.webp', true, '2026-06-04T09:45:20.152765+00:00', '2026-07-12T17:37:09.833485+00:00'),
  ('efa03985-b1fb-40b2-ae17-afe03f030bb0', NULL, 'product-3', 'סידור מעוצב ברכת הכהנים לגבר צבע חום עתיק', '<p>העניקו או קבלו מתנה בעלת משמעות עמוקה עם סידור ברכת הכהנים המעוצב שלנו. בגוון חום עתיק, הוא משלב יופי קלאסי עם קדושה, ומביא את ברכת הכהנים המפורסמת בצורה מכובדת ואמנותית. הסידור עשוי מחומרים איכותיים, הניכרת במגע ובעמידות, ומעוצב כך שישתלב באופן הרמוני בכל בית או בית כנסת. זוהי מתנה שתעורר הערכה ותשמש מקור השראה רוחני לאורך שנים.</p>', 'סידור ברכת הכהנים לגבר בעיצוב עתיק בגוון חום. מתנה יוקרתית ומרגשת לתת או לקבל.', 186.0, NULL, NULL, 'instock', NULL, 'https://deyidkzuvwniioxjisdr.supabase.co/storage/v1/object/public/product-images/opt/10d5ecf5cb622313d7ac4ebd.webp', true, '2026-05-31T11:04:26.373999+00:00', '2026-07-12T17:37:12.075018+00:00'),
  ('efe9568d-b154-403f-8c10-2e583b0ed2f0', NULL, 'product-15', 'סידור מעוצב האש שלי לגבר קורדרוי אפור כהה', '<p>הציגו את סידור התפילה ''האש שלי'' – מתנה מושלמת לגבר המודרני, המשלבת יראת שמיים עם שיק עיצובי. מגיע בבד קורדרוי אפור כהה ורך למגע, המעניק תחושה יוקרתית ונעימה. כל פרט עוצב בקפידה, מתוך מחשבה להפוך את רגע התפילה לחוויה שלווה ומכובדת. הסידור כולל את כל התפילות הדרושות, כתובות באותיות ברורות וקריאות, ומעוצב באופן נגיש ונוח לשימוש. זוהי דרך נפלאה לחבר בין עולם הרוח והנצח לבין העידון העכשווי.</p>', 'סידור תפילה ''האש שלי'' לגבר – אלגנטיות פוגשת קדושה. עיצוב קורדרוי אפור כהה, מחומרים איכותיים, לחוויית תפילה מרוממת.', 186.0, NULL, NULL, 'instock', NULL, 'https://deyidkzuvwniioxjisdr.supabase.co/storage/v1/object/public/product-images/opt/215579d4a2cf10886c5a7e94.webp', true, '2026-05-31T11:04:26.373999+00:00', '2026-07-12T17:37:14.454699+00:00'),
  ('f00cde3a-1ccf-4ad4-8560-20bd25247ab7', 2871338, 'talit-2871338', 'טלית דגם כתר', '<p>הטלית ''כתר'' היא ביטוי של פאר והדר, המשלבת עיצוב מלכותי עם איכות בלתי מתפשרת. עשויה מבדי משי נקיים המשווים לה מגע רך ויוקרתי, היא תלווה את תפילותיכם בקדושה וביופי. ה''כתר'' המעוצב להפליא על צווארון הטלית מוסיף לה נופך של הוד מלכותי, והופך אותה למתנה מושלמת לכל אירוע משמעותי. חוויה של רוחניות ואסתטיקה בכל שימוש.</p>', 'טלית יוקרתית ''כתר'' – עיצוב מלכותי ומרהיב, עשויה מבדי משי איכותיים.', 571.43, 350.0, NULL, 'instock', NULL, 'https://deyidkzuvwniioxjisdr.supabase.co/storage/v1/object/public/product-images/opt/ef47c4412acaf5786a67910d.webp', true, '2026-05-31T11:10:09.145533+00:00', '2026-07-12T17:37:16.690374+00:00'),
