  ('f5009850-86db-49ac-8fbb-ee56c7a6ff2d', 2874406, 'chal-2874406', 'סט חלאקה קלאסי דגם מגן דוד רקמה זהב וחריטה על המספרים', '<p>ציינו את יום החלאקה בסט קלאסי ומרהיב “מגן דוד”. הסט כולל סכין מיוחדת, קערה מעוצבת, ומספרים לחריטה אישית, כולם משובצים ברקמת זהב עשירה ותיבת מגן דוד קלאסית. עשוי מהחומרים המשובחים ביותר, הסט הזה הוא לא רק כלי פרקטי ליום החשוב, אלא גם פריט יוקרתי שישמש כמזכרת משפחתית יקרת ערך לשנים רבות.</p>', 'סט חלאקה קלאסי “מגן דוד” - מזכרת יוקרתית ליום המיוחד. רקמת זהב עשירה וחריטה אישית על המספרים.', 400.0, NULL, NULL, 'instock', NULL, 'https://deyidkzuvwniioxjisdr.supabase.co/storage/v1/object/public/product-images/opt/019424676bebb1261af17753.webp', true, '2026-05-31T11:30:03.111272+00:00', '2026-07-12T17:37:21.689518+00:00'),
  ('f6b858f5-005e-44f6-9770-6469bd063b5b', NULL, 'product-37', 'סידור מעוצב כתר מובלט לגבר צבע שחור מט', '<p>סידור תפילה מעוצב זה, המיועד לגבר המודרני, משלב מסורת והדר בעיצוב ייחודי. כתר מוזהב בולט, בעל גימור שחור מט אלגנטי, מעניק נוכחות מרשימה ויוקרתית. הספר עצמו עשוי מנייר איכותי, עם סידור תפילות התואם את כל ימות השנה, והוא תפור בכריכה קשה ועמידה. יופיו המינימליסטי והאלגנטי הופכים אותו למתנה מושלמת לגברים, לבר מצווה, לימי הולדת או לכל אירוע משמעותי אחר.</p>', 'סידור תפילה מהודר לגבר, עם כתר מעוצב ומרשים בצבע שחור מט. מתנה יוקרתית לכל אירוע.', 186.0, NULL, NULL, 'instock', NULL, 'https://deyidkzuvwniioxjisdr.supabase.co/storage/v1/object/public/product-images/opt/432e54e4dabcddd235396ec6.webp', true, '2026-05-31T11:04:26.373999+00:00', '2026-07-12T17:37:15.158362+00:00'),
  ('f766b777-bb1b-4329-8494-6fe96f6e5e3d', 2245, 'מזוזה-לבנה-מפלסטיק-12-סמ-עם-פקק-גומי', 'מזוזה לבנה מפלסטיק 12 ס"מ עם פקק גומי', '<p>הוסיפו נגיעה של קדושה לכל פינה בבית עם מזוזה לבנה וצנועה זו. עשויה מפלסטיק עמיד ונעימה למגע, בגודל אידיאלי של 12 ס"מ, היא משתלבת בקלות בכל דלת. הפקק גומי מבטיח שהמגילה תישאר מוגנת ושלמה. זוהי בחירה מצוינת למתנה חמה או לשדרוג ביתי, המעניקה תחושת שלווה וברכה.</p>', 'מזוזה לבנה ופשוטה, 12 ס"מ, עשויה פלסטיק איכותי עם פקק גומי. מתנה מושלמת לבית חדש או כתוספת צנועה לחללים קיימים.', 26.0, 21.98, 'UK22538', 'instock', NULL, 'https://deyidkzuvwniioxjisdr.supabase.co/storage/v1/object/public/product-images/opt/642ae7109d16b0b75b2a95a4.webp', true, '2026-05-10T16:10:19.018791+00:00', '2026-07-12T17:37:20.792463+00:00'),
  ('f7db28ac-4f43-47f2-96f6-31c32ee38df3', 2158, 'חנוכייה-מקריסטל-מהודרת-21-סמ-חבד', 'חנוכייה מקריסטל מהודרת 21 ס"מ - חב"ד', '<p>האירו את חג החנוכה באור יקרות עם חנוכייה מרהיבה זו, עשויה קריסטל איכותי ומעוצבת בקו נקי ומכובד. גודלה האידיאלי (21 ס"מ) הופך אותה למרשימה על כל שולחן, והיא משלבת מסורת עם עידון מודרני, בהתאם לסגנון האלגנטי של חב"ד. מתנה מושלמת לבית, לחג ולאורך שנים.</p>', 'חנוכייה מהודרת קריסטל 21 ס"מ - חב"ד. עיצוב קלאסי ואלגנטי להדלקת נרות חנוכה.', 264.0, 219.98, 'UK42200', 'instock', NULL, 'https://deyidkzuvwniioxjisdr.supabase.co/storage/v1/object/public/product-images/opt/2d543d51a6e514b9ff7df66a.webp', true, '2026-05-10T16:10:19.018791+00:00', '2026-07-12T17:37:20.581521+00:00'),
  ('f8030579-6722-4a47-bc8b-72ddab70eda5', 2874420, 'chal-2874420', 'סט חלאקה פרימיום דגם האש שלי רקמה בכסף', '<p>הפכו את טקס החלאקה לחוויה בלתי נשכחת עם סט "האש שלי". כל פריט מעוצב בקפידה, משלב רקמת כסף אמיתית המנצנצת בעדינות, ויוצר אווירה של קדושה ושמחה. הסט כולל את כל הדרוש לטקס מושלם, מחומרי גלם איכותיים המבטיחים עמידות ויוקרה. תנו לילדכם להתחיל את דרכו בעולם עם ברכה מיוחדת, כשהזיכרון הזה נחרט בליבכם לנצח.</p>', 'חלאקה קסומה - סט פרימיום "האש שלי", רקום בכסף טהור, ליצירת זיכרון נצחי.', 586.0, NULL, NULL, 'instock', NULL, 'https://deyidkzuvwniioxjisdr.supabase.co/storage/v1/object/public/product-images/opt/a6b353dac8dd42cf91314567.webp', true, '2026-05-31T11:28:50.557064+00:00', '2026-07-12T17:37:21.949119+00:00'),
  ('f8ec0ae2-835e-4027-860e-ccd9a9f3062a', 2241, 'מזוזה-מפלסטיק-עם-פקק-גומי-12-סמ-נושא-ירוש', 'מזוזה מפלסטיק עם פקק גומי 12 ס"מ - נושא ירושלים בצבע כסף', '<p>הוסיפו מגע של קדושה ויופי לביתכם עם מזוזת פלסטיק מעוצבת זו, בגודל 12 ס"מ. המזוזה מציגה עיטור מושקע של נופי ירושלים האהובה, בצבע כסף נוצץ שיתאים לכל עיצוב. עשויה מחומרים איכותיים ועמידים, עם פקק גומי אטום המגן על הקלף. היא אינה רק אביזר יודאיקה מרשים, אלא גם תזכורת יומיומית לקשר המיוחד לירושלים. מתנה נפלאה לכל בית יהודי.</p>', 'מזוזה מעוצבת עם נוף ירושלים, עשויה פלסטיק עמיד בצבע כסף אלגנטי. מתנה מושלמת וקישוט מושך לכל דלת.', 29.0, 23.98, 'UK22540', 'instock', NULL, 'https://deyidkzuvwniioxjisdr.supabase.co/storage/v1/object/public/product-images/opt/48134fd7d724954dc374736b.webp', true, '2026-05-10T16:10:19.018791+00:00', '2026-07-12T17:37:19.083198+00:00'),
  ('f9a57419-d46d-4fc7-a359-390ddfae09fd', NULL, 'product-31', 'סידור כתר לגבר אפור הטבעה בכסף', '<p>סידור תפילה "כתר" לגבר, בעיצוב אפור מודרני ויוקרתי, המשדר רוגע וכבוד. העיטור המרכזי של הטבעת כסף אמיתית מוסיף נגיעה של אלגנטיות וייחודיות, ומסמל את קדושת התפילה. הסידור כולל את כל התפילות ליום יום, ראש חודש ושבת, בנוסח עדות מזרח, והוא עשוי מנייר איכותי ועמיד. מתנה מושלמת ומרגשת לגבר שלך, שתלווה אותו בכל תפילה.</p>', 'סידור כתר לגבר - עיצוב אפור קלאסי עם הטבעת כסף עדינה. מושלם לתפילה יומיומית.', 186.0, NULL, NULL, 'instock', NULL, 'https://deyidkzuvwniioxjisdr.supabase.co/storage/v1/object/public/product-images/opt/92693f2beb4bd5de9e490480.webp', true, '2026-05-31T11:04:26.373999+00:00', '2026-07-12T17:37:14.969207+00:00'),
