  ('fba9d888-f3ea-4be5-ac3d-88a43aa1af95', NULL, 'כיסוי-חלה-מהודר-דמוי-עור-pv-לבן-קידוש-42x52-סמ-66319', 'כיסוי חלה מהודר דמוי עור + PV לבן "קידוש" 42x52 ס"מ', NULL, 'כיסוי חלה מהודר דמוי עור + PV לבן "קידוש" 42x52 ס"מ', 270.0, NULL, 'UK66319', 'instock', NULL, 'https://deyidkzuvwniioxjisdr.supabase.co/storage/v1/object/public/product-images/opt/486f47510aa0f21564fcfa4f.webp', true, '2026-06-04T09:45:14.748606+00:00', '2026-07-12T17:37:08.310442+00:00'),
  ('fbca8565-97cb-43f6-9262-6c7ef616a1e5', 2872413, 'chal-2872413', 'סט חלאקה פרימיום דגם פרי רקמה בתכלת', '<p>ערכו לכם טקס חלאקה בלתי נשכח עם סט פרימיום "פרי רקמה" המעוצב בתכלת עדין. הסט כולל את כל מה שנדרש לרגע המיוחד, עשוי מחומרים איכותיים ומעוטר ברקמה עשירה שתהפוך את האירוע למזכר יפהפה לשנים רבות. מתנה מושלמת לציון המעבר החשוב בחיי הילד.</p>', 'סט חלאקה פרימיום "פרי רקמה" בתכלת - מתנה יוקרתית לבר מצווה.', 586.0, NULL, NULL, 'instock', NULL, 'https://deyidkzuvwniioxjisdr.supabase.co/storage/v1/object/public/product-images/opt/67311e28aea33912d078547c.webp', true, '2026-05-31T11:30:03.111272+00:00', '2026-07-12T17:37:07.362383+00:00'),
  ('fbe1b67c-012c-412b-9428-27e8a02f1d96', NULL, 'artj-uk67109', 'תיק מפואר לטלית גדול תפילין עם ידית 31X41 ס"מ', '<p>קחו את התפילין והטלית שלכם בכל מקום בסטייל ובביטחון עם התיק המפואר שלנו. התיק, בגודל 31X41 ס"מ, נושא בחן ידית נוחה לנשיאה ומעוצב בקפידה כדי להגן על פריטי הקודש שלכם. עשוי מחומרים עמידים ויוקרתיים, הוא מהווה מתנה מושלמת או תוספת אישית שתשדרג כל תפילה.</p>', 'תיק תפילין וטלית מהודר, מעוצב בטוב טעם. עשוי חומרים איכותיים, ישמור על קודש הקודשים שלכם.', 400.0, NULL, 'UK67109', 'instock', NULL, 'https://deyidkzuvwniioxjisdr.supabase.co/storage/v1/object/public/product-images/opt/ccc1d2cf1baa5208d5072b55.webp', true, '2026-05-31T11:25:25.72855+00:00', '2026-07-12T17:37:21.629609+00:00'),
  ('fcc1943b-f170-43a1-8c0a-f6344ed27e47', 2871437, 'talit-2871437', 'טלית תשבץ  צמר פסים בצבע כסף  עם עטרה שחורה יוקרתית רקמת יברכך ה'' וישמרך בכסוף', '<p>התעטפו בברכה והדר עם טלית צמר משובחת זו, בעיצוב תשבץ אלגנטי ופסים מתכתיים בכסף. העטרה מבדיל איכותי, רקועה בפסוק ''יברכך ה'' וישמרך'' בכסף נוצץ, מעניקה קדושה ויוקרה לתפילה. טלית זו, עשויה צמר טבעי ונעים למגע, תלווה אתכם ברגעים הרוחניים החשובים ביותר, ותהווה מתנה מרהיבה ובעלת משמעות.</p>', 'טלית צמר יוקרתית בעיצוב תשבץ פסים כסופים, עם עטרה רקום ''יברכך ה'' וישמרך'' בכסף.', 720.0, 600.0, NULL, 'instock', NULL, 'https://deyidkzuvwniioxjisdr.supabase.co/storage/v1/object/public/product-images/opt/a77460989ab3fc7ff4bbb9c9.webp', true, '2026-05-31T11:10:09.145533+00:00', '2026-07-12T17:37:13.560663+00:00'),
  ('fd280ded-7981-4fc1-a247-1b607e664891', NULL, 'כרית-מהודרת-לברית-דמוי-עור-עם-אותיות-בולטות-74x50-סמ-דגם-2-66451', 'כרית מהודרת לברית דמוי עור עם אותיות בולטות 74x50 ס"מ (דגם 2)', NULL, 'כרית מהודרת לברית דמוי עור עם אותיות בולטות 74x50 ס"מ (דגם 2)', 428.57, NULL, 'UK66451', 'instock', NULL, 'https://deyidkzuvwniioxjisdr.supabase.co/storage/v1/object/public/product-images/opt/3f5c1a05a7d6034b12e51004.webp', true, '2026-06-04T09:45:19.256486+00:00', '2026-07-12T17:37:17.92746+00:00'),
  ('fd590331-6794-4680-9cca-d4144d104509', NULL, 'product-22', 'סידור כותל לגבר שחור הטבעה בזהב', '<p>סידור כותל מרהיב זה, המיועד לגברים, משלב עיצוב אלגנטי ויוקרתי בצבע שחור עמוק עם הטבעה מיוחדת בזהב. הסידור כולל את כל התפילות הנדרשות לתפילות היומיומיות, בנוסח מדויק, כתוב באותיות ברורות וקריאות. הכריכה השחורה המהודרת, בשילוב הזהב הנוצץ, מעניקה תחושה של קדושה והדר. עשוי מחומרים איכותיים ועמידים, סידור זה הוא פריט חובה לכל גבר שומר מצוות, המעוניין בתפילה מרוכזת ומכובדת. מתנה אידיאלית לבר מצווה, ליום הולדת או לכל אירוע משמעותי.</p>', 'סידור כותל מהודר לגבר, בעיצוב קלאסי ובולטות מוזהבת. תוספת יוקרתית ותפילה לעילא. מתנה מושלמת.', 186.0, NULL, NULL, 'instock', NULL, 'https://deyidkzuvwniioxjisdr.supabase.co/storage/v1/object/public/product-images/opt/330d0289dfa3eb5ca3f1e9f0.webp', true, '2026-05-31T11:04:26.373999+00:00', '2026-07-12T17:37:14.722909+00:00'),
  ('fdf9494b-7d32-4362-b35f-db4afd8aebe6', 2870874, 'chal-2870874', 'סט חלאקה קלאסי דגם האש שלי רקמה בזהב', '<p>חגגו את רגע החלאקה בסט "האש שלי", המשלב מסורת יופי עם עיצוב קלאסי. הסט כולל את כל הדרוש לאירוע, כשהשיא הוא הקישוט המרהיב ברקמת זהב, המוסיף נופך מלכותי לזיכרון המתוק. עשוי מחומרים איכותיים, הסט מבטיח עמידות ויופי לאורך שנים, והופך לאוצר משפחתי. תנו לילד שלכם להתחיל את דרכו בסט שכולו אהבה, מסורת וברק.</p>', 'סט "האש שלי" – חלאקה קלאסי ומרהיב, מעוטר ברקמת זהב עדינה. המתנה המושלמת לציון רגע מרגש וזיכרון יקר.', 357.0, NULL, NULL, 'instock', NULL, 'https://deyidkzuvwniioxjisdr.supabase.co/storage/v1/object/public/product-images/opt/cfcdfdd12914b60317823972.webp', true, '2026-05-31T11:30:03.111272+00:00', '2026-07-12T17:37:21.375554+00:00'),
  ('fe7cbe74-a36f-4a95-8ced-b1e487295559', NULL, 'product-54', 'סידור לבת ישראל – לבן קורדרוי', '<p>סידור תפילה "לבן קורדרוי" עוצב במיוחד עבור בת ישראל, עם דגש על עיצוב אלגנטי ורכות מלטפת. הכריכה העשויה קורדרוי לבן איכותי מעניקה תחושה יוקרתית ונעימה למגע, אידיאלית לנשיאה יומיומית או להנחה על שולחן קריאה. הסידור כולל את כל התפילות החשובות, בנוסח עדות אשכנז, מודפס על נייר משובח וברור לקריאה. זוהי מתנה מיוחדת ואישית, שתלווה את המתפללת במסעה הרוחני ותעשיר את תפילותיה.</p>', 'סידור תפילה מהודר לבת ישראל, עטוף בקטיפה לבנה רכה. המתנה המושלמת שילווה אותה בכל יום.', 186.0, NULL, NULL, 'instock', NULL, 'https://deyidkzuvwniioxjisdr.supabase.co/storage/v1/object/public/product-images/opt/afb3acfa8f6dbfac68307f26.webp', true, '2026-05-31T11:04:26.373999+00:00', '2026-07-12T17:37:15.8958+00:00'),
  ('fed0c8af-0b20-43dc-9b6a-4be124b4ea43', 2016, 'פמוטי-קריסטל-אלגנטיים-2019-סמ', 'פמוטי קריסטל אלגנטיים 20*19 ס"מ', '<p>הוסיפו נגיעה של זוהר ויוקרה לביתכם עם פמוטי הקריסטל המרהיבים הללו. בגודל אידיאלי של 20x19 ס"מ, הם משתלבים נפלא בכל פינה, משדרגים את האווירה בשולחן השבת או החג. עשויים קריסטל איכותי, הם מחזירים את אור הנרות בריקוד נוצץ שמעל הכל, יוצרים קסם מיוחד ורגעים בלתי נשכחים.</p>', 'פמוטי קריסטל מהודרים, 20x19 ס"מ. מוסיפים נצנוץ ויוקרה לכל שולחן חג ושבת.', 156.0, 129.98, 'UK42160', 'instock', NULL, 'https://deyidkzuvwniioxjisdr.supabase.co/storage/v1/object/public/product-images/opt/ce997ca0ec678eb713822d30.webp', true, '2026-05-10T16:10:19.018791+00:00', '2026-07-12T17:37:11.975909+00:00'),
  ('ff51b1d7-69ab-49b4-ba8b-e3730c29653c', NULL, 'מסגרת-נצנצים-מזכוכית-עיצוב-קווים-הדלקת-נרות-22x17-סמ-82872', 'מסגרת נצנצים מזכוכית עיצוב "קווים" הדלקת נרות 22x17 ס"מ', NULL, 'מסגרת נצנצים מזכוכית עיצוב "קווים" הדלקת נרות 22x17 ס"מ', 113.0, NULL, 'UK82872', 'instock', NULL, 'https://deyidkzuvwniioxjisdr.supabase.co/storage/v1/object/public/product-images/opt/9902a56f67cb397bc9aeadd5.webp', true, '2026-06-04T09:45:16.070462+00:00', '2026-07-12T17:37:18.625932+00:00'),
  ('ff8d77db-71c5-4e86-93a5-e3c3bdf082dc', 2871959, 'talit-2871959', 'טלית פרימיום תשבץ  100% צמר רחלים דגם יברכך עטרה ופינות רקומות בצבע שחור', '<p>טלית יוקרתית זו, עשויה 100% צמר רחלים משובח, מציעה חוויה רוחנית עשירה. עיטורי "יברכך" רקומים בעבודת יד על העטרה והפינות בצבע שחור אלגנטי מוסיפים נופך של קדושה וחגיגיות. בד התשבץ האיכותי והרכות הטבעית של הצמר מבטיחים נוחות מרבית ותחושת שייכות מחזקת בכל תפילה. מתנה מושלמת ופריט יקר ערך לכל בית.</p>', 'טלית פרימיום תשבץ, 100% צמר רחלים - עטרה ופינות רקומות "יברכך" בשחור. יוקרה לארון הקודש.', 786.0, NULL, NULL, 'instock', NULL, 'https://deyidkzuvwniioxjisdr.supabase.co/storage/v1/object/public/product-images/opt/dc0d05e159eea92b071880fd.webp', true, '2026-05-31T11:10:09.145533+00:00', '2026-07-12T17:37:16.981495+00:00')
